INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”（kǎn）指用斧、刀猛力把物体断开。"}, {"text": "看", "is_correct": false, "explanation": "kàn（第四声）与 kǎn（第三声）声调不同，意思是看。"}, {"text": "赶", "is_correct": false, "explanation": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是追赶。"}, {"text": "款", "is_correct": false, "explanation": "读音：“款”（kuǎn）与“砍”（kǎn）声调相同，只差介音 u，意思是款项，不是近义词。"}], "explanations": {"砍": "正确。“砍”（kǎn）指用斧、刀猛力把物体断开。", "看": "kàn（第四声）与 kǎn（第三声）声调不同，意思是看。", "赶": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是追赶。", "款": "读音：“款”（kuǎn）与“砍”（kǎn）声调相同，只差介音 u，意思是款项，不是近义词。"}, "sentence_index": null, "correct_answer": "砍"}, "level_3": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”指用斧、刀猛力砍断树木，与“爷爷拿着斧子去山上……树”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说在山上吃树。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲，不能说唱树。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是给人或动物吃东西，与拿斧子去山上的动作无关，句子不通。"}], "explanations": {"砍": "正确。“砍”指用斧、刀猛力砍断树木，与“爷爷拿着斧子去山上……树”相符。", "吃": "搭配：“吃”的宾语是食物，不能说在山上吃树。", "唱": "搭配：“唱”的宾语是歌曲，不能说唱树。", "喂": "语义：“喂”是给人或动物吃东西，与拿斧子去山上的动作无关，句子不通。"}, "sentence_index": 0, "correct_answer": "砍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她砍了一朵花。", "explanation": "这里应该用〈摘〉。摘花是用手采下，砍是用刀斧猛力切断，不能这样用。"}, {"text": "裁缝用斧子砍下了一块布。", "explanation": "这里应该用〈裁〉。裁布是按尺寸剪下布料，砍是用斧刀猛力断开物体，用斧子砍布不是裁布的说法。"}, {"text": "工人砍了一个坑。", "explanation": "这里应该用〈挖〉。挖坑要靠挖掘，砍是切断，不能用来形成坑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”（kǎn）指用斧、刀猛力把物体断开。"}, {"text": "敢", "is_correct": false, "explanation": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是敢。"}, {"text": "刊", "is_correct": false, "explanation": "kān（第一声）与 kǎn（第三声）声调不同，意思是刊登。"}, {"text": "感", "is_correct": false, "explanation": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是感觉。"}], "explanations": {"砍": "正确。“砍”（kǎn）指用斧、刀猛力把物体断开。", "敢": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是敢。", "刊": "kān（第一声）与 kǎn（第三声）声调不同，意思是刊登。", "感": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是感觉。"}, "sentence_index": null, "correct_answer": "砍"}, "level_3": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”指用斧、刀断开树木，与“我从来没……过树”相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的宾语是食物，不能说煮过树。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”的宾语是布料或毛线，与“树”搭配不通。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是用火加热食物，与砍树的行为毫无关系。"}], "explanations": {"砍": "正确。“砍”指用斧、刀断开树木，与“我从来没……过树”相符。", "煮": "搭配：“煮”的宾语是食物，不能说煮过树。", "织": "搭配：“织”的宾语是布料或毛线，与“树”搭配不通。", "烤": "语义：“烤”是用火加热食物，与砍树的行为毫无关系。"}, "sentence_index": 6, "correct_answer": "砍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手砍了那棵老树。", "explanation": "这里不能用砍。砍必须借助刀斧等有刃工具，徒手不能砍；徒手可以掰断或折断细枝，但不能说“用手砍”。"}, {"text": "他不小心砍碎了碗。", "explanation": "这里应该用〈摔〉。碗是摔碎的，不是砍碎的；砍用于有刃工具猛力切断。"}, {"text": "妈妈砍掉了衣服的袖子。", "explanation": "这里应该用〈剪〉。裁剪衣服要用剪刀，砍是用刀斧猛力切断，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年砍了过三棵老树。", "corrected_sentence": "他去年砍过三棵老树。", "error_description": "体标错误：“过”表示经历，动词后用了“过”就不能再加“了”，“了”与“过”不能同时用在“砍”后。正确说法是“他去年砍过三棵老树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用斧子把竹子砍了倒。", "corrected_sentence": "他用斧子把竹子砍倒了。", "error_description": "补语位置错误：结果补语“倒”必须紧跟动词，不能放在“了”之后。正确说法是“砍倒了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "购买", "is_correct": true, "explanation": "正确。“出售”是卖出，“购买”是买入，二者互为反义。"}, {"text": "保存", "is_correct": false, "explanation": "“保存”指留存，与“出售”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏的东西，与“出售”没有反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "“种植”指栽培作物，与“出售”没有反义关系。"}], "correct_answer": "购买", "explanations": {"购买": "正确。“出售”是卖出，“购买”是买入，二者互为反义。", "保存": "“保存”指留存，与“出售”没有反义关系。", "修理": "“修理”指修复损坏的东西，与“出售”没有反义关系。", "种植": "“种植”指栽培作物，与“出售”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "购买", "is_correct": true, "explanation": "正确。“出售”是卖出，“购买”是买入，二者互为反义。"}, {"text": "洗涤", "is_correct": false, "explanation": "“洗涤”指清洗，与“出售”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意行走，与“出售”没有反义关系。"}, {"text": "测量", "is_correct": false, "explanation": "“测量”指量取尺寸，与“出售”没有反义关系。"}], "correct_answer": "购买", "explanations": {"购买": "正确。“出售”是卖出，“购买”是买入，二者互为反义。", "洗涤": "“洗涤”指清洗，与“出售”没有反义关系。", "散步": "“散步”指随意行走，与“出售”没有反义关系。", "测量": "“测量”指量取尺寸，与“出售”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "卖出（商品等）。", "primary_collocate": null, "pronunciation": "chū shòu", "ipa": "ʈʂʰu˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家商店出售各种新鲜水果。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出售自己的旧汽车。", "target_word": "出售", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书在网上出售，价格不贵。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店明天开始出售新手机。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些旧家具已经出售了。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里出售的牛奶都很新鲜。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的房子出售了。", "target_word": "出售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不出售香烟，请去别的店买。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年夏天，他出售过一批蔬菜。", "target_word": "出售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这种茶叶只出售给老客人。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出售了", "label": "完成体"}, {"form": "出售过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "把商品卖出去，多用于商店、网络等场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '476a3295-ccc1-45f7-ab1b-c537dc3fa42a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "采摘", "is_correct": false, "explanation": "语义：采摘是从植株上摘下，商店不会采摘水果，与句意不符。"}, {"text": "出售", "is_correct": true, "explanation": "正确。商店把各种新鲜水果卖出去，与句意相符。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：品尝是尝味道，与商店经营的语境不符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的宾语须是地点或展览，不能接“新鲜水果”。"}], "explanations": {"采摘": "语义：采摘是从植株上摘下，商店不会采摘水果，与句意不符。", "出售": "正确。商店把各种新鲜水果卖出去，与句意相符。", "品尝": "语义：品尝是尝味道，与商店经营的语境不符。", "参观": "搭配：“参观”的宾语须是地点或展览，不能接“新鲜水果”。"}, "sentence_index": 0, "correct_answer": "出售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商店今天免费出售新手机。", "explanation": "这里应该用〈赠送〉。“出售”是卖出并收钱，与“免费”矛盾。"}, {"text": "这套房子出售给学生，每月要交一次房租。", "explanation": "这里应该用〈出租〉。“出售”是一次性卖断，与“每月交房租”矛盾。"}, {"text": "他弄坏了邻居的窗户，所以出售了损失。", "explanation": "这里应该用〈赔偿〉。“出售”的宾语是商品，损失不能出售，应说“赔偿了损失”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：房子不能吃，“吃了房子”句意不通。"}, {"text": "出售", "is_correct": true, "explanation": "正确。“出售”指把房子卖出去，与“把……了”的处置语境相符。"}, {"text": "读", "is_correct": false, "explanation": "语义：房子不能阅读，与句意不符。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象一般是动物或婴儿，不能用于房子。"}], "explanations": {"吃": "语义：房子不能吃，“吃了房子”句意不通。", "出售": "正确。“出售”指把房子卖出去，与“把……了”的处置语境相符。", "读": "语义：房子不能阅读，与句意不符。", "喂": "搭配：“喂”的对象一般是动物或婴儿，不能用于房子。"}, "sentence_index": 6, "correct_answer": "出售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了钱出售了朋友。", "explanation": "这里应该用〈出卖〉。“出售”用于商品，不用于人，背叛他人应说“出卖”。"}, {"text": "我把书出售给了同学，过几天就还。", "explanation": "这里应该用〈借〉。“出售”是卖断，不会归还，与“过几天就还”矛盾。"}, {"text": "学校每年出售一次运动会。", "explanation": "这里应该用〈举办〉。运动会是活动，不是商品，不能出售。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年出售着一批手工艺品。", "corrected_sentence": "她去年出售过一批手工艺品。", "error_description": "体标记错误。表示去年已经发生过的经历要用“过”，“着”表示持续状态，不能用于此句。应为“出售过一批”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这辆旧摩托出售了给同事。", "corrected_sentence": "他把这辆旧摩托出售给了同事。", "error_description": "“给”与“了”的位置错误。“给”应紧跟动词“出售”，“了”应放在“给”之后，应为“出售给了同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
