INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91563, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多科学家一起做研究的大地方。", "primary_collocate": null, "pronunciation": "kē xué yuàn", "ipa": "kʰɤ˥ ɕɥe˧˥ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "科学院里有很多大楼。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个科学院离我家很近。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们参观了一个科学院。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学院里的人都在做研究。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学院的花园又大又安静。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天坐车去科学院上班。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个科学院有一千多位科学家。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学院门口有很多人在排队。", "target_word": "科学院", "complexity_tier": "T3", "furigana": "kē xué yuàn", "sentence_source": "generated"}, {"text": "科学院里面有很多实验室。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，爸爸带我去科学院看看。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科學院", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "科学院：科学家一起做研究的大地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老师", "is_correct": false, "explanation": "语义：“老师”指人，不是能容纳“很多大楼”的处所，句子不通。"}, {"text": "科学院", "is_correct": true, "explanation": "正确：科学院是科研机构，里面可以有很多大楼，“里”前接处所名词。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是供人休闲的地方，里面不会有很多大楼。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：厨房里通常说有灶台、锅碗，不与“很多大楼”搭配。"}], "explanations": {"老师": "语义：“老师”指人，不是能容纳“很多大楼”的处所，句子不通。", "科学院": "正确：科学院是科研机构，里面可以有很多大楼，“里”前接处所名词。", "花园": "语义：花园是供人休闲的地方，里面不会有很多大楼。", "厨房": "搭配：厨房里通常说有灶台、锅碗，不与“很多大楼”搭配。"}, "sentence_index": 0, "correct_answer": "科学院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月都去科学院取钱。", "explanation": "这里应该用〈银行〉。取钱要去银行，科学院是科研机构，不办理存取款业务。"}, {"text": "孩子们每天都去科学院上课。", "explanation": "这里应该用〈学校〉。科学院是科研机构，不是供学生上课的地方，“上课”的场所要用学校。"}, {"text": "他是一位很有名的科学院。", "explanation": "误把机构当人：科学院指机构，说人应用〈院士〉或〈研究员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是机构，不可能“有一千多位科学家”。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“一千多位科学家”说的是研究人员的集体，公园不作这样的主体。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是餐饮场所，不会有一千多位科学家在此工作。"}, {"text": "科学院", "is_correct": true, "explanation": "正确：科学院是科研机构，可以有一千多位科学家在此工作，与“这个”搭配。"}], "explanations": {"面包": "语义：面包是食物，不是机构，不可能“有一千多位科学家”。", "公园": "搭配：“一千多位科学家”说的是研究人员的集体，公园不作这样的主体。", "饭馆": "语义：饭馆是餐饮场所，不会有一千多位科学家在此工作。", "科学院": "正确：科学院是科研机构，可以有一千多位科学家在此工作，与“这个”搭配。"}, "sentence_index": 6, "correct_answer": "科学院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈每周去科学院看病。", "explanation": "这里应该用〈医院〉。科学院是科研机构，不接待病人，看病要去医院。"}, {"text": "我们周末去科学院坐飞机。", "explanation": "这里应该用〈机场〉。科学院是科研机构，不是飞机起降的地方，坐飞机要去机场。"}, {"text": "我要去科学院办签证。", "explanation": "这里应该用〈大使馆〉。科学院不办理签证，办签证要去大使馆或领事馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那本科学院是新建的。", "corrected_sentence": "那所科学院是新建的。", "error_description": "量词错误：“本”只用于书籍等，不能用于机构；这里应说“那所科学院”或“那个科学院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他走进科学院的，找了一位老师。", "corrected_sentence": "他走进科学院，找了一位老师。", "error_description": "错误：“科学院”后面多加了“的”。正确：“走进科学院”后直接接逗号，“的”不能附在处所名词后作句中的停顿。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
