INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91569, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从坐着变成站着。", "primary_collocate": null, "pronunciation": "zhàn qǐ", "ipa": "ʈʂan˥˩ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师进来，大家都站起来了。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从椅子上站起，走向门口。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到名字，她马上站起来。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "他慢慢站起来，看了看窗外。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩从沙发上站起，跑了出去。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人一进门，爷爷就站起来。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家站起来，一起唱国歌。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "他坐了很久，才站起来去喝水。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "她笑着站起，给我倒了茶。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束，所有人都站起来。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "站起来", "label": "复合"}, {"form": "站起身", "label": "复合"}], "register": "中性", "sense_fingerprint": "站起：从坐着变成站着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91569, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站起", "is_correct": true, "explanation": "正确：“大家都站起来了”符合“都……来了”的结构，与“老师进来”的场景相合。"}, {"text": "躺下", "is_correct": false, "explanation": "语义：“躺下”指卧倒，与“老师进来，大家都……”的场景不符。"}, {"text": "冒起", "is_correct": false, "explanation": "搭配：“冒起来”搭配烟、火等，不搭配“大家”。"}, {"text": "飞起", "is_correct": false, "explanation": "语义：人不会在屋里“飞起来”，与“老师进来”的场景不符。"}], "explanations": {"站起": "正确：“大家都站起来了”符合“都……来了”的结构，与“老师进来”的场景相合。", "躺下": "语义：“躺下”指卧倒，与“老师进来，大家都……”的场景不符。", "冒起": "搭配：“冒起来”搭配烟、火等，不搭配“大家”。", "飞起": "语义：人不会在屋里“飞起来”，与“老师进来”的场景不符。"}, "sentence_index": 0, "correct_answer": "站起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们让那根歪了的电线杆站起来。", "explanation": "这里应该用〈竖起〉。“站起来”只用于人或动物自己从坐、蹲、卧变为直立，竖直的物体要说“竖起”。"}, {"text": "这块木板突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，木板不能自己站起来，这里应该用〈竖起〉。"}, {"text": "这块石头突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，石头不能自己站起来，这里应该用〈竖起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91569, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站起", "is_correct": true, "explanation": "正确：“站起来”表示起立，与“一起唱国歌”的场合相合。"}, {"text": "蹲下", "is_correct": false, "explanation": "语义：“蹲下”是屈膝低身，与“一起唱国歌”的站立场合不符。"}, {"text": "倒下", "is_correct": false, "explanation": "语义：“倒下”指跌倒躺下，与“一起唱国歌”的站立场合不合。"}, {"text": "跪下", "is_correct": false, "explanation": "语域：“跪下”带有屈从或仪式性很强的色彩，与“唱国歌”的郑重场合不协调。"}], "explanations": {"站起": "正确：“站起来”表示起立，与“一起唱国歌”的场合相合。", "蹲下": "语义：“蹲下”是屈膝低身，与“一起唱国歌”的站立场合不符。", "倒下": "语义：“倒下”指跌倒躺下，与“一起唱国歌”的站立场合不合。", "跪下": "语域：“跪下”带有屈从或仪式性很强的色彩，与“唱国歌”的郑重场合不协调。"}, "sentence_index": 6, "correct_answer": "站起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只木箱突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，木箱不能自己站起来，这里应该用〈竖起〉。"}, {"text": "这把椅子突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，椅子不能站起来。"}, {"text": "这卷地毯突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，地毯不能自己站起来，这里应该用〈竖起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈听到电话，立刻站起来了接。", "corrected_sentence": "妈妈听到电话，立刻站起来接。", "error_description": "体标错误：“站起来”后不能插入“了”再接动词，应说“立刻站起来接”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶从沙发上站起去，走向厨房。", "corrected_sentence": "奶奶从沙发上站起来，走向厨房。", "error_description": "趋向补语错误：“站起”后应接“来”，不能接“去”，应说“站起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
