INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由坐、蹲、卧的姿势变为直立。", "primary_collocate": null, "pronunciation": "zhàn qǐ", "ipa": "ʈʂan˥˩ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他蹲了很久，站起来时腿很麻。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗躺在地上，听到声音就站起来。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我蹲在花园里，站起来看了看。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "她从地上站起，拍了拍裤子。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人躺了三天，今天终于站起来了。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子蹲着玩，妈妈让他站起来吃饭。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "他从床上站起来，打开了灯。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "蹲着看书的女孩站起来了。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫趴着睡觉，听到门响就站起来跑开了。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "老人躺在床上，想自己站起来。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "站起来", "label": "复合"}, {"form": "站起身", "label": "复合"}], "register": "中性", "sense_fingerprint": "站起：由坐、蹲、卧变为直立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2beb4a87-1356-4fca-8f26-67e841f14fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站起", "is_correct": true, "explanation": "正确：“站起来”指由蹲变为直立，与“蹲了很久”前后相承。"}, {"text": "挂起", "is_correct": false, "explanation": "搭配：“挂起”指悬挂，人的身体不说“挂起来”。"}, {"text": "摔下", "is_correct": false, "explanation": "语义：摔下指跌倒受伤，与“蹲了很久”后的起身动作不符。"}, {"text": "翻起", "is_correct": false, "explanation": "配价：“翻起”需带宾语（如“土”“书页”），不能只用于人自身的动作。"}], "explanations": {"站起": "正确：“站起来”指由蹲变为直立，与“蹲了很久”前后相承。", "挂起": "搭配：“挂起”指悬挂，人的身体不说“挂起来”。", "摔下": "语义：摔下指跌倒受伤，与“蹲了很久”后的起身动作不符。", "翻起": "配价：“翻起”需带宾语（如“土”“书页”），不能只用于人自身的动作。"}, "sentence_index": 0, "correct_answer": "站起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们让那根歪了的电线杆站起来。", "explanation": "这里应该用〈竖起〉。“站起来”只用于人或动物自己从坐、蹲、卧变为直立，竖直的物体要说“竖起”。"}, {"text": "这张桌子突然站起来了。", "explanation": "误用：“站起来”只用于能自主动作的人或动物，桌子不能站起来。"}, {"text": "这块石头突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，石头不能自己站起来，这里应该用〈竖起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站起", "is_correct": true, "explanation": "正确：“站起来”指从床上变为直立，与“从床上”相合。"}, {"text": "脱下", "is_correct": false, "explanation": "配价：“脱下”需带宾语（如“衣服”），不能只说“从床上脱下来”。"}, {"text": "升起", "is_correct": false, "explanation": "语义：“升起”多指太阳、旗子等，人不说“升起来”。"}, {"text": "扶起", "is_correct": false, "explanation": "配价：“扶起”需带受事宾语（如“老人”），不能用于“他从床上扶起来”。"}], "explanations": {"站起": "正确：“站起来”指从床上变为直立，与“从床上”相合。", "脱下": "配价：“脱下”需带宾语（如“衣服”），不能只说“从床上脱下来”。", "升起": "语义：“升起”多指太阳、旗子等，人不说“升起来”。", "扶起": "配价：“扶起”需带受事宾语（如“老人”），不能用于“他从床上扶起来”。"}, "sentence_index": 6, "correct_answer": "站起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这扇门突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，门不能自己站起来，这里应该用〈竖起〉。"}, {"text": "这盏灯突然站起来了。", "explanation": "误用：“站起来”只用于能自主动作的人或动物，灯不能站起来。"}, {"text": "这只箱子突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，箱子不能自己站起来，这里应该用〈竖起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在桌边坐了很久，终于站起起来。", "corrected_sentence": "她在桌边坐了很久，终于站起来。", "error_description": "重复错误：“站起来”中的“起”不能重复，应说“终于站起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人慢慢从床边站起去，走向窗口。", "corrected_sentence": "老人慢慢从床边站起来，走向窗口。", "error_description": "趋向补语错误：“站起”后应接“来”，不能接“去”，应说“站起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d4fb7c7-c4d7-4384-a5f5-f3ca08593168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
