INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "升是慢慢地往上走。", "primary_collocate": null, "pronunciation": "shēng", "ipa": "ʂɤŋ˥", "syllable_count": 1, "sentences": [{"text": "太阳慢慢升上了山顶。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气球慢慢升到了空中。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国旗在歌声中升起。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "月亮从海面升上来。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "烟从屋顶慢慢往上升。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电梯升到了十楼。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机升得很高，我们看不见了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着太阳慢慢升上天空。", "target_word": "升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭从地面升向天空。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看，月亮已经升起来了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升了", "label": "完成体"}, {"form": "升起", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体缓缓向上移动，如太阳、气球、国旗上升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '476a3295-ccc1-45f7-ab1b-c537dc3fa42a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升", "is_correct": true, "explanation": "升（shēng）：慢慢地往上走，如太阳、气球上升。"}, {"text": "省", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是节约、省去，不是往上走。"}, {"text": "胜", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是胜利、超过。"}, {"text": "深", "is_correct": false, "explanation": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是深浅的深。"}, {"text": "神", "is_correct": false, "explanation": "shén 与 shēng 韵母不同（-en 与 -eng），意思是神灵、精神。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}], "explanations": {"升": "升（shēng）：慢慢地往上走，如太阳、气球上升。", "省": "shěng（第三声）与 shēng（第一声）声调不同，意思是节约、省去，不是往上走。", "胜": "shèng（第四声）与 shēng（第一声）声调不同，意思是胜利、超过。", "深": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是深浅的深。", "神": "shén 与 shēng 韵母不同（-en 与 -eng），意思是神灵、精神。", "绳": "shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}, "sentence_index": null, "correct_answer": "升"}, "level_3": {"options": [{"text": "降", "is_correct": false, "explanation": "语义：“降”是向下，与“慢慢……上了山顶”的方向相反。"}, {"text": "升", "is_correct": true, "explanation": "升：向上移动，与“慢慢……上了山顶”相合。"}, {"text": "沉", "is_correct": false, "explanation": "语义：“沉”指向下落，不能说太阳“沉上了山顶”。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象通常是可以拿起的物品，不能说太阳被“搬”上山顶。"}], "explanations": {"降": "语义：“降”是向下，与“慢慢……上了山顶”的方向相反。", "升": "升：向上移动，与“慢慢……上了山顶”相合。", "沉": "语义：“沉”指向下落，不能说太阳“沉上了山顶”。", "搬": "搭配：“搬”的对象通常是可以拿起的物品，不能说太阳被“搬”上山顶。"}, "sentence_index": 0, "correct_answer": "升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳从海面升下去了。", "explanation": "这里应该用〈落〉。升指向上移动，太阳向下落到海面以下要用落。"}, {"text": "他慢慢升上了楼梯。", "explanation": "这里应该用〈走〉。升指太阳、气球等物体自己向上移动，人沿楼梯上去要用走。"}, {"text": "苹果从树上升下来了。", "explanation": "这里应该用〈掉〉。升指向上移动，苹果往下落要用掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升", "is_correct": true, "explanation": "升（shēng）：慢慢地往上走，如太阳、气球上升。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 shēng 韵母不同（-ang 与 -eng），意思是受伤。"}, {"text": "身", "is_correct": false, "explanation": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是身体。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh 与 sh），意思是争夺。"}, {"text": "剩", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}], "explanations": {"升": "升（shēng）：慢慢地往上走，如太阳、气球上升。", "伤": "shāng 与 shēng 韵母不同（-ang 与 -eng），意思是受伤。", "身": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是身体。", "争": "zhēng 与 shēng 声母不同（zh 与 sh），意思是争夺。", "剩": "shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}, "sentence_index": null, "correct_answer": "升"}, "level_3": {"options": [{"text": "跑", "is_correct": false, "explanation": "搭配：“跑”指用腿或车辆在地面快速移动，不能说飞机“跑得很高”。"}, {"text": "升", "is_correct": true, "explanation": "升：向上飞，与“很高”和“看不见了”相合。"}, {"text": "降", "is_correct": false, "explanation": "语义：“降”是向下，与“很高”的方向相反。"}, {"text": "跌", "is_correct": false, "explanation": "语义：“跌”指失足或下落，与飞机飞得很高矛盾。"}], "explanations": {"跑": "搭配：“跑”指用腿或车辆在地面快速移动，不能说飞机“跑得很高”。", "升": "升：向上飞，与“很高”和“看不见了”相合。", "降": "语义：“降”是向下，与“很高”的方向相反。", "跌": "语义：“跌”指失足或下落，与飞机飞得很高矛盾。"}, "sentence_index": 6, "correct_answer": "升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把信升上了楼。", "explanation": "这里应该用〈送〉。升指物体自己往上移动，把信送上楼要用送，不能用升。"}, {"text": "蜗牛慢慢升上了墙。", "explanation": "这里应该用〈爬〉。升不指靠身体一点点攀登，蜗牛自己爬行要用爬。"}, {"text": "石头升进了水里。", "explanation": "这里应该用〈沉〉。升是往上，石头往水底下去要用沉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "热气球慢慢升下了天空。", "corrected_sentence": "热气球慢慢升上了天空。", "error_description": "补语错误：“升”表示向上，应说“升上了天空”；“升下”的方向与“升”相反，不能这样说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月亮正慢慢升了着，天渐渐黑了。", "corrected_sentence": "月亮正慢慢升着，天渐渐黑了。", "error_description": "体标错误：“了”与“着”不能同时用在“升”后（“升了着”不成立）；表示动作持续只用“着”，应说“正慢慢升着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
