INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由低往高移动；提高。", "primary_collocate": null, "pronunciation": "shēng", "ipa": "ʂɤŋ˥", "syllable_count": 1, "sentences": [{"text": "今天气温升到了三十五度。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月房价又升了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今年升了一级。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水位升得很快。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油价升了，坐车也贵了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小职员升为经理。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "病人的体温升到了三十九度。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水已经升到了桥边。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工资升了不少。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们明年就升三年级了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升了", "label": "完成体"}, {"form": "升高", "label": "复合"}, {"form": "升级", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量、等级、位置等由低变高，如气温、价格、级别上升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '476a3295-ccc1-45f7-ab1b-c537dc3fa42a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升", "is_correct": true, "explanation": "升（shēng）：数量、等级由低变高，如气温、价格上升。"}, {"text": "省", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是节省。"}, {"text": "盛", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是盛大、茂盛。"}, {"text": "神", "is_correct": false, "explanation": "shén 与 shēng 韵母不同（-en 与 -eng），意思是精神、神灵。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}], "explanations": {"升": "升（shēng）：数量、等级由低变高，如气温、价格上升。", "省": "shěng（第三声）与 shēng（第一声）声调不同，意思是节省。", "盛": "shèng（第四声）与 shēng（第一声）声调不同，意思是盛大、茂盛。", "神": "shén 与 shēng 韵母不同（-en 与 -eng），意思是精神、神灵。", "绳": "shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}, "sentence_index": null, "correct_answer": "升"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”是发出歌声，不能说气温“唱到”三十五度。"}, {"text": "升", "is_correct": true, "explanation": "升：数量向上变化，气温升到三十五度，表示温度上升。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”是用笔记录文字，与气温变化无关。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于气温。"}], "explanations": {"唱": "搭配：“唱”是发出歌声，不能说气温“唱到”三十五度。", "升": "升：数量向上变化，气温升到三十五度，表示温度上升。", "写": "语义：“写”是用笔记录文字，与气温变化无关。", "吃": "搭配：“吃”的对象是食物，不能用于气温。"}, "sentence_index": 0, "correct_answer": "升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把纸箱升上了二楼，累得不行。", "explanation": "这里应该用〈搬〉。升指事物自己由低往高移动，人把纸箱搬上楼要用搬。"}, {"text": "他往杯子里升了很多水。", "explanation": "这里应该用〈倒〉。升指事物自己由低往高移动或数量增加，往杯子里注入水要用倒。"}, {"text": "我吃得太多，肚子升得难受。", "explanation": "这里应该用〈胀〉。升不能描述肚子因充满而变大，胀才表示膨胀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升", "is_correct": true, "explanation": "升（shēng）：数量、等级由低变高，如气温、价格上升。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 shēng 韵母不同（-ang 与 -eng），意思是受伤。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh 与 sh），意思是争夺。"}, {"text": "身", "is_correct": false, "explanation": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是身体。"}, {"text": "剩", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}], "explanations": {"升": "升（shēng）：数量、等级由低变高，如气温、价格上升。", "伤": "shāng 与 shēng 韵母不同（-ang 与 -eng），意思是受伤。", "争": "zhēng 与 shēng 声母不同（zh 与 sh），意思是争夺。", "身": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是身体。", "剩": "shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}, "sentence_index": null, "correct_answer": "升"}, "level_3": {"options": [{"text": "睡", "is_correct": false, "explanation": "搭配：“睡”是人的动作，不能说体温“睡到”三十九度。"}, {"text": "升", "is_correct": true, "explanation": "升：数量向上变化，体温升到三十九度，表示发烧。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中移动，与体温变化无关。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能用于体温。"}], "explanations": {"睡": "搭配：“睡”是人的动作，不能说体温“睡到”三十九度。", "升": "升：数量向上变化，体温升到三十九度，表示发烧。", "游": "语义：“游”指在水中移动，与体温变化无关。", "喝": "搭配：“喝”的对象是液体，不能用于体温。"}, "sentence_index": 6, "correct_answer": "升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把货物升上了车。", "explanation": "这里应该用〈装〉。升指事物自己由低往高移动，人把货物放上车要用装。"}, {"text": "他把钱升进了口袋。", "explanation": "这里应该用〈放〉。升指事物自己由低往高移动或数量增加，把钱放进口袋要用放。"}, {"text": "书从桌上升下来了。", "explanation": "这里应该用〈掉〉。升是向上，书往下落要用掉，与等级无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水位升在了三米。", "corrected_sentence": "水位升到了三米。", "error_description": "补语错误：表示水位升高到某个数值要用“到”，不能用“在”，应说“水位升到了三米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "油价升地很快。", "corrected_sentence": "油价升得很快。", "error_description": "补语错误：“升”后接程度补语要用“得”，不能用“地”，应说“升得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优点", "is_correct": true, "explanation": "正确：“优点”与“缺点”构成反义，指人或事物好的方面。"}, {"text": "天气", "is_correct": false, "explanation": "无关：“天气”与“缺点”没有反义关系，只是同为名词。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”与“缺点”没有反义关系，只是同为名词。"}, {"text": "颜色", "is_correct": false, "explanation": "无关：“颜色”与“缺点”没有反义关系，只是同为名词。"}], "correct_answer": "优点", "explanations": {"优点": "正确：“优点”与“缺点”构成反义，指人或事物好的方面。", "天气": "无关：“天气”与“缺点”没有反义关系，只是同为名词。", "桌子": "无关：“桌子”与“缺点”没有反义关系，只是同为名词。", "颜色": "无关：“颜色”与“缺点”没有反义关系，只是同为名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优点", "is_correct": true, "explanation": "正确：“优点”与“缺点”构成反义，指人或事物好的方面。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”与“缺点”没有反义关系，只是同为名词。"}, {"text": "音乐", "is_correct": false, "explanation": "无关：“音乐”与“缺点”没有反义关系，只是同为名词。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”与“缺点”没有反义关系，只是同为名词。"}], "correct_answer": "优点", "explanations": {"优点": "正确：“优点”与“缺点”构成反义，指人或事物好的方面。", "河流": "无关：“河流”与“缺点”没有反义关系，只是同为名词。", "音乐": "无关：“音乐”与“缺点”没有反义关系，只是同为名词。", "窗户": "无关：“窗户”与“缺点”没有反义关系，只是同为名词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不好的地方。", "primary_collocate": null, "pronunciation": "quē diǎn", "ipa": "tɕʰɥe˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "每个人都有自己的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最大的缺点是不爱说话。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要多看别人的优点，少看缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的缺点是电池太小。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道自己的缺点，所以每天努力改。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服样子好看，就是有一个缺点：太贵。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说说这个方法的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子的缺点是离地铁太远。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很懒，这是他的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉我，我有什么缺点？", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个缺点", "label": "量词"}, {"form": "优缺点", "label": "复合"}, {"form": "缺點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物不好的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a11213-c341-4784-a79b-c98043c84b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺点", "is_correct": true, "explanation": "正确：“缺点”指不好的地方，可以说“自己的缺点”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能说“每个人都有自己的天气”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是公共的自然事物，不能说“每个人都有自己的河流”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“自己的”不能修饰“空气”，这一搭配不成立。"}], "explanations": {"缺点": "正确：“缺点”指不好的地方，可以说“自己的缺点”。", "天气": "语义：天气是自然现象，不能说“每个人都有自己的天气”。", "河流": "语义：河流是公共的自然事物，不能说“每个人都有自己的河流”。", "空气": "搭配：“自己的”不能修饰“空气”，这一搭配不成立。"}, "sentence_index": 0, "correct_answer": "缺点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车前几天出了缺点，只好送去修理。", "explanation": "这里应该用〈毛病〉。“缺点”指事物的不足之处，车或机器发生故障要说“出了毛病”，不说“出了缺点”。"}, {"text": "我在他身上发现了一只缺点。", "explanation": "这里应该用〈个〉。“缺点”前用量词“个”，“只”多用于动物或成对物中的一个，不能修饰“缺点”。"}, {"text": "他很擅长发挥自己的缺点。", "explanation": "这里应该用〈长处〉。“发挥”搭配“长处、优点、作用”等积极的东西，不能说“发挥缺点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺点", "is_correct": true, "explanation": "正确：“缺点”指不好的地方，可以说“这个方法的缺点”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：方法没有颜色，“这个方法的颜色”不成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只用于人的体型，不能说“方法的身材”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”指人的情绪，不能说“这个方法的心情”。"}], "explanations": {"缺点": "正确：“缺点”指不好的地方，可以说“这个方法的缺点”。", "颜色": "语义：方法没有颜色，“这个方法的颜色”不成立。", "身材": "体貌：“身材”只用于人的体型，不能说“方法的身材”。", "心情": "语义：“心情”指人的情绪，不能说“这个方法的心情”。"}, "sentence_index": 6, "correct_answer": "缺点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该扩大自己的缺点。", "explanation": "这里应该用〈优势〉。“扩大”搭配“优势、范围、影响”等，“缺点”是要改正的，不能被扩大。"}, {"text": "大家要互相发扬对方的缺点。", "explanation": "这里应该用〈优点〉。“发扬”搭配“优点、传统”等值得推广的东西，“缺点”应该改正，不能发扬。"}, {"text": "他这次比赛又吃了一个缺点。", "explanation": "这里应该用〈暴露〉。“吃”不能与“缺点”搭配，常说“暴露缺点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人的一只缺点很明显。", "corrected_sentence": "这个人的一个缺点很明显。", "error_description": "量词错误：“缺点”前应用量词“个”，“只”多用于动物，不能说“一只缺点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要把这只缺点改掉。", "corrected_sentence": "我们要把这个缺点改掉。", "error_description": "量词错误：“缺点”前应用量词“个”，“只”多用于动物，不能说“这只缺点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优点", "is_correct": true, "explanation": "正确：“优点”与“缺点”构成反义，指人或事物好的方面。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”与“缺点”没有反义关系，只是同为名词。"}, {"text": "椅子", "is_correct": false, "explanation": "无关：“椅子”与“缺点”没有反义关系，只是同为名词。"}, {"text": "鞋子", "is_correct": false, "explanation": "无关：“鞋子”与“缺点”没有反义关系，只是同为名词。"}], "correct_answer": "优点", "explanations": {"优点": "正确：“优点”与“缺点”构成反义，指人或事物好的方面。", "窗户": "无关：“窗户”与“缺点”没有反义关系，只是同为名词。", "椅子": "无关：“椅子”与“缺点”没有反义关系，只是同为名词。", "鞋子": "无关：“鞋子”与“缺点”没有反义关系，只是同为名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优点", "is_correct": true, "explanation": "正确：“优点”与“缺点”构成反义，指人或事物好的方面。"}, {"text": "天气", "is_correct": false, "explanation": "无关：“天气”与“缺点”没有反义关系，只是同为名词。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”与“缺点”没有反义关系，只是同为名词。"}, {"text": "颜色", "is_correct": false, "explanation": "无关：“颜色”与“缺点”没有反义关系，只是同为名词。"}], "correct_answer": "优点", "explanations": {"优点": "正确：“优点”与“缺点”构成反义，指人或事物好的方面。", "天气": "无关：“天气”与“缺点”没有反义关系，只是同为名词。", "桌子": "无关：“桌子”与“缺点”没有反义关系，只是同为名词。", "颜色": "无关：“颜色”与“缺点”没有反义关系，只是同为名词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "欠缺或不完美之处；与“优点”相对。", "primary_collocate": null, "pronunciation": "quē diǎn", "ipa": "tɕʰɥe˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这篇文章有优点，也有缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友指出了我的缺点，我很感谢。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在努力改正自己的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划的优点很多，缺点只有一个。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骄傲是很多年轻人的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看人不能只看缺点，也要看优点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我写字的缺点是太慢。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个设计的缺点，大家都看出来了。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的缺点和优点一样明显。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对自己的缺点，我们不要害怕。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个缺点", "label": "量词"}, {"form": "优缺点", "label": "复合"}, {"form": "缺點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "欠缺、不完美之处，与优点相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a11213-c341-4784-a79b-c98043c84b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺点", "is_correct": true, "explanation": "正确：“有……，也有……”后接与“优点”相对的“缺点”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“这篇文章有……”后不能接“桌子”，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：文章不能“有天气”，这一搭配没有意义。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“这篇文章有……”后不接“空气”，这一搭配不成立。"}], "explanations": {"缺点": "正确：“有……，也有……”后接与“优点”相对的“缺点”。", "桌子": "搭配：“这篇文章有……”后不能接“桌子”，句子不成立。", "天气": "语义：文章不能“有天气”，这一搭配没有意义。", "空气": "搭配：“这篇文章有……”后不接“空气”，这一搭配不成立。"}, "sentence_index": 0, "correct_answer": "缺点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱出了缺点，要找人来修。", "explanation": "这里应该用〈毛病〉。“缺点”指事物的不足之处，机器发生故障要说“出了毛病”。"}, {"text": "我觉得他最大的一只缺点是爱迟到。", "explanation": "这里应该用〈个〉。“缺点”前用量词“个”，“只”多用于动物或成对物中的一个，不能修饰“缺点”。"}, {"text": "比赛中他充分发挥了自己的缺点。", "explanation": "这里应该用〈长处〉。“发挥”搭配“长处、优点、作用”等积极的东西，不能说“发挥缺点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺点", "is_correct": true, "explanation": "正确：“缺点”指不好的方面，可以说“写字的缺点”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“写字的桌子”不能作“太慢”的主语，句子无法成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只用于人的体型，不能说“写字的身材”。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”是时间概念，不能说“写字的季节是太慢”。"}], "explanations": {"缺点": "正确：“缺点”指不好的方面，可以说“写字的缺点”。", "桌子": "语义：“写字的桌子”不能作“太慢”的主语，句子无法成立。", "身材": "体貌：“身材”只用于人的体型，不能说“写字的身材”。", "季节": "语义：“季节”是时间概念，不能说“写字的季节是太慢”。"}, "sentence_index": 6, "correct_answer": "缺点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司一直在扩大产品的缺点。", "explanation": "这里应该用〈优势〉。“扩大”搭配“优势、范围、影响”等，“缺点”不能被扩大。"}, {"text": "我们要把团队的缺点发扬光大。", "explanation": "这里应该用〈优点〉。“发扬光大”用于优点、传统等值得推广的东西，“缺点”不能发扬光大。"}, {"text": "他这次考试又喝了一个缺点。", "explanation": "这里应该用〈暴露〉。“喝”不能与“缺点”搭配，常说“暴露缺点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次作业的一只缺点是字写得太小。", "corrected_sentence": "这次作业的一个缺点是字写得太小。", "error_description": "量词错误：“缺点”前应用量词“个”，“只”多用于动物，不能说“一只缺点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把这只缺点讲清楚了。", "corrected_sentence": "他终于把这个缺点讲清楚了。", "error_description": "量词错误：“缺点”前应用量词“个”，“只”多用于动物，不能说“这只缺点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
