INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "南部地区，与北方相对。", "primary_collocate": null, "pronunciation": "nán fāng", "ipa": "nan˧˥ faŋ˥", "syllable_count": 2, "sentences": [{"text": "他是在南方长大的。", "target_word": "南方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "南方的冬天不太冷。", "target_word": "南方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "南方的人爱吃米饭。", "target_word": "南方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "南方夏天常常下大雨。", "target_word": "南方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想去南方旅行，看看大海。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种水果只长在南方。", "target_word": "南方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "南方的城市夏天又热又湿。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次去南方，觉得很新鲜。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从北方搬到了南方住。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方的春天来得比北方早。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "南方人", "label": "复合"}, {"form": "南方菜", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个国家中靠南的地区，与北方相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '476a3295-ccc1-45f7-ab1b-c537dc3fa42a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不是可以“长大”的地点，与句子不符。"}, {"text": "南方", "is_correct": true, "explanation": "南方：指南部地区，他在那里长大，与句子相合。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：“星期三”是日期，不是地方，不能用来回答“在哪里长大”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“在……里长大”要求一个地点，“心情”不能作为地点。"}], "explanations": {"春天": "语义：“春天”是季节，不是可以“长大”的地点，与句子不符。", "南方": "南方：指南部地区，他在那里长大，与句子相合。", "星期三": "语义：“星期三”是日期，不是地方，不能用来回答“在哪里长大”。", "心情": "搭配：“在……里长大”要求一个地点，“心情”不能作为地点。"}, "sentence_index": 0, "correct_answer": "南方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子的南方有一滴水。", "explanation": "这里应该用〈南边〉。南方指较大的方向或地区，杯子这样的小物件的位置要说南边。"}, {"text": "狮子主要生活在南方非洲的草原上。", "explanation": "这里应该用〈南部〉。“南部非洲”是固定的地区名称，不能用南方代替。"}, {"text": "这条河是南方走向的。", "explanation": "这里应该用〈南北〉。“南北走向”是固定说法，南方不能用来指走向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠少雨干燥，与“又湿”矛盾。"}, {"text": "南方", "is_correct": true, "explanation": "南方：指南部地区，修饰城市，与“夏天又热又湿”相合。"}, {"text": "高原", "is_correct": false, "explanation": "语义：高原气候凉爽干燥，与“又热又湿”矛盾。"}, {"text": "冰川", "is_correct": false, "explanation": "搭配：“冰川的城市”不是常用说法，冰川不能修饰城市。"}], "explanations": {"沙漠": "语义：沙漠少雨干燥，与“又湿”矛盾。", "南方": "南方：指南部地区，修饰城市，与“夏天又热又湿”相合。", "高原": "语义：高原气候凉爽干燥，与“又热又湿”矛盾。", "冰川": "搭配：“冰川的城市”不是常用说法，冰川不能修饰城市。"}, "sentence_index": 6, "correct_answer": "南方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果的南方烂了。", "explanation": "这里应该用〈南边〉。南方指较大的方向或地区，苹果这样的小东西的位置要说南边。"}, {"text": "他坐在我的南方。", "explanation": "这里应该用〈南边〉。南方指较大的方向或地区，人身边的位置要说南边。"}, {"text": "他一心想南方称王。", "explanation": "这里应该用〈南面〉。“南面称王”是固定说法，指面朝南而为王，南方不能代替“南面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的老家南方。", "corrected_sentence": "我的老家在南方。", "error_description": "缺少介词：表示处所要用“在”，“南方”前应有“在”，不能说“我的老家南方”，应说“我的老家在南方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他南方来到北京。", "corrected_sentence": "他从南方来到北京。", "error_description": "介词缺失：表示起点要用“从”引出“南方”，不能直接说“南方来到北京”，应说“从南方来到北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fdefc-9b2f-4f15-8b12-a868af208845') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
