INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91587, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "老师说词语，我们听着，把它写下来。", "primary_collocate": null, "pronunciation": "tīng xiě", "ipa": "tʰiŋ˥ ɕje˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天上课，老师让我们听写词语。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每个星期五都听写一次。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师念得很慢，我们认真听写。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天老师让我们听写生词。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听写以前，同学们都先复习生词。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听写的时候，从不看书。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下课前要听写完。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次我们听写了二十个词。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明听写得很认真。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们听写过这些词语。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听写了", "label": "体标"}, {"form": "听写过", "label": "体标"}, {"form": "听写本", "label": "复合"}, {"form": "聽寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "课堂上听老师说词语并写下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a11213-c341-4784-a79b-c98043c84b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听写", "is_correct": true, "explanation": "正确：“听写”指课堂上听老师说词语并写下来，符合句意。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：“演唱”接歌曲，不能接“词语”，“老师让我们演唱词语”不成立。"}, {"text": "扮演", "is_correct": false, "explanation": "语义：“扮演”指装扮成角色，与课堂上的词语无关。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，与课堂活动毫无关系。"}], "explanations": {"听写": "正确：“听写”指课堂上听老师说词语并写下来，符合句意。", "演唱": "搭配：“演唱”接歌曲，不能接“词语”，“老师让我们演唱词语”不成立。", "扮演": "语义：“扮演”指装扮成角色，与课堂上的词语无关。", "烹饪": "语义：“烹饪”指做饭，与课堂活动毫无关系。"}, "sentence_index": 0, "correct_answer": "听写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对着天空，把云朵的样子听写下来。", "explanation": "这里应该用〈描绘〉。“听写”针对念出来的字词和文字，云朵的样子要用眼睛看、用语言描绘，不能说“听写”。"}, {"text": "老师在黑板上写了答案，我们把它听写下来。", "explanation": "这里应该用〈抄写〉。“听写”要有人把内容念出来，写在黑板上的字要看着抄，应说“抄写”。"}, {"text": "这些英语句子，我们要听写成汉语。", "explanation": "这里应该用〈翻译〉。“听写”是把听到的内容原样写下，不能把句子变成另一种语言，应说“翻译”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听写", "is_correct": true, "explanation": "正确：“听写”指听别人念字词并写下来，“下课前要听写完”符合课堂任务。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指睡觉，与“下课前要……完”的课堂任务不符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗完”指洗涤完成，与“下课前要……”的课堂任务不符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮完”指做饭，与课堂任务不相关。"}], "explanations": {"听写": "正确：“听写”指听别人念字词并写下来，“下课前要听写完”符合课堂任务。", "睡": "语义：“睡”指睡觉，与“下课前要……完”的课堂任务不符。", "洗": "语义：“洗完”指洗涤完成，与“下课前要……”的课堂任务不符。", "煮": "语义：“煮完”指做饭，与课堂任务不相关。"}, "sentence_index": 6, "correct_answer": "听写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上听写了一只小猫。", "explanation": "这里应该用〈画〉。“听写”只用于字词、句子等文字内容，画画不能说“听写”。"}, {"text": "我们用相机听写了比赛。", "explanation": "这里应该用〈拍摄〉。“听写”针对可以念出的字词和文字，比赛要说“拍摄”。"}, {"text": "他用计算器听写出了答案。", "explanation": "这里应该用〈算出〉。“听写”是把听到的字词写下来，不能用来计算出答案，应说“算出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我们听写着了十个词。", "corrected_sentence": "今天我们听写了十个词。", "error_description": "体标错误：表示完成应说“听写了”，“听写”不宜带“着”，不能说“听写着了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，我们下课前要听写起这些词语。", "corrected_sentence": "老师说，我们下课前要听写完这些词语。", "error_description": "补语错误：“听写”的结果补语应为“完”，“起”不能作“听写”的补语，应为“听写完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44ba156f-903b-4919-a0f6-ff1f2b86a3e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
