INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91591, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地上是地的上面，地面上。", "primary_collocate": null, "pronunciation": "dì shang", "ipa": "ti˥˩ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "地上有一本书。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子坐在地上玩玩具。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的水是谁洒的？", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱包掉在了地上。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，地上白白的。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上很脏，你别坐。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫躺在地上睡觉。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上放着一个大箱子。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把垃圾扔在地上。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有很多落叶。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "地的上面，地面上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bdefeb-1e1d-4048-a525-662a680312a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91591, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气里放不下一本书，“空气有一本书”说不通。"}, {"text": "地上", "is_correct": true, "explanation": "正确：地上是地面上，可以放一本书。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不能放一本书。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“有”后面的主语要能容纳具体事物，声音不能容纳一本书。"}], "explanations": {"空气": "语义：空气里放不下一本书，“空气有一本书”说不通。", "地上": "正确：地上是地面上，可以放一本书。", "春天": "语义：春天是季节，不能放一本书。", "声音": "配价：“有”后面的主语要能容纳具体事物，声音不能容纳一本书。"}, "sentence_index": 0, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把种子埋在地上，等它发芽。", "explanation": "这里应该用“地下”。种子埋进土里要说地下，“地上”指地面以上，不能说埋在地上。"}, {"text": "我把眼镜挂在了地上。", "explanation": "语义：这里误把“地上”当成〈高处〉来用。挂东西要在高处，应说“挂在墙上”；“地上”指地面，不能用来挂东西。"}, {"text": "地上飘着几朵白云。", "explanation": "这里应该用〈天上〉。白云在高空飘动，“地上”指地面，不能用来描述白云的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91591, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以躺的地方，“猫躺在时间睡觉”说不通。"}, {"text": "风", "is_correct": false, "explanation": "配价：“躺在”需要有承托的处所，风不能承托猫。"}, {"text": "地上", "is_correct": true, "explanation": "正确：地上是地面上，猫可以躺在地上睡觉。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空没有可以躺的地方，“猫躺在天空睡觉”说不通。"}], "explanations": {"时间": "语义：时间不是可以躺的地方，“猫躺在时间睡觉”说不通。", "风": "配价：“躺在”需要有承托的处所，风不能承托猫。", "地上": "正确：地上是地面上，猫可以躺在地上睡觉。", "天空": "语义：天空没有可以躺的地方，“猫躺在天空睡觉”说不通。"}, "sentence_index": 6, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在地上的天空中找到了落叶。", "explanation": "语义：这里误把“地上”当成〈天上〉的意思来用。“地上”指地面，天空在高处，应说“天上”。"}, {"text": "那只猫趴在了地上的天花板上。", "explanation": "语义：这里误把“地上”当成〈顶上〉的意思来用。“地上”指地面，天花板在屋子顶部，应说“顶上”。"}, {"text": "飞机在地上盘旋。", "explanation": "这里应该用〈空中〉。飞机在空中盘旋，“地上”指地面，不能用来形容飞机的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看见一地上有一只小猫。", "corrected_sentence": "我看见地上有一只小猫。", "error_description": "错误：“地上”是一个词，中间不能插入数量词“一”，应说“地上有一只小猫”，不能拆成“一地上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地上是一只小猫。", "corrected_sentence": "地上有一只小猫。", "error_description": "错误：表示“某处存在某物”要用“有”，不能用“是”，应说“地上有一只小猫”；“地上是一只小猫”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
