INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上。", "primary_collocate": null, "pronunciation": "dì shang", "ipa": "ti˥˩ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "苹果从树上掉到了地上。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上太滑，小心点儿。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在地上系鞋带。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上铺着一块红地毯。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的地上都是水。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我把地上擦干净。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在地上找吃的。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的玩具请收好。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不小心摔倒在地上。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见地上有一只小虫。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "地面上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bdefeb-1e1d-4048-a525-662a680312a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天上", "is_correct": false, "explanation": "语义：苹果是从树上掉下来的，落点不能是天上，“掉到了天上”说不通。"}, {"text": "地上", "is_correct": true, "explanation": "正确：苹果落到地面，可以说“掉到了地上”。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“掉到”需要一个能承接实物的落点，空气不能承接苹果。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：苹果掉不到云朵上，这句话不成立。"}], "explanations": {"天上": "语义：苹果是从树上掉下来的，落点不能是天上，“掉到了天上”说不通。", "地上": "正确：苹果落到地面，可以说“掉到了地上”。", "空气": "配价：“掉到”需要一个能承接实物的落点，空气不能承接苹果。", "云朵": "语义：苹果掉不到云朵上，这句话不成立。"}, "sentence_index": 0, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子把积木埋在地上，过了几天就找不到了。", "explanation": "这里应该用“地下”。埋进土里要说地下，“地上”指地面以上，不能说埋在地上。"}, {"text": "我把书挂在了地上。", "explanation": "语义：这里误把“地上”当成〈高处〉来用。挂书要挂在高处，应说“挂在墙上”，“地上”只指地面。"}, {"text": "地上结着很多红苹果。", "explanation": "这里应该用〈树上〉。苹果长在树枝上，“地上”指地面，不能说苹果结在地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：小狗不能在天空里找吃的，这句话不成立。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，小狗不能在星星里找吃的。"}, {"text": "地上", "is_correct": true, "explanation": "正确：小狗可以在地上找吃的。"}, {"text": "风", "is_correct": false, "explanation": "配价：“在……找吃的”需要一个具体的场所，风不能提供吃的东西。"}], "explanations": {"天空": "语义：小狗不能在天空里找吃的，这句话不成立。", "星星": "语义：星星在天上，小狗不能在星星里找吃的。", "地上": "正确：小狗可以在地上找吃的。", "风": "配价：“在……找吃的”需要一个具体的场所，风不能提供吃的东西。"}, "sentence_index": 6, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看见地上的天空有一只小虫。", "explanation": "“地上”指地面，“天空”在高处，“地上的天空”自相矛盾，这里应说“天上”。"}, {"text": "我看见地上的墙上有一只小虫。", "explanation": "语义：这里误把“地上”当成〈高处〉来用。墙面在高处，不在地面，应去掉“地上”，直接说“墙上”。"}, {"text": "我看见屋顶的地上有一只小虫。", "explanation": "语义：这里误把“地上”当成〈上方〉的意思来用。“地上”只指地面，屋顶在屋子上方，不能用“地上”来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只小狗躺了地上。", "corrected_sentence": "一只小狗躺在地上。", "error_description": "错误：“躺”后要用“在”引出处所，应说“躺在地上”，“躺了地上”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "苹果掉了地上。", "corrected_sentence": "苹果掉在地上。", "error_description": "错误：“掉”后要用“在”引出处所，应说“掉在地上”，“掉了地上”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冬天", "is_correct": true, "explanation": "“夏天”与“冬天”是一对反义词，分别指一年中相对的两个季节。"}, {"text": "书", "is_correct": false, "explanation": "“书”与“夏天”没有反义关系，二者语义无关。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”与“夏天”没有反义关系，二者语义无关。"}, {"text": "电脑", "is_correct": false, "explanation": "“电脑”与“夏天”没有反义关系，二者语义无关。"}], "correct_answer": "冬天", "explanations": {"冬天": "“夏天”与“冬天”是一对反义词，分别指一年中相对的两个季节。", "书": "“书”与“夏天”没有反义关系，二者语义无关。", "河流": "“河流”与“夏天”没有反义关系，二者语义无关。", "电脑": "“电脑”与“夏天”没有反义关系，二者语义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冬天", "is_correct": true, "explanation": "“夏天”与“冬天”是一对反义词，分别指一年中相对的两个季节。"}, {"text": "老师", "is_correct": false, "explanation": "“老师”与“夏天”没有反义关系，二者语义无关。"}, {"text": "花园", "is_correct": false, "explanation": "“花园”与“夏天”没有反义关系，二者语义无关。"}, {"text": "电脑", "is_correct": false, "explanation": "“电脑”与“夏天”没有反义关系，二者语义无关。"}], "correct_answer": "冬天", "explanations": {"冬天": "“夏天”与“冬天”是一对反义词，分别指一年中相对的两个季节。", "老师": "“老师”与“夏天”没有反义关系，二者语义无关。", "花园": "“花园”与“夏天”没有反义关系，二者语义无关。", "电脑": "“电脑”与“夏天”没有反义关系，二者语义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "夏天是一年里最热的时候，我们爱吃冰淇淋，爱游泳。", "primary_collocate": null, "pronunciation": "xià tiān", "ipa": "ɕi̯a˥˩ tʰi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "夏天很热，我爱吃冰淇淋。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的时候，我们常去游泳。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天我想去海边玩。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天黑得晚，晚上八点还很亮。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热了，我一直开着空调。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈夏天喜欢穿白色的裙子。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天到了，街上卖西瓜的人多了。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天我们去过北京。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我每天喝很多水。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的晚上，大家都坐在外面聊天。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个夏天", "label": "量词搭配"}, {"form": "整个夏天", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "一年里最热的时候，人们吃冰淇淋、游泳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27aa1c00-fc1e-4f9c-85cd-83e1806a40ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夏天", "is_correct": true, "explanation": "“夏天”指一年中最热的季节，与“很热”相符，句子通顺。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与“很热”相反，“冬天很热，我爱吃冰淇淋”说不通。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：“冰块”是寒冷的固体，不能用“很热”来描述，句子说不通。"}, {"text": "寒冬", "is_correct": false, "explanation": "语义：“寒冬”指最冷的冬季，与“很热”矛盾。"}], "explanations": {"夏天": "“夏天”指一年中最热的季节，与“很热”相符，句子通顺。", "冬天": "语义：“冬天”与“很热”相反，“冬天很热，我爱吃冰淇淋”说不通。", "冰块": "语义：“冰块”是寒冷的固体，不能用“很热”来描述，句子说不通。", "寒冬": "语义：“寒冬”指最冷的冬季，与“很热”矛盾。"}, "sentence_index": 0, "correct_answer": "夏天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在海边度过了一只夏天。", "explanation": "这里应该用〈个〉。“夏天”指一段时间，量词用“个”；“只”多用于动物或成对的物品。"}, {"text": "我们去夏天学三门课。", "explanation": "这里应该用〈学校〉。“去”后应接处所，“夏天”是时间，不能作处所。"}, {"text": "去年我们一家人参加了夏天。", "explanation": "这里应该用〈夏令营〉。“参加”的对象是活动，“夏天”是时段，不能作为活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夏天", "is_correct": true, "explanation": "“夏天到了”说明季节转换，与“街上卖西瓜的人多了”相符。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：“寒假”是冬季的假期，与卖西瓜的夏季景象不符。"}, {"text": "元旦", "is_correct": false, "explanation": "搭配：“元旦”是节日名称，不能与“街上卖西瓜的人多了”这样的季节景象搭配。"}, {"text": "春节", "is_correct": false, "explanation": "搭配：“春节”是节日名称，春节前后不会出现街上卖西瓜的景象，句子说不通。"}], "explanations": {"夏天": "“夏天到了”说明季节转换，与“街上卖西瓜的人多了”相符。", "寒假": "语义：“寒假”是冬季的假期，与卖西瓜的夏季景象不符。", "元旦": "搭配：“元旦”是节日名称，不能与“街上卖西瓜的人多了”这样的季节景象搭配。", "春节": "搭配：“春节”是节日名称，春节前后不会出现街上卖西瓜的景象，句子说不通。"}, "sentence_index": 6, "correct_answer": "夏天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我报名了夏天，每天上午上课。", "explanation": "这里应该用〈夏令营〉。“报名”的对象是活动，“夏天”是时段，不能作报名的对象。"}, {"text": "我们要把钟表拨到夏天。", "explanation": "这里应该用〈夏令时〉。拨动钟表调整的是“夏令时”这一时制，“夏天”是季节，不能作为时制名称。"}, {"text": "老师让我们回家做夏天。", "explanation": "这里应该用〈作业〉。“做”的对象是作业、事情等，“夏天”是时段，不能作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只夏天我过得很开心。", "corrected_sentence": "这个夏天我过得很开心。", "error_description": "“夏天”作为一段时间，量词应用“个”，不能用“只”（“只”多用于动物或成对的物品）。应把“这只夏天”改为“这个夏天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们今年夏天的去海边玩。", "corrected_sentence": "我们今年夏天去海边玩。", "error_description": "助词错误：“夏天”作时间状语时后面不加“的”，应说“今年夏天去海边玩”，多出的“的”使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冬天", "is_correct": true, "explanation": "“夏天”与“冬天”是一对反义词，分别指一年中相对的两个季节。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”与“夏天”没有反义关系，二者语义无关。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”与“夏天”没有反义关系，二者语义无关。"}, {"text": "手机", "is_correct": false, "explanation": "“手机”与“夏天”没有反义关系，二者语义无关。"}], "correct_answer": "冬天", "explanations": {"冬天": "“夏天”与“冬天”是一对反义词，分别指一年中相对的两个季节。", "桌子": "“桌子”与“夏天”没有反义关系，二者语义无关。", "河流": "“河流”与“夏天”没有反义关系，二者语义无关。", "手机": "“手机”与“夏天”没有反义关系，二者语义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
