INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "四季之一，一年中最热的季节。", "primary_collocate": null, "pronunciation": "xià tiān", "ipa": "ɕi̯a˥˩ tʰi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "夏天是一年中最热的季节。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六月到八月是北方的夏天。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天过去以后，秋天就来了。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天又长又热。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天雨水多，常常下大雨。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天、夏天、秋天、冬天是四个季节。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方的夏天比北方更热。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到夏天，河里的水就多起来。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天白天长，夜里短。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢夏天的雷雨。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个夏天", "label": "量词搭配"}, {"form": "整个夏天", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "四季中排在春天之后、秋天之前的最热季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27aa1c00-fc1e-4f9c-85cd-83e1806a40ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夏天", "is_correct": true, "explanation": "“夏天”指四季之一，是一年中最热的季节，与句中的描述相符。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”是一年中最冷的季节，不是最热的季节，句子与事实相反。"}, {"text": "暑假", "is_correct": false, "explanation": "搭配：“暑假”是假期，不是季节，不能与“季节”构成同指关系。"}, {"text": "秋天", "is_correct": false, "explanation": "语义：“秋天”在夏天之后，并不是一年中最热的季节。"}], "explanations": {"夏天": "“夏天”指四季之一，是一年中最热的季节，与句中的描述相符。", "冬天": "语义：“冬天”是一年中最冷的季节，不是最热的季节，句子与事实相反。", "暑假": "搭配：“暑假”是假期，不是季节，不能与“季节”构成同指关系。", "秋天": "语义：“秋天”在夏天之后，并不是一年中最热的季节。"}, "sentence_index": 0, "correct_answer": "夏天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我还没写完夏天。", "explanation": "这里应该用〈作业〉。“写完”的对象是作业、文章等，“夏天”是时段，不能作宾语。"}, {"text": "这里的一只夏天又长又热。", "explanation": "这里应该用〈个〉。“夏天”指一段时间，量词用“个”；“只”多用于动物或成对的物品。"}, {"text": "我们要把手表调到夏天。", "explanation": "这里应该用〈夏令时〉。手表调整的是“夏令时”这一时制，“夏天”是季节，不能作为时制名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夏天", "is_correct": true, "explanation": "“夏天”指夏季，“南方的夏天比北方更热”符合常识，句子通顺。"}, {"text": "雪", "is_correct": false, "explanation": "语义：“雪”是寒冷天气的降水，与“比北方更热”的比较不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是制冷电器，不能用来比较南北方的气温高低。"}, {"text": "夏令营", "is_correct": false, "explanation": "搭配：“夏令营”是活动，不指时段或气候，不能作“南方的……比北方更热”的主语。"}], "explanations": {"夏天": "“夏天”指夏季，“南方的夏天比北方更热”符合常识，句子通顺。", "雪": "语义：“雪”是寒冷天气的降水，与“比北方更热”的比较不成立。", "冰箱": "语义：“冰箱”是制冷电器，不能用来比较南北方的气温高低。", "夏令营": "搭配：“夏令营”是活动，不指时段或气候，不能作“南方的……比北方更热”的主语。"}, "sentence_index": 6, "correct_answer": "夏天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年参加了夏天。", "explanation": "这里应该用〈夏令营〉。“参加”的对象是活动，“夏天”是季节，不能作为活动。"}, {"text": "我们每天去夏天上学。", "explanation": "这里应该用〈学校〉。“去”后应接处所，“夏天”是时间，不能作处所。"}, {"text": "她穿着一身夏天去上班。", "explanation": "这里应该用〈夏装〉。“夏装”指夏天穿的衣服，“夏天”是季节，不能作为衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只夏天很长，又很热。", "corrected_sentence": "这个夏天很长，又很热。", "error_description": "“夏天”作为季节，量词应用“个”，不能用“只”（“只”多用于动物或成对的物品）。应把“一只夏天”改为“这个夏天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每年夏天的都去海边。", "corrected_sentence": "我们每年夏天都去海边。", "error_description": "“夏天”作时间状语，后面不加“的”，应说“每年夏天都去海边”；这里在“夏天”后多加了“的”，是多余的结构助词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表扬", "is_correct": true, "explanation": "表扬：真诚地赞扬人，与讽刺的言不由衷相反，是这一义项的反义词。"}, {"text": "煮", "is_correct": false, "explanation": "煮：指用水加热食物，与讽刺没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：指出外游览，与讽刺没有反义关系。"}, {"text": "收拾", "is_correct": false, "explanation": "收拾：指整理物品，与讽刺没有反义关系。"}], "correct_answer": "表扬", "explanations": {"表扬": "表扬：真诚地赞扬人，与讽刺的言不由衷相反，是这一义项的反义词。", "煮": "煮：指用水加热食物，与讽刺没有反义关系。", "旅行": "旅行：指出外游览，与讽刺没有反义关系。", "收拾": "收拾：指整理物品，与讽刺没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "称赞", "is_correct": true, "explanation": "称赞：真心夸奖，与“用客气的话说坏话”的表里不一相反，是这一义项的反义词。"}, {"text": "洗", "is_correct": false, "explanation": "洗：指用水去除污垢，与讽刺没有反义关系。"}, {"text": "搬", "is_correct": false, "explanation": "搬：指移动物体，与讽刺没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指慢慢走动，与讽刺没有反义关系。"}], "correct_answer": "称赞", "explanations": {"称赞": "称赞：真心夸奖，与“用客气的话说坏话”的表里不一相反，是这一义项的反义词。", "洗": "洗：指用水去除污垢，与讽刺没有反义关系。", "搬": "搬：指移动物体，与讽刺没有反义关系。", "散步": "散步：指慢慢走动，与讽刺没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用好听的话说坏话，让人难为情。", "primary_collocate": null, "pronunciation": "fěng cì", "ipa": "fɤŋ˨˩ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他笑着说“你真聪明”，其实是在讽刺我。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我考得不好，同学却说我“真厉害”，这是讽刺我。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说“你来得真早”，是在讽刺我迟到。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别讽刺我了，我知道自己做得不好。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥夸我“跑得真快”，我听出来他在讽刺我。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理对迟到的小王说：“你来得真早啊！”这是在讽刺他。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话听起来很好听，其实是讽刺人。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说“你真爱干净啊”，是讽刺我房间太乱。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人夸你的时候，也要想想他是不是在讽刺你。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用很客气的话讽刺了我，我脸都红了。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "讽刺了", "label": "完成体"}, {"form": "讽刺过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "说反话、用表面夸奖的话挖苦人，让对方难为情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a6645ab-78ba-4186-8461-e21091544327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讽刺", "is_correct": true, "explanation": "讽刺：说反话、用表面夸奖挖苦人，与“笑着说你真聪明”及“其实”的转折相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说吃我。"}, {"text": "喂", "is_correct": false, "explanation": "语义：喂是给人或动物送食物，与“你真聪明”的夸奖语境不符。"}, {"text": "认识", "is_correct": false, "explanation": "配价：“认识”不能用“在”表示进行，不能说“是在认识我”。"}], "explanations": {"讽刺": "讽刺：说反话、用表面夸奖挖苦人，与“笑着说你真聪明”及“其实”的转折相符。", "吃": "搭配：“吃”的宾语是食物，不能说吃我。", "喂": "语义：喂是给人或动物送食物，与“你真聪明”的夸奖语境不符。", "认识": "配价：“认识”不能用“在”表示进行，不能说“是在认识我”。"}, "sentence_index": 0, "correct_answer": "讽刺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他满怀感激地讽刺了我的努力。", "explanation": "讽刺是用好听的话说坏话，暗含反面意思，与“满怀感激”的心情相矛盾，不能用来表达谢意。"}, {"text": "老师真诚地讽刺了我的进步。", "explanation": "这里应该用〈赞美〉。讽刺是用好听的话说坏话，“真诚地”与它的暗讽不符。"}, {"text": "老师为了鼓励我，讽刺了我的错误。", "explanation": "讽刺是说坏话，与“鼓励”的意图相反，不能用来激励别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讽刺", "is_correct": true, "explanation": "讽刺：表面说好听的话，实际挖苦人，与“听起来很好听，其实是”的转折相符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的宾语是物品，不能说搬人。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是衣物、身体等，不能说洗人。"}, {"text": "绑", "is_correct": false, "explanation": "语义：绑是捆住，与“听起来很好听”的话语无关，不能说绑人。"}], "explanations": {"讽刺": "讽刺：表面说好听的话，实际挖苦人，与“听起来很好听，其实是”的转折相符。", "搬": "搭配：“搬”的宾语是物品，不能说搬人。", "洗": "搭配：“洗”的宾语是衣物、身体等，不能说洗人。", "绑": "语义：绑是捆住，与“听起来很好听”的话语无关，不能说绑人。"}, "sentence_index": 6, "correct_answer": "讽刺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他满脸严肃地讽刺了我的笑话，却没说一句坏话。", "explanation": "讽刺就是用好听的话说坏话，“没说一句坏话”与讽刺的本义相矛盾。"}, {"text": "他真心实意地讽刺了我，说我的回答非常准确。", "explanation": "讽刺是言不由衷地说反话，“真心实意”与之相矛盾，句子表达的是真诚的夸奖。"}, {"text": "大家一起讽刺新同学，还送给他一束花。", "explanation": "讽刺是挖苦，与“送花”表示欢迎的举动相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学用夸奖的口气正在讽刺了我的懒惰。", "corrected_sentence": "同学用夸奖的口气讽刺了我的懒惰。", "error_description": "错误：“讽刺”前多出了“正在”，与表示完成的“了”不能同用。正确：去掉“正在”，写作“讽刺了我的懒惰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用客气的话讽刺了了我的穿着，我很尴尬。", "corrected_sentence": "他用客气的话讽刺了我的穿着，我很尴尬。", "error_description": "错误：“了”重复出现（“了了”）。正确：“讽刺”后只用一个“了”，写作“讽刺了我的穿着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赞美", "is_correct": true, "explanation": "赞美：真诚地称赞人，与讽刺的挖苦相反，是这一义项的反义词。"}, {"text": "观察", "is_correct": false, "explanation": "观察：指仔细看，与讽刺没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指修补器物，与讽刺没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集：指聚拢物品或资料，与讽刺没有反义关系。"}], "correct_answer": "赞美", "explanations": {"赞美": "赞美：真诚地称赞人，与讽刺的挖苦相反，是这一义项的反义词。", "观察": "观察：指仔细看，与讽刺没有反义关系。", "修理": "修理：指修补器物，与讽刺没有反义关系。", "收集": "收集：指聚拢物品或资料，与讽刺没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "称赞", "is_correct": true, "explanation": "称赞：真心夸奖，与讽刺的挖苦相反，是这一义项的反义词。"}, {"text": "修补", "is_correct": false, "explanation": "修补：指修复破损之处，与讽刺没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理：指使事物有条理，与讽刺没有反义关系。"}, {"text": "询问", "is_correct": false, "explanation": "询问：指打听、问，与讽刺没有反义关系。"}], "correct_answer": "称赞", "explanations": {"称赞": "称赞：真心夸奖，与讽刺的挖苦相反，是这一义项的反义词。", "修补": "修补：指修复破损之处，与讽刺没有反义关系。", "整理": "整理：指使事物有条理，与讽刺没有反义关系。", "询问": "询问：指打听、问，与讽刺没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用比喻、夸张等手法对人或事进行嘲笑和批评。", "primary_collocate": null, "pronunciation": "fěng cì", "ipa": "fɤŋ˨˩ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这幅漫画讽刺了乱扔垃圾的人。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家用夸张的方法讽刺社会上的坏事。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说讽刺了那个时代的官员。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的相声常常讽刺爱面子的人。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事用小动物讽刺人的缺点。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这首诗是在讽刺懒人。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上的漫画常常讽刺不好的社会现象。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲁迅的文章讽刺过很多社会问题。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影用笑话讽刺了贪钱的老板。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一幅画，讽刺那些浪费粮食的人。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "讽刺了", "label": "完成体"}, {"form": "讽刺过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "文学、漫画、相声等用比喻、夸张的手法嘲笑并批评坏人坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a6645ab-78ba-4186-8461-e21091544327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讽刺", "is_correct": true, "explanation": "讽刺：用比喻、夸张的手法嘲笑批评乱扔垃圾的人，与漫画的意图相符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美是称赞，乱扔垃圾的人不值得称赞，与漫画的批评意图相反。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：庆祝的对象是节日、胜利等事件，不能说庆祝乱扔垃圾的人。"}, {"text": "保护", "is_correct": false, "explanation": "语义：保护是护卫、爱护，漫画不会去保护乱扔垃圾的人。"}], "explanations": {"讽刺": "讽刺：用比喻、夸张的手法嘲笑批评乱扔垃圾的人，与漫画的意图相符。", "赞美": "语义：赞美是称赞，乱扔垃圾的人不值得称赞，与漫画的批评意图相反。", "庆祝": "搭配：庆祝的对象是节日、胜利等事件，不能说庆祝乱扔垃圾的人。", "保护": "语义：保护是护卫、爱护，漫画不会去保护乱扔垃圾的人。"}, "sentence_index": 0, "correct_answer": "讽刺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我真心地讽刺了你的进步。", "explanation": "讽刺是用比喻、夸张嘲笑或批评，本质上言不由衷，与“真心地”相矛盾，不能用来真心表扬。"}, {"text": "老师满怀感激地讽刺了我的帮助。", "explanation": "讽刺是嘲笑批评，与“满怀感激”的心情相矛盾，不能用来表示谢意。"}, {"text": "为了鼓励他，我讽刺了他的努力。", "explanation": "讽刺的意图是挖苦嘲笑，与“鼓励”相反，不能用来激励别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讽刺", "is_correct": true, "explanation": "讽刺：用漫画批评、挖苦不好的社会现象，与“常常”及句意相符。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：歌颂是赞美颂扬，与“不好的社会现象”矛盾。"}, {"text": "赞助", "is_correct": false, "explanation": "搭配：赞助的对象是活动、事业等，不能说赞助不好的社会现象。"}, {"text": "维护", "is_correct": false, "explanation": "语义：维护是保护、坚持，漫画不会去维护不好的社会现象。"}], "explanations": {"讽刺": "讽刺：用漫画批评、挖苦不好的社会现象，与“常常”及句意相符。", "歌颂": "语义：歌颂是赞美颂扬，与“不好的社会现象”矛盾。", "赞助": "搭配：赞助的对象是活动、事业等，不能说赞助不好的社会现象。", "维护": "语义：维护是保护、坚持，漫画不会去维护不好的社会现象。"}, "sentence_index": 6, "correct_answer": "讽刺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了表示感谢，讽刺了那位送花的朋友。", "explanation": "讽刺是嘲笑批评，不能用来表示感谢。"}, {"text": "老师热情地讽刺了新来的同学。", "explanation": "讽刺是挖苦批评，与“热情”的态度相矛盾。"}, {"text": "大家都很高兴，纷纷讽刺这次的胜利。", "explanation": "讽刺含有挖苦批评的意思，与大家庆祝胜利的心情相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇社论正在讽刺了乱花公款的人。", "corrected_sentence": "这篇社论讽刺了乱花公款的人。", "error_description": "错误：“正在”表示动作进行，与表示完成的“了”不能同用，且“讽刺”前多出了“正在”。正确：去掉“正在”，写作“这篇社论讽刺了乱花公款的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章讽刺了了乱收费的机构。", "corrected_sentence": "这篇文章讽刺了乱收费的机构。", "error_description": "错误：“了”重复出现（“了了”）。正确：“讽刺”后只用一个“了”，写作“讽刺了乱收费的机构”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
