INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91616, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指介入他人婚姻关系的第三者（口语）。", "primary_collocate": null, "pronunciation": "xiǎo sān", "ipa": "ɕjɑʊ̯˨˩ sa˥", "syllable_count": 2, "sentences": [{"text": "他有了小三，妻子很伤心。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现丈夫外面有小三。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人愿意被人叫小三。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为小三和妻子离婚了。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧里的小三总是很坏。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己不想当小三。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子找到了小三，质问她。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友劝他离开小三，回到家里。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小三的事让两家人都很难过。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都看不起小三。", "target_word": "小三", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "介入他人婚姻的第三者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bdefeb-1e1d-4048-a525-662a680312a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91616, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小三", "is_correct": true, "explanation": "正确。小三指介入他人婚姻关系的第三者（口语）。"}, {"text": "小山", "is_correct": false, "explanation": "shān（第一声）与 sān（第一声）声母不同（sh 与 s），意思是小山。"}, {"text": "小伞", "is_correct": false, "explanation": "sǎn（第三声）与 sān（第一声）声调不同，意思是小伞。"}, {"text": "消散", "is_correct": false, "explanation": "xiāo 与 xiǎo、sàn 与 sān 声调都不同，意思是消散。"}], "explanations": {"小三": "正确。小三指介入他人婚姻关系的第三者（口语）。", "小山": "shān（第一声）与 sān（第一声）声母不同（sh 与 s），意思是小山。", "小伞": "sǎn（第三声）与 sān（第一声）声调不同，意思是小伞。", "消散": "xiāo 与 xiǎo、sàn 与 sān 声调都不同，意思是消散。"}, "sentence_index": null, "correct_answer": "小三"}, "level_3": {"options": [{"text": "小三", "is_correct": true, "explanation": "正确。“小三”指介入他人婚姻的第三者，与“妻子很伤心”的语境相符。"}, {"text": "妻子", "is_correct": false, "explanation": "语义：“他有了妻子”指有妻子，不指婚外第三者，且与后文“妻子很伤心”重复，句意不合常理。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人，“他有了汽车，妻子很伤心”没有合理的因果关系。"}, {"text": "胡子", "is_correct": false, "explanation": "体貌：胡子是外貌特征，“有了胡子”不能使妻子伤心，句子不通。"}], "explanations": {"小三": "正确。“小三”指介入他人婚姻的第三者，与“妻子很伤心”的语境相符。", "妻子": "语义：“他有了妻子”指有妻子，不指婚外第三者，且与后文“妻子很伤心”重复，句意不合常理。", "汽车": "语义：汽车不是人，“他有了汽车，妻子很伤心”没有合理的因果关系。", "胡子": "体貌：胡子是外貌特征，“有了胡子”不能使妻子伤心，句子不通。"}, "sentence_index": 0, "correct_answer": "小三"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小三偷走了我的钱包。", "explanation": "这里应该用〈小偷〉。小三指介入他人婚姻关系的第三者，不指偷东西的人，偷东西的要说小偷。"}, {"text": "这位小三每天在办公室开会。", "explanation": "这里应该用〈老板〉。小三指介入他人婚姻关系的第三者，不指主持会议的管理者，要说老板。"}, {"text": "这只小三很可爱，经常跟我玩。", "explanation": "这里应该用〈小猫〉。小三指介入他人婚姻关系的第三者，不能用来称呼可爱的小动物，要说小猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小三", "is_correct": true, "explanation": "正确。“妻子找到了小三，质问她”中，“小三”指介入婚姻的第三者，语境完整。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是人，妻子“找到了钥匙”后“质问她”，句子意思不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能被妻子质问，“找到了桌子，质问她”没有合理的语义联系。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是人，不能被“质问”，“妻子找到了太阳，质问她”句意不通。"}], "explanations": {"小三": "正确。“妻子找到了小三，质问她”中，“小三”指介入婚姻的第三者，语境完整。", "钥匙": "语义：钥匙不是人，妻子“找到了钥匙”后“质问她”，句子意思不通。", "桌子": "语义：桌子不能被妻子质问，“找到了桌子，质问她”没有合理的语义联系。", "太阳": "语义：太阳不是人，不能被“质问”，“妻子找到了太阳，质问她”句意不通。"}, "sentence_index": 6, "correct_answer": "小三"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位小三写了很多好书。", "explanation": "这里应该用〈作家〉。小三指介入他人婚姻关系的第三者，不指写书的人，要说作家。"}, {"text": "这位小三每天给病人看病。", "explanation": "这里应该用〈医生〉。小三指介入他人婚姻关系的第三者，不指给病人看病的人，要说医生。"}, {"text": "这位小三在太空站工作了一年。", "explanation": "这里应该用〈宇航员〉。小三指介入他人婚姻关系的第三者，不指在太空站工作的人，要说宇航员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妻子知道丈夫和一只小三的事后很生气。", "corrected_sentence": "妻子知道丈夫和一个小三的事后很生气。", "error_description": "量词错误：“小三”指人，量词应用“个”。“一只”多用于动物或小物件，指人不对，应改为“一个小三”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妻子把小三赶了走，很伤心。", "corrected_sentence": "妻子把小三赶走了，很伤心。", "error_description": "补语语序错误：“赶走”是动补结构，不能拆成“赶了走”，应说“把小三赶走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
