INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91623, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被面是被子最外面的那层布。", "primary_collocate": null, "pronunciation": "bèi miàn", "ipa": "peɪ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这条被面是红色的，上面有花。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给我做了一条新被面。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被面脏了，我把它拿去洗。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这床被子的被面很软。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被面上有一只可爱的小鸟。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢白色的被面，看起来很干净。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用旧布做了一条漂亮的被面。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个被面太小，盖不住整张床。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被面是丝做的，摸起来很滑。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完以后，被面挂在院子里晒着。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：被子最外面的一层布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d5693c-26b2-4f0a-ad61-6ebde57a6292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被面", "is_correct": true, "explanation": "正确：被面是被子外面的一层布，与“红色的，上面有花”相合。"}, {"text": "被芯", "is_correct": false, "explanation": "语义：被芯是包在里面的絮，看不到，不会“上面有花”。"}, {"text": "棉花", "is_correct": false, "explanation": "搭配：“条”不用于棉花这种散状的原料，也不能说“这条棉花是红色的”。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "搭配：“条”用于细长或成条的东西，不能用于洗衣粉这类粉状物。"}], "explanations": {"被面": "正确：被面是被子外面的一层布，与“红色的，上面有花”相合。", "被芯": "语义：被芯是包在里面的絮，看不到，不会“上面有花”。", "棉花": "搭配：“条”不用于棉花这种散状的原料，也不能说“这条棉花是红色的”。", "洗衣粉": "搭配：“条”用于细长或成条的东西，不能用于洗衣粉这类粉状物。"}, "sentence_index": 0, "correct_answer": "被面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚上盖着厚被面，身上很暖和。", "explanation": "这里应该用〈被子〉。被面只是外层的布，保暖的是整床被子，不能说“盖着被面很暖和”。"}, {"text": "我买了一杯被面，准备做新被子。", "explanation": "这里应该用〈条〉或〈块〉。“杯”用于盛液体的容器，被面是一长块布，不能用“杯”计量。"}, {"text": "被面是棉花做的，很蓬松。", "explanation": "这里应该用〈被芯〉。被面是布料，棉花是填在被子里的被芯，不能说“被面是棉花做的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被面", "is_correct": true, "explanation": "正确：被面是用旧布做成的被子外层，与“做了一条漂亮的”相合。"}, {"text": "被窝", "is_correct": false, "explanation": "语义：被窝是被子包着人的地方，不是用布做成的东西。"}, {"text": "洗衣机", "is_correct": false, "explanation": "搭配：“条”不用于洗衣机，洗衣机是机器，不能用旧布做。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯不是用旧布做的，也不是布类的东西，与“漂亮”的描述不合。"}], "explanations": {"被面": "正确：被面是用旧布做成的被子外层，与“做了一条漂亮的”相合。", "被窝": "语义：被窝是被子包着人的地方，不是用布做成的东西。", "洗衣机": "搭配：“条”不用于洗衣机，洗衣机是机器，不能用旧布做。", "台灯": "语义：台灯不是用旧布做的，也不是布类的东西，与“漂亮”的描述不合。"}, "sentence_index": 6, "correct_answer": "被面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的被面晒得很黑，常年在地里干活。", "explanation": "这里把“被面”用来指人的皮肤，被面只指被子外面的布，不能这样说。"}, {"text": "这座山的被面长满了松树。", "explanation": "这里把“被面”用来指山的表面，被面只能指被子外层的布，不能指地形。"}, {"text": "这辆车的被面是铁做的，很结实。", "explanation": "这里把“被面”用来指车身，被面只指被子外层的布，车身不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把那朵旧被面洗干净，又缝回被子上。", "corrected_sentence": "妈妈把那条旧被面洗干净，又缝回被子上。", "error_description": "错误形式：那朵旧被面；正确形式：那条旧被面。被面是一长条布，应用“条”计量；“朵”用于花、云等，不能用于被面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把这条被面洗很干净。", "corrected_sentence": "奶奶把这条被面洗得很干净。", "error_description": "错误形式：洗很干净；正确形式：洗得很干净。“洗”后带“很干净”这类结果补语，中间要用“得”连接，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
