INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91625, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "选人的时候，用来写名字的小纸。", "primary_collocate": null, "pronunciation": "xuǎn piào", "ipa": "ɕɥɛn˨˩ pʰjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老师给每个同学一张选票。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在选票上写了小明的名字。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选班长时，大家把名字写在选票上。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张选票很小，只能写一个名字。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们折好选票，放进盒子里。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班长走过来，收走了大家的选票。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板前数选票，小王得了十张。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心把选票弄丢了，只好再要一张。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选票上不能写别的话，只能写名字。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选出新队长以后，老师把选票都收起来了。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "選票", "label": "繁体"}], "register": "中性", "sense_fingerprint": "选班长、选队长等选人时用来写名字的小纸片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a6645ab-78ba-4186-8461-e21091544327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选票", "is_correct": true, "explanation": "选票：选人时用来写名字的小纸片，老师给每个同学一张，符合句意。"}, {"text": "通缉令", "is_correct": false, "explanation": "语义：通缉令是针对罪犯发布的，老师不会给每个同学一张。"}, {"text": "病假条", "is_correct": false, "explanation": "搭配：“病假条”是请假时用的，老师不会一人发一张，与“给”的语境不搭。"}, {"text": "欠条", "is_correct": false, "explanation": "语义：欠条是欠钱时写的，老师给每个同学一张欠条没有道理。"}], "explanations": {"选票": "选票：选人时用来写名字的小纸片，老师给每个同学一张，符合句意。", "通缉令": "语义：通缉令是针对罪犯发布的，老师不会给每个同学一张。", "病假条": "搭配：“病假条”是请假时用的，老师不会一人发一张，与“给”的语境不搭。", "欠条": "语义：欠条是欠钱时写的，老师给每个同学一张欠条没有道理。"}, "sentence_index": 0, "correct_answer": "选票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们在选票上写下了悄悄话。", "explanation": "这里应该用〈纸条〉。选票只用来写候选人的名字，不能写悄悄话。"}, {"text": "他在选票上写了祝福。", "explanation": "这里应该用〈卡片〉。选票只用来写选人的名字，不用于写祝福。"}, {"text": "老师让大家在选票上写下了课文的句子。", "explanation": "这里应该用〈作业本〉。选票只用来写选人的名字，不能抄写课文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选票", "is_correct": true, "explanation": "选票：数的是选班长时的选票，“小王得了十张”与选票的量词相符。"}, {"text": "花", "is_correct": false, "explanation": "搭配：花的量词是“朵”，不能用“张”来计数。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：老师在黑板前数笑话没有道理，与“得了十张”的语境不符。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：糖的量词是“颗”，不能说“得了十张”。"}], "explanations": {"选票": "选票：数的是选班长时的选票，“小王得了十张”与选票的量词相符。", "花": "搭配：花的量词是“朵”，不能用“张”来计数。", "笑话": "语义：老师在黑板前数笑话没有道理，与“得了十张”的语境不符。", "糖": "搭配：糖的量词是“颗”，不能说“得了十张”。"}, "sentence_index": 6, "correct_answer": "选票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用选票擦了黑板。", "explanation": "选票只用来写选人的名字，不能拿来擦黑板。"}, {"text": "他把选票当成钱，去小卖部买了一根冰棍。", "explanation": "选票不是货币，不能用来付款。"}, {"text": "他用选票包了一块点心。", "explanation": "选票是用来写名字的纸，不用于包裹食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小红悄悄地把一个选票折了两次。", "corrected_sentence": "小红悄悄地把一张选票折了两次。", "error_description": "错误：选票的量词用了“个”。正确：选票是纸片，量词用“张”，写作“一张选票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王把选票们装进了书包。", "corrected_sentence": "小王把选票装进了书包。", "error_description": "错误：选票后加了“们”。正确：表示事物的名词不加“们”，写作“选票”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
