INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "选举时用来写明或标明所选对象的票。", "primary_collocate": null, "pronunciation": "xuǎn piào", "ipa": "ɕɥɛn˨˩ pʰjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "每个人都有一张选票。", "target_word": "选票", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工作人员在门口发选票。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在选票上写了自己喜欢的人的名字。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举结束后，大家开始数选票。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把选票放进了投票箱。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次选举一共收到了五百张选票。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选票上有三个名字，你只能选一个。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有一张选票没有写名字，所以不能算。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在选票上画圈，选出你支持的人。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选举那天，他拿着选票走进了学校的大厅。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "選票", "label": "繁体"}], "register": "中性", "sense_fingerprint": "正式选举中投票人用来写明或标明所选对象的票", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a6645ab-78ba-4186-8461-e21091544327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选票", "is_correct": true, "explanation": "选票：选举时用来写所选对象的票，“每个人都有一张”指每位选民各得一张。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：奖状是颁给获奖者的，不是每个人都有，与“每个人都有”不符。"}, {"text": "罚单", "is_correct": false, "explanation": "语义：罚单是开给违规者的，说每个人都有一张罚单不合常理。"}, {"text": "病假条", "is_correct": false, "explanation": "搭配：“病假条”通常说“请”或“开”，不说“有”。"}], "explanations": {"选票": "选票：选举时用来写所选对象的票，“每个人都有一张”指每位选民各得一张。", "奖状": "语义：奖状是颁给获奖者的，不是每个人都有，与“每个人都有”不符。", "罚单": "语义：罚单是开给违规者的，说每个人都有一张罚单不合常理。", "病假条": "搭配：“病假条”通常说“请”或“开”，不说“有”。"}, "sentence_index": 0, "correct_answer": "选票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站买了一张选票。", "explanation": "这里应该用〈车票〉。选票是选举时投给候选人的票，不能买，也不能用来乘车。"}, {"text": "演出开始前，他拿出选票检查了一遍。", "explanation": "这里应该用〈门票〉。选票不用于进入场所，不能用来检票。"}, {"text": "选举那天，他把选票当作生日礼物送给了朋友。", "explanation": "选票是选举时投给候选人的票，不能当作礼物送人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选票", "is_correct": true, "explanation": "选票：选举时写所选对象的票，与“上有三个名字，你只能选一个”的选举语境相符。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单上列的是费用，不会列出可以选的人名。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片上通常只印一个人的名字，不会列出三个供选择的名字。"}, {"text": "床单", "is_correct": false, "explanation": "语义：床单是铺床用的布，上面不会列出可以选的名字，与“你只能选一个”不符。"}], "explanations": {"选票": "选票：选举时写所选对象的票，与“上有三个名字，你只能选一个”的选举语境相符。", "账单": "语义：账单上列的是费用，不会列出可以选的人名。", "名片": "语义：名片上通常只印一个人的名字，不会列出三个供选择的名字。", "床单": "语义：床单是铺床用的布，上面不会列出可以选的名字，与“你只能选一个”不符。"}, "sentence_index": 6, "correct_answer": "选票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考场上交了一张选票。", "explanation": "选票是选举时投给候选人的票，不能像考卷那样交给考官。"}, {"text": "他中了一张选票。", "explanation": "这里应该用〈奖券〉。选票没有中奖的用法，只能用于选举。"}, {"text": "他向店员要了一张选票。", "explanation": "这里应该用〈收据〉。选票不是购物凭证，不能向店员索要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次选举中，有几百个选票被认定无效。", "corrected_sentence": "这次选举中，有几百张选票被认定无效。", "error_description": "错误：选票的量词用了“个”。正确：选票是纸片，量词用“张”，写作“几百张选票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员正在清点过选票。", "corrected_sentence": "工作人员正在清点选票。", "error_description": "错误：“正在”表示动作进行中，不能与表示经历的“过”同用，句中多出了“过”。正确：去掉“过”，写作“工作人员正在清点选票。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留用", "is_correct": true, "explanation": "反义：「开除」让人离开，「留用」让人继续留在原单位。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：「研究」指探讨问题，与「开除」意思无关。"}, {"text": "出版", "is_correct": false, "explanation": "无反义关系：「出版」指把作品印刷发行，与「开除」无关。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：「散步」指随意走动，与「开除」无关。"}], "correct_answer": "留用", "explanations": {"留用": "反义：「开除」让人离开，「留用」让人继续留在原单位。", "研究": "无反义关系：「研究」指探讨问题，与「开除」意思无关。", "出版": "无反义关系：「出版」指把作品印刷发行，与「开除」无关。", "散步": "无反义关系：「散步」指随意走动，与「开除」无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "录用", "is_correct": true, "explanation": "反义：「开除」是让人离开，「录用」是接收人员入职，意思相反。"}, {"text": "报告", "is_correct": false, "explanation": "无反义关系：「报告」指陈述情况，与「开除」无关。"}, {"text": "游览", "is_correct": false, "explanation": "无反义关系：「游览」指参观风景，与「开除」无关。"}, {"text": "咨询", "is_correct": false, "explanation": "无反义关系：「咨询」指请人提供意见，与「开除」无关。"}], "correct_answer": "录用", "explanations": {"录用": "反义：「开除」是让人离开，「录用」是接收人员入职，意思相反。", "报告": "无反义关系：「报告」指陈述情况，与「开除」无关。", "游览": "无反义关系：「游览」指参观风景，与「开除」无关。", "咨询": "无反义关系：「咨询」指请人提供意见，与「开除」无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不让他再留在学校或工作的地方。", "primary_collocate": null, "pronunciation": "kāi chú", "ipa": "kʰaɪ˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "小王常常迟到，老板把他开除了。", "target_word": "开除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在考试时作弊，学校开除了他。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司说，再迟到就要开除你。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师告诉我，那个学生打了人，学校决定开除他。", "target_word": "开除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是不来上班，老板就开除了他。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂开除了三个不好好工作的人。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再这样做，老板会开除你的。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕老板开除他，所以天天早到。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家饭店昨天开除了一个服务员。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板很生气，他说要马上开除小李。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开除了", "label": "完成体"}, {"form": "开除过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "老板或学校不再让人留在原来的学校或工作单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a8897d1-e71b-427d-ba6c-d8eccd14f3cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开除", "is_correct": true, "explanation": "正确。「开除」指因犯错误而不让他留在单位，与「常常迟到」的语境相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：「表扬」是称赞，与「常常迟到」的行为相矛盾。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：「讨论」的对象是问题或方案，不说「讨论他」。"}, {"text": "批准", "is_correct": false, "explanation": "语义：「批准」是同意某事，与老板因迟到而处理员工的语境不符。"}], "explanations": {"开除": "正确。「开除」指因犯错误而不让他留在单位，与「常常迟到」的语境相符。", "表扬": "语义：「表扬」是称赞，与「常常迟到」的行为相矛盾。", "讨论": "搭配：「讨论」的对象是问题或方案，不说「讨论他」。", "批准": "语义：「批准」是同意某事，与老板因迟到而处理员工的语境不符。"}, "sentence_index": 0, "correct_answer": "开除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用肥皂水可以开除衣服上的油渍。", "explanation": "这里应该用〈去除〉。开除只用于人及其身份（学籍、职务等），去除用于油渍、污渍等。"}, {"text": "学校今年开除了三百多份申请。", "explanation": "这里应该用〈受理〉。「开除」的对象是人或其身份，不能用于申请。"}, {"text": "公司因为业务调整，开除了一批合同。", "explanation": "这里应该用〈终止〉。「开除」的对象是人或其身份，不能用于合同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开除", "is_correct": true, "explanation": "正确。「你再这样做，老板会……你的」是威胁语气，「开除」符合这一语境。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：「奖励」是对好行为的回报，与带威胁语气的句子不符。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：「感谢」表示对帮助的回应，与「会……你的」的威胁语气矛盾。"}, {"text": "嘉奖", "is_correct": false, "explanation": "语域：「嘉奖」是书面语的正式表彰，口语的威胁句中不用。"}], "explanations": {"开除": "正确。「你再这样做，老板会……你的」是威胁语气，「开除」符合这一语境。", "奖励": "语义：「奖励」是对好行为的回报，与带威胁语气的句子不符。", "感谢": "语义：「感谢」表示对帮助的回应，与「会……你的」的威胁语气矛盾。", "嘉奖": "语域：「嘉奖」是书面语的正式表彰，口语的威胁句中不用。"}, "sentence_index": 6, "correct_answer": "开除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我觉得工资太低，就开除了这家公司。", "explanation": "这里应该用〈辞职〉。「开除」的施事是学校或单位，对象是人；自己离开工作要说辞职。"}, {"text": "老板开除了我的意见。", "explanation": "这里应该用〈采纳〉。「开除」的对象是人或其身份，不能用于意见。"}, {"text": "公司决定开除这个部门。", "explanation": "这里应该用〈解散〉。「开除」的对象是人，不能用于部门或团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把那名迟到的员工开除。", "corrected_sentence": "公司把那名迟到的员工开除了。", "error_description": "错误：「把」字句缺少「了」。正确：「把」字句要表示完成的动作，应说「把那名迟到的员工开除了」，只说「开除」句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂把那个乱扔垃圾的工人开除。", "corrected_sentence": "工厂把那个乱扔垃圾的工人开除了。", "error_description": "错误：「把」字句缺少「了」。正确：「把」字句要表示完成的动作，应说「把那个乱扔垃圾的工人开除了」，只说「开除」句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
