INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因犯错误而取消其学籍或职务，令其离开集体。", "primary_collocate": null, "pronunciation": "kāi chú", "ipa": "kʰaɪ˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "他犯了严重的错误，学校开除了他的学籍。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校决定开除他的学籍。", "target_word": "开除", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他贪污公款，单位开除了他的公职。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个队员违反了规定，球队开除了他。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他多次违反校规，学校开除了他。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个官员收了很多钱，党开除了他的党籍。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "协会开除了那位乱收钱的会员。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在部队里偷东西，部队开除了他的军籍。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做错了事，可是学校没有开除他。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过调查，医院开除了那位收红包的医生。", "target_word": "开除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开除了", "label": "完成体"}, {"form": "开除过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "因犯错误取消学籍、公职、党籍等身份，使其离开集体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a8897d1-e71b-427d-ba6c-d8eccd14f3cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开除", "is_correct": true, "explanation": "正确。「犯了严重的错误」之后，学校取消其学籍，用「开除」。"}, {"text": "颁发", "is_correct": false, "explanation": "搭配：「颁发」用于证书、奖状，不说「颁发学籍」。"}, {"text": "授予", "is_correct": false, "explanation": "搭配：「授予」用于学位、称号，不用于学籍。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：「恢复」表示重新给予，与「犯了严重的错误」的语境相反。"}], "explanations": {"开除": "正确。「犯了严重的错误」之后，学校取消其学籍，用「开除」。", "颁发": "搭配：「颁发」用于证书、奖状，不说「颁发学籍」。", "授予": "搭配：「授予」用于学位、称号，不用于学籍。", "恢复": "语义：「恢复」表示重新给予，与「犯了严重的错误」的语境相反。"}, "sentence_index": 0, "correct_answer": "开除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为身体不好，开除了自己的学籍。", "explanation": "这里应该用〈退学〉。「开除」的施事是学校或单位，学生自己离开应说退学。"}, {"text": "学校开除了他的考试资格。", "explanation": "这里应该用〈取消〉。「开除」只用于学籍、职务、党籍等身份，考试资格应说取消。"}, {"text": "公司因为他工作失误，开除了他的工资。", "explanation": "这里应该用〈扣除〉。「开除」的对象是人或其身份，不能用于工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开除", "is_correct": true, "explanation": "正确。「协会开除了……会员」指取消其会员身份，符合「乱收钱」的语境。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：「表扬」是称赞，与「乱收钱」的行为矛盾。"}, {"text": "检测", "is_correct": false, "explanation": "搭配：「检测」的对象是产品、水质等，不用于人。"}, {"text": "慰问", "is_correct": false, "explanation": "语义：「慰问」是表示关心安慰，与「乱收钱」的会员不符。"}], "explanations": {"开除": "正确。「协会开除了……会员」指取消其会员身份，符合「乱收钱」的语境。", "表扬": "语义：「表扬」是称赞，与「乱收钱」的行为矛盾。", "检测": "搭配：「检测」的对象是产品、水质等，不用于人。", "慰问": "语义：「慰问」是表示关心安慰，与「乱收钱」的会员不符。"}, "sentence_index": 6, "correct_answer": "开除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察开除了他的违禁品。", "explanation": "这里应该用〈没收〉。「开除」只用于人及其身份，不能用于物品。"}, {"text": "警察开除了那个小偷。", "explanation": "这里应该用〈逮捕〉。「开除」是取消身份、令人离开集体，不是对罪犯采取的强制措施。"}, {"text": "我因为想换工作，就开除了自己。", "explanation": "「开除」的施事是学校或单位，不能用于自己离职，应说辞职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把他开除。", "corrected_sentence": "学校把他开除了。", "error_description": "错误：「把」字句缺少「了」。正确：「把」字句要表示完成的动作，应说「学校把他开除了」，只说「开除」句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "食堂把偷东西的那个厨师开除。", "corrected_sentence": "食堂把偷东西的那个厨师开除了。", "error_description": "错误：「把」字句缺少「了」。正确：「把」字句要表示完成的动作，应说「把偷东西的那个厨师开除了」，只说「开除」句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
