INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "职位或席位中居第一位的。", "primary_collocate": null, "pronunciation": "shǒu xí", "ipa": "ʂoʊ˨˩ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "他担任乐团的首席，负责带领大家排练。", "target_word": "首席", "complexity_tier": "T3", "furigana": "tā dān rèn lè tuán de shǒu xí, fù zé dài lǐng dà jiā pái liàn.", "sentence_source": "generated"}, {"text": "她是乐团的首席小提琴手。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位首席记者去过很多国家。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首席代表今天会见了客人。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王博士被请来做首席科学家。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的首席设计师刚到公司。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首席律师在会上说了几句话。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了三年首席翻译。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首席大提琴手坐在最前面。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院请了一位新的首席专家。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "首席：职位或席位中居第一位的，如首席执行官、首席小提琴手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daefa5e4-da06-49ae-91b6-3464485ab917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手提", "is_correct": false, "explanation": "tí（第二声）与 xí（第二声）只有声母不同，意思是用手拿着，如手提包。"}, {"text": "首席", "is_correct": true, "explanation": "正确答案。首席指职位或席位居第一位的人。"}, {"text": "手洗", "is_correct": false, "explanation": "xǐ（第三声）与 xí（第二声）声调不同，意思是用手洗。"}, {"text": "手旗", "is_correct": false, "explanation": "qí（第二声）与 xí（第二声）只有声母不同，意思是挥动的小旗。"}, {"text": "守时", "is_correct": false, "explanation": "shí（第二声）与 xí（第二声）只有声母不同，意思是遵守时间。"}], "explanations": {"手提": "tí（第二声）与 xí（第二声）只有声母不同，意思是用手拿着，如手提包。", "首席": "正确答案。首席指职位或席位居第一位的人。", "手洗": "xǐ（第三声）与 xí（第二声）声调不同，意思是用手洗。", "手旗": "qí（第二声）与 xí（第二声）只有声母不同，意思是挥动的小旗。", "守时": "shí（第二声）与 xí（第二声）只有声母不同，意思是遵守时间。"}, "sentence_index": null, "correct_answer": "首席"}, "level_3": {"options": [{"text": "首席", "is_correct": true, "explanation": "正确答案。“首席”指乐团中居第一位的乐手或负责人，与“担任”和“负责带领大家排练”相符。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是台下听演出的人，不能被“担任”为乐团的职务。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是能担任职务、带领排练的人。"}, {"text": "节目", "is_correct": false, "explanation": "搭配：“担任”后接职务，不能说“担任节目”。"}], "explanations": {"首席": "正确答案。“首席”指乐团中居第一位的乐手或负责人，与“担任”和“负责带领大家排练”相符。", "观众": "语义：观众是台下听演出的人，不能被“担任”为乐团的职务。", "钢琴": "语义：钢琴是乐器，不是能担任职务、带领排练的人。", "节目": "搭配：“担任”后接职务，不能说“担任节目”。"}, "sentence_index": 0, "correct_answer": "首席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我是班里的首席，超过了所有人。", "explanation": "这里应该用〈第一名〉。首席指职位或席位上居第一的人，不用来表示考试名次；考试排名应说“第一名”。"}, {"text": "这家餐厅的首席菜是烤鸭。", "explanation": "首席只用于人员的职位或席位，不修饰菜肴。这里应说“招牌菜”，表示餐厅最有名的菜。"}, {"text": "排队时他站在首席。", "explanation": "这里应该用〈首位〉。首席指职位上的第一位，排队次序要说“首位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91654, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手持", "is_correct": false, "explanation": "chí（第二声）与 xí（第二声）只有声母不同，意思是用手拿着。"}, {"text": "首集", "is_correct": false, "explanation": "jí（第二声）与 xí（第二声）只有声母不同，意思是第一集。"}, {"text": "首席", "is_correct": true, "explanation": "正确答案。首席指职位或席位居第一位的人。"}, {"text": "手旗", "is_correct": false, "explanation": "qí（第二声）与 xí（第二声）只有声母不同，意思是挥动的小旗。"}, {"text": "守时", "is_correct": false, "explanation": "shí（第二声）与 xí（第二声）只有声母不同，意思是遵守时间。"}], "explanations": {"手持": "chí（第二声）与 xí（第二声）只有声母不同，意思是用手拿着。", "首集": "jí（第二声）与 xí（第二声）只有声母不同，意思是第一集。", "首席": "正确答案。首席指职位或席位居第一位的人。", "手旗": "qí（第二声）与 xí（第二声）只有声母不同，意思是挥动的小旗。", "守时": "shí（第二声）与 xí（第二声）只有声母不同，意思是遵守时间。"}, "sentence_index": null, "correct_answer": "首席"}, "level_3": {"options": [{"text": "首席", "is_correct": true, "explanation": "正确答案。“首席律师”指律所或机构中居第一位的律师，与句中的说话情境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与律师的职业身份不相关，不能用来修饰律师。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不是律师的职业类别，无法修饰律师。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“花园”不能用来限定“律师”这一职业。"}], "explanations": {"首席": "正确答案。“首席律师”指律所或机构中居第一位的律师，与句中的说话情境相符。", "游泳": "语义：游泳与律师的职业身份不相关，不能用来修饰律师。", "厨房": "语义：厨房是场所，不是律师的职业类别，无法修饰律师。", "花园": "搭配：“花园”不能用来限定“律师”这一职业。"}, "sentence_index": 6, "correct_answer": "首席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗是家里的首席。", "explanation": "这里把“首席”当成“最受宠、最突出”的意思，指家里最受宠的狗。“首席”只指排第一位的职务或席位，不能用来形容宠物；这里应说“最受宠”。"}, {"text": "我们公司的首席部门是财务部。", "explanation": "这里把“首席”当成“最重要”的意思，说公司最重要的部门。“首席”只修饰人员的职务或席位，不修饰机构；表示最重要的部门应说“核心部门”。"}, {"text": "这学期的首席是三月。", "explanation": "这里把“首席”当成“第一个”的意思，指学期的第一个月。“首席”指职位或席位上排第一的人，不能用来指时间的先后；第一个月应说“第一个月”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是公司的首席的律师。", "corrected_sentence": "她是公司的首席律师。", "error_description": "多加了“的”：“首席”作定语时直接修饰名词，不加“的”，应说“首席律师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的首席的执行官是一位女士。", "corrected_sentence": "这家公司的首席执行官是一位女士。", "error_description": "多加了“的”：“首席”修饰“执行官”时直接作定语，不加“的”，应说“首席执行官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
