INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91655, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军阀是拿着军队，占着一块地方的人。", "primary_collocate": null, "pronunciation": "jūn fá", "ipa": "tɕyn˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "那时候，这个地方有一个军阀。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀手里有很多兵。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓都怕这个军阀。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个军阀占着一座大城。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷小时候见过军阀。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的军阀总是很凶。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀住在城里最大的房子里。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位军阀每年向农民要很多粮食。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了一个有名的军阀。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀带着兵走进了小镇。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "军阀混战", "label": "复合"}, {"form": "軍閥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "手里有军队、占着一块地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a13f3c-7d80-4a9a-8407-2021ae5c1faf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91655, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军阀", "is_correct": true, "explanation": "jūn fá 指拥有军队、割据一方的人，正确答案。"}, {"text": "军法", "is_correct": false, "explanation": "jūn fǎ 与 jūn fá 第二音节声调不同（第三声与第二声），意思是军队的法律。"}, {"text": "军服", "is_correct": false, "explanation": "jūn fú 与 jūn fá 第二音节韵母不同（-u 与 -a），意思是军队的服装。"}, {"text": "军费", "is_correct": false, "explanation": "jūn fèi 与 jūn fá 第二音节韵母和声调都不同（-ei 与 -a），意思是军队的经费。"}], "explanations": {"军阀": "jūn fá 指拥有军队、割据一方的人，正确答案。", "军法": "jūn fǎ 与 jūn fá 第二音节声调不同（第三声与第二声），意思是军队的法律。", "军服": "jūn fú 与 jūn fá 第二音节韵母不同（-u 与 -a），意思是军队的服装。", "军费": "jūn fèi 与 jūn fá 第二音节韵母和声调都不同（-ei 与 -a），意思是军队的经费。"}, "sentence_index": null, "correct_answer": "军阀"}, "level_3": {"options": [{"text": "军阀", "is_correct": true, "explanation": "军阀指拥有军队、割据一方的人，这里指那时候占据这个地方的人。"}, {"text": "手机", "is_correct": false, "explanation": "语义：那时候还没有手机，与“那时候”的时间背景不合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：那时候还没有普及电脑，与“那时候”的时间背景不合。"}, {"text": "互联网", "is_correct": false, "explanation": "语义：那时候还没有互联网，与“那时候”的时间背景不合。"}], "explanations": {"军阀": "军阀指拥有军队、割据一方的人，这里指那时候占据这个地方的人。", "手机": "语义：那时候还没有手机，与“那时候”的时间背景不合。", "电脑": "语义：那时候还没有普及电脑，与“那时候”的时间背景不合。", "互联网": "语义：那时候还没有互联网，与“那时候”的时间背景不合。"}, "sentence_index": 0, "correct_answer": "军阀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军阀每天在地里种庄稼。", "explanation": "这里应该用〈农民〉。在地里种庄稼的是农民；军阀指拥兵割据、占着一块地方的人，不用来指种地的人。"}, {"text": "军阀在厨房里做饭。", "explanation": "这里应该用〈厨师〉。在厨房里做饭的是厨师；军阀指拥有军队的人，不用来指做饭的人。"}, {"text": "军阀在工厂里装配机器。", "explanation": "这里应该用〈工人〉。在工厂里装配机器的是工人；军阀不用来指干体力活的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军阀", "is_correct": true, "explanation": "军阀指拥兵割据的人，这里指能住在城里最大房子里的人。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐没有钱住在城里最大的房子里，与句意不合。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠是动物，不能住在人住的大房子里，句意不合。"}, {"text": "小草", "is_correct": false, "explanation": "语义：小草是植物，不能住在房子里，与句意不合。"}], "explanations": {"军阀": "军阀指拥兵割据的人，这里指能住在城里最大房子里的人。", "乞丐": "语义：乞丐没有钱住在城里最大的房子里，与句意不合。", "老鼠": "语义：老鼠是动物，不能住在人住的大房子里，句意不合。", "小草": "语义：小草是植物，不能住在房子里，与句意不合。"}, "sentence_index": 6, "correct_answer": "军阀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "军阀在大学里给学生上课。", "explanation": "这里应该用〈教授〉。教授是在大学里讲课的人；军阀指拥兵割据的人，不用来指教师。"}, {"text": "军阀开车送乘客去车站。", "explanation": "这里应该用〈司机〉。送乘客的是司机；军阀不用来指开车载客的人。"}, {"text": "军阀给病人换药。", "explanation": "这里应该用〈护士〉。给病人换药是护士的工作；军阀不用来指护理病人的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那两只军阀占了这个省。", "corrected_sentence": "那两个军阀占了这个省。", "error_description": "量词误用：指人的名词不用“只”（“只”用于动物等），应说“那两个军阀”，不说“那两只军阀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那三个的军阀占了这个省。", "corrected_sentence": "那三个军阀占了这个省。", "error_description": "“的”误加：数量词直接修饰名词时不加“的”，应说“那三个军阀”，不说“那三个的军阀”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
