INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拥有军队并割据一方、争夺权力的人。", "primary_collocate": null, "pronunciation": "jūn fá", "ipa": "tɕyn˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "几个军阀为了争地盘打了很多年仗。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民国时期，各地的军阀互相打仗。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀们都想得到更大的权力。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个军阀不听政府的话，自己管一方。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀打来打去，老百姓过得很苦。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个军阀为了抢城市，打了起来。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，老师讲了军阀割据的过程。", "target_word": "军阀", "complexity_tier": "T3", "furigana": "lì shǐ kè shàng, lǎo shī jiǎng le jūn fá gē jù de guò chéng.", "sentence_source": "generated"}, {"text": "北方的军阀想抢南方的地方。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位军阀带兵占了三个省。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀之间常常先合作，后又打起来。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "军阀混战", "label": "复合"}, {"form": "軍閥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "拥兵割据一方并互相争夺权力的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a13f3c-7d80-4a9a-8407-2021ae5c1faf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军阀", "is_correct": true, "explanation": "jūn fá 指拥有军队、割据一方的人，正确答案。"}, {"text": "军法", "is_correct": false, "explanation": "jūn fǎ 与 jūn fá 第二音节声调不同（第三声与第二声），意思是军队的法律。"}, {"text": "军服", "is_correct": false, "explanation": "jūn fú 与 jūn fá 第二音节韵母不同（-u 与 -a），意思是军队的服装。"}, {"text": "军费", "is_correct": false, "explanation": "jūn fèi 与 jūn fá 第二音节韵母和声调都不同（-ei 与 -a），意思是军队的经费。"}], "explanations": {"军阀": "jūn fá 指拥有军队、割据一方的人，正确答案。", "军法": "jūn fǎ 与 jūn fá 第二音节声调不同（第三声与第二声），意思是军队的法律。", "军服": "jūn fú 与 jūn fá 第二音节韵母不同（-u 与 -a），意思是军队的服装。", "军费": "jūn fèi 与 jūn fá 第二音节韵母和声调都不同（-ei 与 -a），意思是军队的经费。"}, "sentence_index": null, "correct_answer": "军阀"}, "level_3": {"options": [{"text": "军阀", "is_correct": true, "explanation": "军阀指拥兵割据的人，这里指为争地盘打仗的人。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不会为争地盘打仗，与句中的意思不合。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不会为争地盘打仗，与句中的意思不合。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“学生”与“为争地盘打了很多年仗”这一描述不搭配。"}], "explanations": {"军阀": "军阀指拥兵割据的人，这里指为争地盘打仗的人。", "厨师": "语义：厨师不会为争地盘打仗，与句中的意思不合。", "游客": "语义：游客不会为争地盘打仗，与句中的意思不合。", "学生": "搭配：“学生”与“为争地盘打了很多年仗”这一描述不搭配。"}, "sentence_index": 0, "correct_answer": "军阀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军阀在码头上卸货。", "explanation": "这里应该用〈工人〉。在码头上卸货的是工人；军阀拥兵割据、争夺权力，不用来指干体力活的人。"}, {"text": "军阀在公园里扫落叶。", "explanation": "这里应该用〈清洁工〉。在公园里扫落叶的是清洁工；军阀不用来指打扫卫生的人。"}, {"text": "军阀每天在地里干活。", "explanation": "这里应该用〈农民〉。在地里干活的是农民；军阀指拥兵割据的人，不用来指种地的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军阀", "is_correct": true, "explanation": "军阀指拥兵割据的人，“军阀割据”是常用搭配，与句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不会割据一方，“厨师割据”与历史内容不合。"}, {"text": "歌星", "is_correct": false, "explanation": "语义：歌星不会割据地方，与历史课上讲的内容不合。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“割据”指占据地方、拥兵自立，不与“学校”搭配。"}], "explanations": {"军阀": "军阀指拥兵割据的人，“军阀割据”是常用搭配，与句意相符。", "厨师": "语义：厨师不会割据一方，“厨师割据”与历史内容不合。", "歌星": "语义：歌星不会割据地方，与历史课上讲的内容不合。", "学校": "搭配：“割据”指占据地方、拥兵自立，不与“学校”搭配。"}, "sentence_index": 6, "correct_answer": "军阀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "军阀给病人治病。", "explanation": "这里应该用〈医生〉。给病人治病的是医生；军阀指拥兵割据的人，不用来指医务人员。"}, {"text": "军阀在教室里认真听讲。", "explanation": "这里应该用〈学生〉。认真听讲的是学生；军阀不用来指在教室里听课的人。"}, {"text": "军阀在厨房里做饭。", "explanation": "这里应该用〈厨师〉。在厨房做饭的是厨师；军阀不用来指做饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一座军阀带着兵打进了城。", "corrected_sentence": "一个军阀带着兵打进了城。", "error_description": "量词错误：“军阀”指人，应用量词“个”或“位”，“座”用于建筑等，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个的军阀抢了一座城。", "corrected_sentence": "两个军阀抢了一座城。", "error_description": "“的”误加：数量词直接修饰名词时不加“的”，应说“两个军阀”，不说“两个的军阀”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae66055-78bc-4a20-aa55-41919c166bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
