INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91657, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "局长是一个局里管事的最大的人。", "primary_collocate": null, "pronunciation": "jú zhǎng", "ipa": "tɕy˧˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "局长在办公室里开会。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们局长今天不在。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长是这个局里最大的领导。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作很努力，后来当上了局长。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长让大家明天早上八点到。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的局长对工作人员很好。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这份文件交给局长。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长每天都很忙，没有时间吃午饭。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸是警察局的局长。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长听了大家的话，点点头。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位局长", "label": "量词搭配"}, {"form": "副局长", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个局里管事的最大的人，也就是最高领导", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27aa1c00-fc1e-4f9c-85cd-83e1806a40ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局长", "is_correct": true, "explanation": "“局长”是局里管事的最大的人，能在办公室里开会，句子通顺。"}, {"text": "猫", "is_correct": false, "explanation": "配价：“开会”的主语必须是人，“猫”不能开会。"}, {"text": "大象", "is_correct": false, "explanation": "配价：“开会”的主语必须是人，“大象”不能开会。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有生命，不能在办公室里开会，句子说不通。"}], "explanations": {"局长": "“局长”是局里管事的最大的人，能在办公室里开会，句子通顺。", "猫": "配价：“开会”的主语必须是人，“猫”不能开会。", "大象": "配价：“开会”的主语必须是人，“大象”不能开会。", "石头": "语义：“石头”没有生命，不能在办公室里开会，句子说不通。"}, "sentence_index": 0, "correct_answer": "局长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的局长上个月换了。", "explanation": "这里应该用〈厂长〉。“局长”是政府部门的负责人，工厂应用“厂长”。"}, {"text": "我们单位来了一只局长。", "explanation": "这里应该用〈位〉。指人的“局长”用“位”，“只”多用于动物或成对的物品。"}, {"text": "这所学校的局长很和蔼。", "explanation": "这里应该用〈校长〉。“局长”管政府部门，学校应用“校长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局长", "is_correct": true, "explanation": "“交给局长”符合句意，文件应交给有权处理的负责人。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“交给”的对象需要是人，“桌子”不能接收文件。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不能接收文件，“交给空气”说不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：“树”不能接收文件，“交给树”说不通。"}], "explanations": {"局长": "“交给局长”符合句意，文件应交给有权处理的负责人。", "桌子": "配价：“交给”的对象需要是人，“桌子”不能接收文件。", "空气": "语义：“空气”不能接收文件，“交给空气”说不通。", "树": "语义：“树”不能接收文件，“交给树”说不通。"}, "sentence_index": 6, "correct_answer": "局长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的局长每天来得很早。", "explanation": "这里应该用〈总经理〉。“局长”是政府部门的负责人，公司应用“总经理”。"}, {"text": "我们楼里走来一条局长。", "explanation": "这里应该用〈位〉。指人的“局长”用“位”，“条”用于细长的东西，不能用于人。"}, {"text": "报社的局长昨天来了。", "explanation": "这里应该用〈社长〉。“局长”管政府部门，报社应用“社长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们局里来了一只新局长。", "corrected_sentence": "我们局里来了一位新局长。", "error_description": "“局长”指人，量词应用“位”，不能用“只”（“只”多用于动物或成对的物品）。应把“一只”改为“一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一头局长来到了我们单位。", "corrected_sentence": "一位局长来到了我们单位。", "error_description": "“局长”指人，量词应用“位”；“头”用于牛、猪等动物，不能用于人。应把“一头”改为“一位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5f80b7-d62b-4cf4-a8a7-8b65295a23e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
