INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山上最高的地方。", "primary_collocate": null, "pronunciation": "gāo fēng", "ipa": "kɑʊ˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这座山的高峰有三千米高。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们终于爬到了山的高峰。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高峰上有很多雪，天气非常冷。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在高峰上，可以看到远处的云。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处那座高峰，一年四季都有白雪。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们爬了一天，才走到这座山的高峰。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很好，我在高峰上拍了很多照片。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的高峰很高，爬山的人要带上厚衣服。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳出来的时候，高峰先亮了。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山的高峰常常在云里，很难看清。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "一座山最高、最尖的那一处山峰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a6645ab-78ba-4186-8461-e21091544327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高峰", "is_correct": true, "explanation": "高峰：山上最高的地方。"}, {"text": "高分", "is_correct": false, "explanation": "fēn（第一声）与 fēng（第一声）韵尾不同（-n 与 -ng），意思是高分，即分数高。"}, {"text": "刀锋", "is_correct": false, "explanation": "dāo 与 gāo 声母不同（d 与 g），意思是刀刃的锋利部分。"}, {"text": "交锋", "is_correct": false, "explanation": "jiāo 与 gāo 声母不同（j 与 g），意思是双方交战或激烈辩论。"}], "explanations": {"高峰": "高峰：山上最高的地方。", "高分": "fēn（第一声）与 fēng（第一声）韵尾不同（-n 与 -ng），意思是高分，即分数高。", "刀锋": "dāo 与 gāo 声母不同（d 与 g），意思是刀刃的锋利部分。", "交锋": "jiāo 与 gāo 声母不同（j 与 g），意思是双方交战或激烈辩论。"}, "sentence_index": null, "correct_answer": "高峰"}, "level_3": {"options": [{"text": "山谷", "is_correct": false, "explanation": "语义：“山谷”是两山之间的低洼处，说它“有三千米高”不合常理。"}, {"text": "高峰", "is_correct": true, "explanation": "高峰：山上最高的地方，与“有三千米高”的高度描述相符。"}, {"text": "山洞", "is_correct": false, "explanation": "语义：“山洞”是山体内部的空间，不能说它“有三千米高”，句子说不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是水流的通道，不能说它“有三千米高”，句子说不通。"}], "explanations": {"山谷": "语义：“山谷”是两山之间的低洼处，说它“有三千米高”不合常理。", "高峰": "高峰：山上最高的地方，与“有三千米高”的高度描述相符。", "山洞": "语义：“山洞”是山体内部的空间，不能说它“有三千米高”，句子说不通。", "河流": "语义：“河流”是水流的通道，不能说它“有三千米高”，句子说不通。"}, "sentence_index": 0, "correct_answer": "高峰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的事业终于到了高峰，然后慢慢下降。", "explanation": "句中的高峰用的是抽象义（事物发展的最高点），与本词条指山上最高的地方不同，不符合本义。"}, {"text": "这部电影的票房到了高峰。", "explanation": "句中的高峰用的是抽象义（数量或水平达到的最高点），与本词条指山上最高的地方不同，不符合本义。"}, {"text": "考试期间是学习的高峰，图书馆里挤满了人。", "explanation": "句中的高峰用的是抽象义（最忙的阶段），与本词条指山上最高的地方不同，不符合本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高峰", "is_correct": true, "explanation": "高峰：山上最高的地方。"}, {"text": "高僧", "is_correct": false, "explanation": "sēng 与 fēng 声母不同（s 与 f），意思是德高望重的僧人。"}, {"text": "高升", "is_correct": false, "explanation": "shēng 与 fēng 声母不同（sh 与 f），意思是职位或地位提高。"}, {"text": "高飞", "is_correct": false, "explanation": "fēi 与 fēng 韵尾不同（-i 与 -ng），意思是高高地飞。"}], "explanations": {"高峰": "高峰：山上最高的地方。", "高僧": "sēng 与 fēng 声母不同（s 与 f），意思是德高望重的僧人。", "高升": "shēng 与 fēng 声母不同（sh 与 f），意思是职位或地位提高。", "高飞": "fēi 与 fēng 韵尾不同（-i 与 -ng），意思是高高地飞。"}, "sentence_index": null, "correct_answer": "高峰"}, "level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”是天体，人不能“在太阳上”拍照，句子说不通。"}, {"text": "春天", "is_correct": false, "explanation": "配价：“在……上”需要处所，“春天”是时间，不能作站立或拍照的地点。"}, {"text": "高峰", "is_correct": true, "explanation": "高峰：山上最高的地方，人可以站在上面拍照。"}, {"text": "冬天", "is_correct": false, "explanation": "配价：“在……上”需要处所，“冬天”是时间，不能作拍照的地点。"}], "explanations": {"太阳": "语义：“太阳”是天体，人不能“在太阳上”拍照，句子说不通。", "春天": "配价：“在……上”需要处所，“春天”是时间，不能作站立或拍照的地点。", "高峰": "高峰：山上最高的地方，人可以站在上面拍照。", "冬天": "配价：“在……上”需要处所，“冬天”是时间，不能作拍照的地点。"}, "sentence_index": 6, "correct_answer": "高峰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的购物高峰比去年来得早。", "explanation": "句中的高峰用的是抽象义（最忙的购物阶段），与本词条指山上最高的地方不同，不符合本义。"}, {"text": "春运的客流已经到了高峰。", "explanation": "句中的高峰用的是抽象义（人流最多的阶段），与本词条指山上最高的地方不同，不符合本义。"}, {"text": "两国的高峰会谈定在下个月举行。", "explanation": "高峰在这里指“首脑级别的会议”（高峰会），与本词条“山上最高的地方”不同，不符合本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山有一条高峰，常年有雪。", "corrected_sentence": "这座山有一座高峰，常年有雪。", "error_description": "量词误用：山峰应搭配量词“座”；“条”多用于河流、道路等长条形事物，说“一条高峰”不符合习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条高峰很陡，不好爬。", "corrected_sentence": "那座高峰很陡，不好爬。", "error_description": "量词误用：“高峰”指山顶，应搭配量词“座”；“条”多用于河流、道路等长条形事物，说“那条高峰”不符合习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91666, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低谷", "is_correct": true, "explanation": "低谷与高峰构成反义：高峰指发展或数量的最高点，低谷指最低点。"}, {"text": "起点", "is_correct": false, "explanation": "起点指开始的地方，与“最高点”不构成反义。"}, {"text": "中段", "is_correct": false, "explanation": "中段指中间的部分，与高峰不构成反义。"}, {"text": "边缘", "is_correct": false, "explanation": "边缘指事物的外沿，与高峰不构成反义。"}], "correct_answer": "低谷", "explanations": {"低谷": "低谷与高峰构成反义：高峰指发展或数量的最高点，低谷指最低点。", "起点": "起点指开始的地方，与“最高点”不构成反义。", "中段": "中段指中间的部分，与高峰不构成反义。", "边缘": "边缘指事物的外沿，与高峰不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
