INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91669, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "库是放很多东西的大房子。", "primary_collocate": null, "pronunciation": "kù", "ipa": "kʰu˥˩", "syllable_count": 1, "sentences": [{"text": "这个库里放着很多桌子和椅子。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校后面有一个大库，里面是体育用品。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把箱子搬到库里去。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "库里很冷，要多穿一件衣服。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在库里找了半天，才找到那把梯子。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个库太小，放不下这么多东西。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "库里黑黑的，我们带着手电筒进去。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，货先放在库里，不要放外面。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家后院有个小库，爸爸用它放工具。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "库里的东西很多，找起来不容易。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "仓库", "label": "复合"}, {"form": "车库", "label": "复合"}, {"form": "座", "label": "量词"}, {"form": "庫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来放很多东西的大房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de7e825-ef28-4954-9ae4-9a37f9d8ffad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91669, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "库", "is_correct": true, "explanation": "库：放很多东西的大房子，是本题的目标词。"}, {"text": "苦", "is_correct": false, "explanation": "kǔ（第三声）与 kù（第四声）声调不同，意思是“苦”，指味道或生活艰难。"}, {"text": "哭", "is_correct": false, "explanation": "kū（第一声）与 kù（第四声）声调不同，意思是“哭”，指流眼泪。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 kù 声母不同（q 与 k），意思是“去”，表示到某处。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 kù 韵母不同（e 与 u），意思是“课”，如上课、课本。"}], "explanations": {"库": "库：放很多东西的大房子，是本题的目标词。", "苦": "kǔ（第三声）与 kù（第四声）声调不同，意思是“苦”，指味道或生活艰难。", "哭": "kū（第一声）与 kù（第四声）声调不同，意思是“哭”，指流眼泪。", "去": "qù 与 kù 声母不同（q 与 k），意思是“去”，表示到某处。", "课": "kè 与 kù 韵母不同（e 与 u），意思是“课”，如上课、课本。"}, "sentence_index": null, "correct_answer": "库"}, "level_3": {"options": [{"text": "库", "is_correct": true, "explanation": "正确：库是放很多东西的大房子，“这个库里放着很多桌子和椅子”符合语境。"}, {"text": "杯", "is_correct": false, "explanation": "语义：杯子容量太小，放不下很多桌子和椅子，与“很多”矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包装不下桌子和椅子，与“很多桌子和椅子”矛盾。"}, {"text": "口袋", "is_correct": false, "explanation": "搭配：口袋只装小物件，不说装桌子和椅子。"}], "explanations": {"库": "正确：库是放很多东西的大房子，“这个库里放着很多桌子和椅子”符合语境。", "杯": "语义：杯子容量太小，放不下很多桌子和椅子，与“很多”矛盾。", "书包": "语义：书包装不下桌子和椅子，与“很多桌子和椅子”矛盾。", "口袋": "搭配：口袋只装小物件，不说装桌子和椅子。"}, "sentence_index": 0, "correct_answer": "库"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "库里坐满了学生，老师在讲课。", "explanation": "这里应该用〈教室〉。库是放东西的房子，不是学生上课的地方，不能坐满学生听课。"}, {"text": "库里的服务员很热情，客人吃得很满意。", "explanation": "这里应该用〈餐厅〉。库是放东西的房子，不招待客人吃饭，也没有服务员。"}, {"text": "库放在桌上，很厚。", "explanation": "这里应该用〈书〉。库是放东西的大房子，不是可以放在桌上的书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91669, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "库", "is_correct": true, "explanation": "库：放很多东西的大房子，是本题的目标词。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 kù 韵母不同（e 与 u），意思是“客人”。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 kù 声母不同（g 与 k，不送气与送气相对），意思是“缘故”，如故事中的“故”。"}, {"text": "户", "is_correct": false, "explanation": "hù 与 kù 声母不同（h 与 k），意思是“门户、住户”。"}, {"text": "枯", "is_correct": false, "explanation": "kū（第一声）与 kù（第四声）声调不同，意思是“干枯、枯萎”。"}], "explanations": {"库": "库：放很多东西的大房子，是本题的目标词。", "客": "kè 与 kù 韵母不同（e 与 u），意思是“客人”。", "故": "gù 与 kù 声母不同（g 与 k，不送气与送气相对），意思是“缘故”，如故事中的“故”。", "户": "hù 与 kù 声母不同（h 与 k），意思是“门户、住户”。", "枯": "kū（第一声）与 kù（第四声）声调不同，意思是“干枯、枯萎”。"}, "sentence_index": null, "correct_answer": "库"}, "level_3": {"options": [{"text": "库", "is_correct": true, "explanation": "正确：库是放东西的大房子，“库里黑黑的，我们带着手电筒进去”符合语境。"}, {"text": "字", "is_correct": false, "explanation": "语义：字是文字，没有空间可以走进去，与“带着手电筒进去”不符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是能走进去的空间，与“进去”的动作矛盾。"}, {"text": "皮包", "is_correct": false, "explanation": "搭配：“进去”的对象一般是房间、洞穴等空间，不说走进皮包里。"}], "explanations": {"库": "正确：库是放东西的大房子，“库里黑黑的，我们带着手电筒进去”符合语境。", "字": "语义：字是文字，没有空间可以走进去，与“带着手电筒进去”不符。", "天空": "语义：天空不是能走进去的空间，与“进去”的动作矛盾。", "皮包": "搭配：“进去”的对象一般是房间、洞穴等空间，不说走进皮包里。"}, "sentence_index": 6, "correct_answer": "库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "库里的老师很多，学生们都很喜欢。", "explanation": "这里应该用〈学校〉。库是放东西的房子，不是教书育人的地方。"}, {"text": "库里的孩子们在玩滑梯，大家都很开心。", "explanation": "这里应该用〈游乐场〉。库是放东西的房子，没有滑梯，也不是孩子们玩耍的地方。"}, {"text": "库里的病人很多，医生们都很忙。", "explanation": "这里应该用〈医院〉。库是放东西的房子，不是给病人看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村口那台旧库已经空了很久。", "corrected_sentence": "村口那座旧库已经空了很久。", "error_description": "量词错误：库是房子，应用「座」；「台」用于机器、设备，不能用于库。应改为「那座旧库」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "后院那辆旧库已经拆掉了，只剩一块空地。", "corrected_sentence": "后院那座旧库已经拆掉了，只剩一块空地。", "error_description": "量词错误：「辆」用于车辆，不能用于库。库是建筑，应用「座」，应改为「后院那座旧库」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
