INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "性格是一个人的脾气，比如爱笑、胆小，或者很勇敢。", "primary_collocate": null, "pronunciation": "xìng gé", "ipa": "ɕiŋ˥˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "小李爱笑，性格特别好。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是他的性格，他不是故意的。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟胆子小，性格有点害羞。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的性格很勇敢，什么都不怕。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢性格开心的朋友。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈性格温和，对谁都很客气。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎的长相一样，性格却不同。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格急，吃饭也很快。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我女儿的性格很活泼。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的性格都有好的一面。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性格特点", "label": "复合"}, {"form": "性格内向", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人的脾气，如爱笑、胆小、勇敢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de7e825-ef28-4954-9ae4-9a37f9d8ffad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "正确：性格指人的脾气、性情，“小李爱笑，性格特别好”符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高是数值，不能用“特别好”来评价。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄不用“特别好”来评价，“爱笑，年龄特别好”搭配不当。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别只有男、女之分，不能用“特别好”来评价，与“爱笑”也无关。"}], "explanations": {"性格": "正确：性格指人的脾气、性情，“小李爱笑，性格特别好”符合语境。", "身高": "搭配：身高是数值，不能用“特别好”来评价。", "年龄": "搭配：年龄不用“特别好”来评价，“爱笑，年龄特别好”搭配不当。", "性别": "语义：性别只有男、女之分，不能用“特别好”来评价，与“爱笑”也无关。"}, "sentence_index": 0, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的性格是女，今年二十岁。", "explanation": "这里应该用〈性别〉。性格指性情特点，不能说“性格是女”。"}, {"text": "他的性格一米八，很壮实。", "explanation": "这里应该用〈身高〉。性格指性情特点，不能用来说明身体的高矮。"}, {"text": "她的性格五十公斤，很苗条。", "explanation": "这里应该用〈体重〉。性格指性情特点，不能用来说明体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "正确：性格指人的脾气、性情，“双胞胎的长相一样，性格却不同”符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是商品的属性，不能用来说双胞胎之间的差异。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是环境状况，不是人的特点，“长相一样，天气却不同”讲不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：体温一般用“高”“低”“正常”来描述，不与“长相一样”对举。"}], "explanations": {"性格": "正确：性格指人的脾气、性情，“双胞胎的长相一样，性格却不同”符合语境。", "价格": "语义：价格是商品的属性，不能用来说双胞胎之间的差异。", "天气": "语义：天气是环境状况，不是人的特点，“长相一样，天气却不同”讲不通。", "体温": "搭配：体温一般用“高”“低”“正常”来描述，不与“长相一样”对举。"}, "sentence_index": 6, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的性格很好，适合出去玩。", "explanation": "这里应该用〈天气〉。性格只用于人的性情，不能用来形容天气。"}, {"text": "这件衣服的性格很好，穿着很舒服。", "explanation": "这里应该用〈质量〉。性格不用于形容衣服，衣服的好坏要用质量。"}, {"text": "这幅画的性格很鲜艳，很漂亮。", "explanation": "这里应该用〈颜色〉。性格不用于形容画的颜色，颜色要用颜色一词来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟的性格已经变很多，现在很少发脾气。", "corrected_sentence": "弟弟的性格已经变了很多，现在很少发脾气。", "error_description": "体标错误：“已经”表示变化已经发生，动词“变”后须用“了”，漏掉“了”，应说“已经变了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块性格的人很少见，大家都喜欢他。", "corrected_sentence": "这种性格的人很少见，大家都喜欢他。", "error_description": "量词错误：性格是抽象名词，应用「种」；「块」用于片状或块状的东西，不能用于性格。应改为「这种性格」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
