INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人对现实的态度和行为方式中比较稳定的特点。", "primary_collocate": null, "pronunciation": "xìng gé", "ipa": "ɕiŋ˥˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他的性格很开朗，朋友特别多。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥的性格完全不一样。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她性格安静，不喜欢参加热闹的聚会。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的性格受家人影响很大。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得自己是什么性格的人？", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作不太适合性格内向的人。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的性格比好的成绩更重要。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐性格很好，从来不生气。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格像他父亲，做事很认真。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从小事上可以看出一个人的性格。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性格特点", "label": "复合"}, {"form": "性格内向", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "人在态度和行为方式上比较稳定的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de7e825-ef28-4954-9ae4-9a37f9d8ffad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "正确：性格指人在态度和行为方式上比较稳定的特点，“开朗”描述的正是性格。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指体形，不能说“很开朗”，开朗描述的是性情。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有性情，不能说“很开朗”，与“朋友特别多”也无关。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“开朗”形容性情，不修饰成绩，不说“成绩很开朗”。"}], "explanations": {"性格": "正确：性格指人在态度和行为方式上比较稳定的特点，“开朗”描述的正是性格。", "身材": "体貌：身材指体形，不能说“很开朗”，开朗描述的是性情。", "房子": "语义：房子没有性情，不能说“很开朗”，与“朋友特别多”也无关。", "成绩": "搭配：“开朗”形容性情，不修饰成绩，不说“成绩很开朗”。"}, "sentence_index": 0, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的性格很好，运行很快。", "explanation": "这里应该用〈性能〉。性格指人的性情特点，不用来形容电脑；电脑的功能表现要用性能。"}, {"text": "他每次考试的性格都是第一。", "explanation": "这里应该用〈成绩〉。性格指性情特点，不能用来说明考试的结果。"}, {"text": "他的性格很英俊，大家都喜欢他。", "explanation": "这里应该用〈外貌〉。性格指性情特点，不能用“英俊”来形容外表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "正确：性格是人的性情特点，“好的性格比好的成绩更重要”符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能与成绩比较哪个更重要，语义不成立。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是学习用具，不能拿来与成绩比较重要性。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：发型指外形，不是人的内在特质，不能与成绩作“更重要”的比较。"}], "explanations": {"性格": "正确：性格是人的性情特点，“好的性格比好的成绩更重要”符合语境。", "桌子": "语义：桌子是家具，不能与成绩比较哪个更重要，语义不成立。", "书包": "语义：书包是学习用具，不能拿来与成绩比较重要性。", "发型": "体貌：发型指外形，不是人的内在特质，不能与成绩作“更重要”的比较。"}, "sentence_index": 6, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的性格很稳定，不容易变质。", "explanation": "这里应该用〈性质〉。性格只用于人的性情特点，药品的属性要用性质。"}, {"text": "他对工作的性格很认真，从不迟到。", "explanation": "这里应该用〈态度〉。性格指性情特点，对工作的看法和做法要用态度。"}, {"text": "这个桌子的性格很特别，很多人来看。", "explanation": "这里应该用〈形状〉。性格不用于形容家具的外形，外形要用形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的性格已经变很多，大家都觉得很惊讶。", "corrected_sentence": "她的性格已经变了很多，大家都觉得很惊讶。", "error_description": "体标错误：“已经”表示变化已经发生，动词“变”后须用“了”，漏掉“了”，应说“已经变了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里的同学有几个性格，大家各不相同。", "corrected_sentence": "班里的同学有几种性格，大家各不相同。", "error_description": "量词错误：性格是抽象名词，应用“种”；“个”用于可数的人或事物，不能用于性格。应改为“几种性格”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
