INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91687, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "懂得是知道，也明白是怎么回事。", "primary_collocate": null, "pronunciation": "dǒng de", "ipa": "tʊŋ˨˩ tə", "syllable_count": 2, "sentences": [{"text": "他懂得怎么用这台机器。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三岁的孩子不懂得什么是危险。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我懂得你的意思，谢谢你。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她懂得很多中国的节日。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸懂得修车，邻居常找他帮忙。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你懂得为什么天会下雨吗？", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在我懂得老师的话了。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂得这里的规矩。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要懂得保护眼睛。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他懂得做人的道理，所以大家相信他。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不懂得", "label": "否定"}, {"form": "懂得了", "label": "体标"}], "register": "中性", "sense_fingerprint": "知道某事，也明白是怎么回事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de7e825-ef28-4954-9ae4-9a37f9d8ffad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "懂得", "is_correct": true, "explanation": "“懂得”表示知道并明白做法，与“怎么用这台机器”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“怎么用这台机器”作宾语。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”不及物，不能带“这台机器”作宾语。"}, {"text": "批发", "is_correct": false, "explanation": "搭配：“批发”指成批卖货，不能与“怎么用”搭配。"}], "explanations": {"懂得": "“懂得”表示知道并明白做法，与“怎么用这台机器”相符。", "吃": "搭配：“吃”不能带“怎么用这台机器”作宾语。", "生气": "配价：“生气”不及物，不能带“这台机器”作宾语。", "批发": "搭配：“批发”指成批卖货，不能与“怎么用”搭配。"}, "sentence_index": 0, "correct_answer": "懂得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在车站懂得了一位老同学。", "explanation": "这里应该用〈认识〉。“懂得”用于道理、做法，不能说懂得某个人，指人要用“认识”。"}, {"text": "我抬头懂得了天上的飞机。", "explanation": "这里应该用〈看见〉。“懂得”表示明白，不能用于看到具体事物。"}, {"text": "这道菜我懂得了一口。", "explanation": "这里应该用〈尝〉。“懂得”不能用于品尝味道，品尝要用“尝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懂得", "is_correct": true, "explanation": "“懂得”表示明白话的意思，与“老师的话”相符。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指把东西交给别人，“送老师的话”与“明白”的意思不符，句意不通。"}, {"text": "吵", "is_correct": false, "explanation": "配价：“吵”不及物，不能带“老师的话”作宾语。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”指用手触碰，“老师的话”不能被摸。"}], "explanations": {"懂得": "“懂得”表示明白话的意思，与“老师的话”相符。", "送": "语义：“送”指把东西交给别人，“送老师的话”与“明白”的意思不符，句意不通。", "吵": "配价：“吵”不及物，不能带“老师的话”作宾语。", "摸": "搭配：“摸”指用手触碰，“老师的话”不能被摸。"}, "sentence_index": 6, "correct_answer": "懂得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在人群中一眼懂得了那位朋友。", "explanation": "这里应该用〈认得〉。“懂得”针对道理、做法，不能用于辨认人，辨认人要用“认得”。"}, {"text": "我一走进厨房，就懂得了菜的香味。", "explanation": "这里应该用〈闻到〉。“懂得”指明白道理，闻气味要用“闻到”。"}, {"text": "我终于懂得了那个包裹。", "explanation": "这里应该用〈找到〉。“懂得”不能用于具体物品，找到物品要用“找到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐很快懂得的修电脑的方法。", "corrected_sentence": "姐姐很快懂得了修电脑的方法。", "error_description": "助词错误：“懂得”后表示已经明白要用“了”，“的”不能接在动词后面表示完成，应为“懂得了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次我终于懂得着这道题的意思。", "corrected_sentence": "这次我终于懂得了这道题的意思。", "error_description": "体标错误：“懂得”表示已经明白，应用“了”；“着”表示持续状态，“懂得着”不成立。应为“懂得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
