INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91702, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入一个国家或地区的国境。", "primary_collocate": null, "pronunciation": "rù jìng", "ipa": "ɻu˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "入境要带护照。", "target_word": "入境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "入境时，海关检查了我的行李。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入境的人都要填表。", "target_word": "入境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没有签证，不能入境。", "target_word": "入境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的护照过期了，不能入境。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入境时要给海关看护照。", "target_word": "入境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个国家入境很容易，不用签证。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入境的时候，他带了很多现金，海关问了他几句。", "target_word": "入境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在入境前准备好这些文件。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "疫情期间，入境的人要先检查身体。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "入境了", "label": "完成体"}, {"form": "入境过", "label": "经历体"}, {"form": "入境签证", "label": "复合词"}], "register": "中性", "sense_fingerprint": "办理手续、检查证件后进入一国国境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a8897d1-e71b-427d-ba6c-d8eccd14f3cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91702, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入境", "is_correct": true, "explanation": "rù jìng，意思是办理手续后进入一国国境。"}, {"text": "路径", "is_correct": false, "explanation": "lù（第四声）与 rù 声母不同（l 与 r），意思是道路、路线。"}, {"text": "素净", "is_correct": false, "explanation": "sù（第四声）与 rù 声母不同（s 与 r），意思是朴素干净。"}, {"text": "入京", "is_correct": false, "explanation": "jīng（第一声）与 jìng 声调不同，意思是进入首都。"}], "explanations": {"入境": "rù jìng，意思是办理手续后进入一国国境。", "路径": "lù（第四声）与 rù 声母不同（l 与 r），意思是道路、路线。", "素净": "sù（第四声）与 rù 声母不同（s 与 r），意思是朴素干净。", "入京": "jīng（第一声）与 jìng 声调不同，意思是进入首都。"}, "sentence_index": null, "correct_answer": "入境"}, "level_3": {"options": [{"text": "入境", "is_correct": true, "explanation": "正确：“入境”指进入国境，入境时需要带护照。"}, {"text": "入侵", "is_correct": false, "explanation": "语义：“入侵”指武力侵犯，与“要带护照”的办证件行为不符。"}, {"text": "入党", "is_correct": false, "explanation": "语义：“入党”指加入政党，与护照无关，句子不通。"}, {"text": "入股", "is_correct": false, "explanation": "搭配：“入股”通常说公司、股份，不能与“要带护照”搭配。"}], "explanations": {"入境": "正确：“入境”指进入国境，入境时需要带护照。", "入侵": "语义：“入侵”指武力侵犯，与“要带护照”的办证件行为不符。", "入党": "语义：“入党”指加入政党，与护照无关，句子不通。", "入股": "搭配：“入股”通常说公司、股份，不能与“要带护照”搭配。"}, "sentence_index": 0, "correct_answer": "入境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚入境了教室，就开始上课。", "explanation": "这里应该用〈进入〉。入境只指跨过国境进入一国，教室不能作它的宾语。"}, {"text": "他在国外入境了一周。", "explanation": "这里应该用〈停留〉。入境是一次性动作，不能表示持续一周。"}, {"text": "这座小镇昨天刚入境。", "explanation": "这里应该用〈游客〉。入境的主语通常是人、货物或交通工具，小镇不能跨过国境入境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入境", "is_correct": true, "explanation": "正确：“入境”指进入国境，与“不用签证”的语境相关。"}, {"text": "入伍", "is_correct": false, "explanation": "语义：“入伍”指参军，与国境、签证无关，句子不通。"}, {"text": "入住", "is_correct": false, "explanation": "搭配：“入住”用于酒店或住所，不能说国家入住很容易。"}, {"text": "入院", "is_correct": false, "explanation": "语义：“入院”指住进医院，与国家、签证无关。"}], "explanations": {"入境": "正确：“入境”指进入国境，与“不用签证”的语境相关。", "入伍": "语义：“入伍”指参军，与国境、签证无关，句子不通。", "入住": "搭配：“入住”用于酒店或住所，不能说国家入住很容易。", "入院": "语义：“入院”指住进医院，与国家、签证无关。"}, "sentence_index": 6, "correct_answer": "入境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疫情期间，他在家里入境了。", "explanation": "这里应该用〈进门〉。入境指跨过国境，只能发生在口岸，家里不是国境，不能在此入境。"}, {"text": "他下了飞机，就入境了机场大厅。", "explanation": "这里应该用〈走进〉。入境只用于跨过国境，机场大厅不能作入境的宾语。"}, {"text": "这张照片入境了。", "explanation": "这里应该用〈寄到〉。入境的主语通常是人、货物或交通工具，照片要说“这张照片寄到了中国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她入境了前在国外换了钱。", "corrected_sentence": "她入境前在国外换了钱。", "error_description": "错误：“了”插在“入境”和“前”之间。表示“……之前”要说“入境前”，“入境”后面不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天入境着，先去了海关。", "corrected_sentence": "他今天入境了，先去了海关。", "error_description": "错误：“着”用在瞬间动作“入境”后面。“入境”不表示持续状态，应改为“入境了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
