INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91707, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "我们现在数年份时，开头的那一年。", "primary_collocate": null, "pronunciation": "gōng yuán", "ipa": "kʊŋ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "现在我们说的年份，都从公元一年开始数。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公元前一年的下一年，就是公元一年。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写历史时，人们常把公元一年当作起点。", "target_word": "公元", "complexity_tier": "T3", "furigana": "xiě lìshǐ shí, rénmen cháng bǎ gōng yuán yī nián dàngzuò qǐdiǎn.", "sentence_source": "generated"}, {"text": "老师讲完了公元一年以后的历史。", "target_word": "公元", "complexity_tier": "T3", "furigana": "lǎoshī jiǎngwán le gōng yuán yī nián yǐhòu de lìshǐ.", "sentence_source": "generated"}, {"text": "公元一年以前的年份，要加上“前”字。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数年份时，公元一年是最重要的一年。", "target_word": "公元", "complexity_tier": "T3", "furigana": "shǔ niánfèn shí, gōng yuán yī nián shì zuì zhòngyào de yī nián.", "sentence_source": "generated"}, {"text": "数年份时，公元一年之后紧接着就是第二年，历法里没有零年。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书从公元一年讲到今年。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里写着，这件事发生在公元一年。", "target_word": "公元", "complexity_tier": "T3", "furigana": "lìshǐshū lǐ xiězhe, zhè jiàn shì fāshēng zài gōng yuán yī nián.", "sentence_source": "generated"}, {"text": "我们把公元一年当作数年份的开头。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公元前", "label": "复合"}, {"form": "公元后", "label": "复合"}], "register": "书面", "sense_fingerprint": "数年份的起点，公元一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a8897d1-e71b-427d-ba6c-d8eccd14f3cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公元", "is_correct": true, "explanation": "正确：“公元”指国际通用纪年的起点，“公元一年”是数年份的开头。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“公司”是经营机构，不能作为数年份的起点。"}, {"text": "年号", "is_correct": false, "explanation": "搭配：“年号”是帝王纪年名，不说“年号一年”作数年份的起点。"}, {"text": "公里", "is_correct": false, "explanation": "语义：“公里”是长度单位，与年份无关。"}], "explanations": {"公元": "正确：“公元”指国际通用纪年的起点，“公元一年”是数年份的开头。", "公司": "语义：“公司”是经营机构，不能作为数年份的起点。", "年号": "搭配：“年号”是帝王纪年名，不说“年号一年”作数年份的起点。", "公里": "语义：“公里”是长度单位，与年份无关。"}, "sentence_index": 0, "correct_answer": "公元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的公元是一九九〇年。", "explanation": "这里应该用〈出生年〉。公元是通用的纪年名称，不能用来说个人的出生年份。"}, {"text": "他住在公元里。", "explanation": "公元表示时间，不能表示地点，这里应该用〈北京〉之类的地名。"}, {"text": "他把公元送给了朋友。", "explanation": "这里应该用〈礼物〉之类的实物。公元是纪年概念，不能当作东西送人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公元", "is_correct": true, "explanation": "正确：“公元”是纪年名，“公元一年”是纪年的起点，句意完整。"}, {"text": "公安", "is_correct": false, "explanation": "语义：“公安”指公共安全机关，与纪年无关。"}, {"text": "公社", "is_correct": false, "explanation": "语义：“公社”指人民公社一类的组织，不能作年份名。"}, {"text": "公道", "is_correct": false, "explanation": "搭配：“公道”指公正的道理，不能用“一年”计数，不说“公道一年”。"}], "explanations": {"公元": "正确：“公元”是纪年名，“公元一年”是纪年的起点，句意完整。", "公安": "语义：“公安”指公共安全机关，与纪年无关。", "公社": "语义：“公社”指人民公社一类的组织，不能作年份名。", "公道": "搭配：“公道”指公正的道理，不能用“一年”计数，不说“公道一年”。"}, "sentence_index": 6, "correct_answer": "公元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的公元很难。", "explanation": "这里应该用〈题目〉。“很难”形容的是题目，不能用来形容纪年名称公元。"}, {"text": "这座山比公元更高。", "explanation": "这里应该用〈高塔〉之类的实物作比较对象。公元是时间概念，不能比高矮。"}, {"text": "公元是中国的传统节日。", "explanation": "这里应该用〈春节〉之类的节日名。公元是纪年方法，不是节日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师说，公元一个年是年份的起点。", "corrected_sentence": "老师说，公元一年是年份的起点。", "error_description": "错误：在固定纪年说法“公元一年”中不能插入量词“个”，应说“公元一年”，不能说“公元一个年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，这个故事发生在前公元一年左右。", "corrected_sentence": "老师说，这个故事发生在公元一年左右。", "error_description": "错误：“前”加在“公元”前面。“公元前”指公元之前的年份，这里指的是公元一年，应说“公元一年”，不能说“前公元一年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
