INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91708, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国际通用的纪年系统，以传说中耶稣诞生之年为元年。", "primary_collocate": null, "pronunciation": "gōng yuán", "ipa": "kʊŋ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "公元是世界上很多国家都用的纪年方法。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国现在也用公元来记年份。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公元纪年把耶稣诞生的那一年定为元年。", "target_word": "公元", "complexity_tier": "T3", "furigana": "gōng yuán jìnián bǎ Yēsū dànshēng de nà yī nián dìngwéi yuánnián.", "sentence_source": "generated"}, {"text": "除了公元，有的国家还用自己的纪年。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公元纪年让各国交流时更方便。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护照上的日期都是用公元写的。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前中国用年号，现在用公元。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的历史课先讲公元纪年。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公元和农历不是一回事。", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道公元是怎么来的吗？", "target_word": "公元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公元纪年", "label": "复合"}], "register": "书面", "sense_fingerprint": "国际通用的纪年方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a8897d1-e71b-427d-ba6c-d8eccd14f3cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公元", "is_correct": true, "explanation": "正确：“公元”是国际通用的纪年方法，符合句意。"}, {"text": "护照", "is_correct": false, "explanation": "语义：“护照”是出入境证件，不是纪年方法。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“公司”是企业，不能作纪年方法。"}, {"text": "公里", "is_correct": false, "explanation": "搭配：“公里”是长度单位，不能与“纪年方法”搭配。"}], "explanations": {"公元": "正确：“公元”是国际通用的纪年方法，符合句意。", "护照": "语义：“护照”是出入境证件，不是纪年方法。", "公司": "语义：“公司”是企业，不能作纪年方法。", "公里": "搭配：“公里”是长度单位，不能与“纪年方法”搭配。"}, "sentence_index": 0, "correct_answer": "公元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃了三个公元。", "explanation": "这里应该用〈饼〉之类的食物。公元是纪年方法，不能当作食物来吃。"}, {"text": "公元在桌子上。", "explanation": "这里应该用〈书〉之类的实物。公元是纪年名称，不能放在桌子上。"}, {"text": "他今年公元二十岁。", "explanation": "这里应该用〈年龄〉。公元是纪年名称，不能用来说人的岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公元", "is_correct": true, "explanation": "正确：“公元”是现在通用的纪年方法，与“以前用年号”形成对比。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不能作纪年方法。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”是交流工具，不能用来纪年。"}, {"text": "皇帝", "is_correct": false, "explanation": "搭配：“皇帝”是称号，“用”后接的应是纪年方法，不能说“现在用皇帝”。"}], "explanations": {"公元": "正确：“公元”是现在通用的纪年方法，与“以前用年号”形成对比。", "手机": "语义：“手机”是通讯工具，不能作纪年方法。", "语言": "语义：“语言”是交流工具，不能用来纪年。", "皇帝": "搭配：“皇帝”是称号，“用”后接的应是纪年方法，不能说“现在用皇帝”。"}, "sentence_index": 6, "correct_answer": "公元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的公元很难。", "explanation": "这里应该用〈题目〉。“很难”形容的是题目，不能用来形容纪年名称公元。"}, {"text": "这座山比公元更高。", "explanation": "这里应该用〈高塔〉之类的实物作比较对象。公元是时间概念，不能比高矮。"}, {"text": "公元是中国的传统节日。", "explanation": "这里应该用〈春节〉之类的节日名。公元是纪年方法，不是节日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多学校向公元开始讲历史。", "corrected_sentence": "很多学校从公元开始讲历史。", "error_description": "错误：介词用错。表示起点要用“从”，不能用“向”。正确说法是“从公元开始讲历史”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本历史书把公元记年。", "corrected_sentence": "这本历史书用公元记年。", "error_description": "错误：介词“把”用错。“用”后直接带“公元”作宾语，应说“用公元记年”，不能说“把公元记年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91711, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
