INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91713, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公共汽车，供很多人一起乘坐的车。", "primary_collocate": null, "pronunciation": "gōng chē", "ipa": "kʊŋ˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "我每天坐公车去上班。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这路公车很挤，我没有座位。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公车来了，大家一个一个上去。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，公车上人特别多。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在公车上遇到了老同学。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐公车比打车便宜多了。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一班公车已经开走了。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公车站等了二十分钟。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆公车到不到火车站？", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在公车上给老人让了座。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "公车站", "label": "复合"}], "register": "口语", "sense_fingerprint": "很多人一起乘坐的公共汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公车", "is_correct": true, "explanation": "正确：“公车”是公共汽车，可以“坐”着去上班，与前后语境相符。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“公司”是单位，不是可以乘坐的交通工具，“坐公司”说不通。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“坐”后面接的是交通工具，“食堂”是场所，不能说“坐食堂”。"}, {"text": "公寓", "is_correct": false, "explanation": "搭配：“公寓”是住所，不能与“坐”搭配，“坐公寓去上班”不通。"}], "explanations": {"公车": "正确：“公车”是公共汽车，可以“坐”着去上班，与前后语境相符。", "公司": "语义：“公司”是单位，不是可以乘坐的交通工具，“坐公司”说不通。", "食堂": "搭配：“坐”后面接的是交通工具，“食堂”是场所，不能说“坐食堂”。", "公寓": "搭配：“公寓”是住所，不能与“坐”搭配，“坐公寓去上班”不通。"}, "sentence_index": 0, "correct_answer": "公车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨天，公车在铁轨上跑得很慢。", "explanation": "这里应该用〈火车〉。公车是在道路上行驶的汽车，不能在铁轨上跑。"}, {"text": "我下班后打了一辆公车回家。", "explanation": "这里应该用〈出租车〉。“打车”指乘坐出租车，公共汽车要说“坐公车”，不能说“打”。"}, {"text": "车站门口停着一只公车，正等着乘客。", "explanation": "量词用错：“公车”是车辆，量词应用〈辆〉，不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公车", "is_correct": true, "explanation": "正确：“最后一班公车”指末班车，与“已经开走了”相符。"}, {"text": "学校", "is_correct": false, "explanation": "配价：“开走”要求车辆作主语，“学校”不能开走，“最后一班学校”说不通。"}, {"text": "饭馆", "is_correct": false, "explanation": "配价：“饭馆”不是车辆，不能被“开走”，与“最后一班”的车次义不符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“公园”是场所，不是班次，“最后一班公园”没有意义。"}], "explanations": {"公车": "正确：“最后一班公车”指末班车，与“已经开走了”相符。", "学校": "配价：“开走”要求车辆作主语，“学校”不能开走，“最后一班学校”说不通。", "饭馆": "配价：“饭馆”不是车辆，不能被“开走”，与“最后一班”的车次义不符。", "公园": "语义：“公园”是场所，不是班次，“最后一班公园”没有意义。"}, "sentence_index": 6, "correct_answer": "公车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天骑公车去上班。", "explanation": "这里应该用〈自行车〉。“骑”用于自行车、摩托车等，公共汽车是大型车辆，要说“坐公车”。"}, {"text": "他一个人去医院，路上坐了一条公车。", "explanation": "量词用错：“公车”是车辆，应用〈辆〉，不能用“条”。"}, {"text": "我一个人坐公车去上海，车在铁轨上开了一整天。", "explanation": "这里应该用〈火车〉。公车在道路上行驶，不能在铁轨上开，“在铁轨上开”指的是火车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我早上坐了两只公车去医院。", "corrected_sentence": "我早上坐了两辆公车去医院。", "error_description": "错误：量词用错。“公车”是车辆，应用“辆”，不能用“只”，应改为“两辆公车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下班后，我坐公车了回家。", "corrected_sentence": "下班后，我坐公车回家。", "error_description": "错误：宾语“公车”后多加了动态助词“了”。“了”不能放在“公车”后面，“坐公车了回家”不通，应去掉，说“我坐公车回家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
