INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91715, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "现金是你拿在手里的钱，有纸钱和硬币。", "primary_collocate": null, "pronunciation": "xiàn jīn", "ipa": "ɕi̯ɛn˥˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "现金有纸钱，也有硬币。", "target_word": "现金", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我钱包里的现金不多。", "target_word": "现金", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从口袋里拿出一把现金。", "target_word": "现金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年时，爷爷给了我一些现金。", "target_word": "现金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现金放在家里不太安全。", "target_word": "现金", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她数了数手里的现金，一共五百块。", "target_word": "现金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "卖菜的阿姨只收现金，不用手机付款。", "target_word": "现金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢用现金，不喜欢用手机付钱。", "target_word": "现金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把现金放进信封里，再交给老师。", "target_word": "现金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱包里除了现金，还有两张银行卡。", "target_word": "现金", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "現金", "label": "繁体"}, {"form": "现金支付", "label": "复合"}, {"form": "一把现金", "label": "量词"}], "register": "中性", "sense_fingerprint": "现金|拿在手里的纸钞和硬币", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3716686e-219a-4097-9cd6-13972df5123d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91715, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现金", "is_correct": true, "explanation": "正确：现金（xiàn jīn），指拿在手里的纸钞和硬币。"}, {"text": "陷进", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是陷进（陷入）。"}, {"text": "先进", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，jìn（第四声）与 jīn（第一声）声调也不同，意思是先进。"}, {"text": "险境", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，jìng 与 jīn 韵母不同（-ng 与 -n），意思是险境。"}], "explanations": {"现金": "正确：现金（xiàn jīn），指拿在手里的纸钞和硬币。", "陷进": "jìn（第四声）与 jīn（第一声）声调不同，意思是陷进（陷入）。", "先进": "xiān（第一声）与 xiàn（第四声）声调不同，jìn（第四声）与 jīn（第一声）声调也不同，意思是先进。", "险境": "xiǎn（第三声）与 xiàn（第四声）声调不同，jìng 与 jīn 韵母不同（-ng 与 -n），意思是险境。"}, "sentence_index": null, "correct_answer": "现金"}, "level_3": {"options": [{"text": "现金", "is_correct": true, "explanation": "正确：现金指纸钞和硬币，与“有纸钱，也有硬币”相符。"}, {"text": "银行卡", "is_correct": false, "explanation": "语义：银行卡是一种卡片，没有纸钱和硬币。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是电子设备，不可能有纸钱和硬币。"}, {"text": "银两", "is_correct": false, "explanation": "语域：“银两”是古代的说法，口语中不用，而且指白银，不是纸钱。"}], "explanations": {"现金": "正确：现金指纸钞和硬币，与“有纸钱，也有硬币”相符。", "银行卡": "语义：银行卡是一种卡片，没有纸钱和硬币。", "电脑": "语义：电脑是电子设备，不可能有纸钱和硬币。", "银两": "语域：“银两”是古代的说法，口语中不用，而且指白银，不是纸钱。"}, "sentence_index": 0, "correct_answer": "现金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这枚现金很旧。", "explanation": "这里应该用〈硬币〉。“枚”用于单个硬币，现金是纸钞和硬币的总称，不能说“一枚现金”。"}, {"text": "他拿出现金查了余额。", "explanation": "这里应该用〈存折〉。查余额要看存折或账户，现金是手里的纸钞和硬币，不能用来查余额。"}, {"text": "他签了一张现金。", "explanation": "这里应该用〈支票〉。签的是支票这类票据，现金是纸钞和硬币，不能签。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91715, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "现金", "is_correct": true, "explanation": "正确：现金（xiàn jīn），指拿在手里的纸钞和硬币。"}, {"text": "先进", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，jìn（第四声）与 jīn（第一声）声调也不同，意思是先进。"}, {"text": "陷阱", "is_correct": false, "explanation": "jǐng（第三声）与 jīn 的韵母不同（-ng 与 -n），声调也不同，意思是陷阱。"}, {"text": "仙境", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，jìng 与 jīn 韵母不同（-ng 与 -n），意思是仙境。"}], "explanations": {"现金": "正确：现金（xiàn jīn），指拿在手里的纸钞和硬币。", "先进": "xiān（第一声）与 xiàn（第四声）声调不同，jìn（第四声）与 jīn（第一声）声调也不同，意思是先进。", "陷阱": "jǐng（第三声）与 jīn 的韵母不同（-ng 与 -n），声调也不同，意思是陷阱。", "仙境": "xiān（第一声）与 xiàn（第四声）声调不同，jìng 与 jīn 韵母不同（-ng 与 -n），意思是仙境。"}, "sentence_index": null, "correct_answer": "现金"}, "level_3": {"options": [{"text": "现金", "is_correct": true, "explanation": "正确：现金，与“只收”搭配，是可以直接付的钱。"}, {"text": "支付宝", "is_correct": false, "explanation": "语义：支付宝要用手机付款，与“不用手机付款”矛盾。"}, {"text": "钱包", "is_correct": false, "explanation": "搭配：“收”后面接的是钱，不说收钱包。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜不能作为付款的方式，与语境不符。"}], "explanations": {"现金": "正确：现金，与“只收”搭配，是可以直接付的钱。", "支付宝": "语义：支付宝要用手机付款，与“不用手机付款”矛盾。", "钱包": "搭配：“收”后面接的是钱，不说收钱包。", "西瓜": "语义：西瓜不能作为付款的方式，与语境不符。"}, "sentence_index": 6, "correct_answer": "现金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的现金很好听。", "explanation": "这里应该用〈名字〉。“好听”用来形容名字、声音，现金是钱，不能说好听。"}, {"text": "他是我的现金。", "explanation": "这里应该用〈朋友〉。“朋友”指关系亲近的人，现金是钱，不能指人。"}, {"text": "他的现金很长。", "explanation": "这里应该用〈寿命〉。“长”用于寿命、道路等，现金是钱，不能说现金很长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他手里只有一个现金，够买车票。", "corrected_sentence": "他手里只有一叠现金，够买车票。", "error_description": "量词错误：成叠的纸钞可以说“一叠”；“个”是通用量词，不能用于现金，说成“一个现金”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从包里拿出一张现金，递给了我。", "corrected_sentence": "他从包里拿出一沓现金，递给了我。", "error_description": "量词错误：成叠的纸钞说“一沓”；“张”用于单张纸片，不能说“一张现金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91719, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "正确答案。“平庸”指平常、不突出，与“出色”意思相反。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”表示明白，与“出色”没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "“潮湿”表示含水分多，与“出色”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容地势，与“出色”没有反义关系。"}], "correct_answer": "平庸", "explanations": {"平庸": "正确答案。“平庸”指平常、不突出，与“出色”意思相反。", "清楚": "“清楚”表示明白，与“出色”没有反义关系。", "潮湿": "“潮湿”表示含水分多，与“出色”没有反义关系。", "陡峭": "“陡峭”形容地势，与“出色”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
