INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91719, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "特别好，比别人好很多。", "primary_collocate": null, "pronunciation": "chū sè", "ipa": "ʈʂʰu˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "她今天的表现非常出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻的医生工作很出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语说得很出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，中国队踢得非常出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸她的作文写得很出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位出色的老师，学生都喜欢他。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的成绩比同学们都出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子画得出色极了。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，小李完成任务很出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上的发言十分出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "出色：表现、完成得特别好，比别人好很多，常作谓语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daefa5e4-da06-49ae-91b6-3464485ab917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91719, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出色", "is_correct": true, "explanation": "正确答案。“表现非常出色”指表现特别好，比别人好很多，与句意相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”描述空气或物体的含水状态，不能用来评价表现。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”描述地势，不能用来形容一个人的表现。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”多形容地域或空间，不能用来描述表现。"}], "explanations": {"出色": "正确答案。“表现非常出色”指表现特别好，比别人好很多，与句意相符。", "潮湿": "语义：“潮湿”描述空气或物体的含水状态，不能用来评价表现。", "陡峭": "语义：“陡峭”描述地势，不能用来形容一个人的表现。", "辽阔": "搭配：“辽阔”多形容地域或空间，不能用来描述表现。"}, "sentence_index": 0, "correct_answer": "出色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的深度很出色。", "explanation": "这里应该用〈深〉。出色表示超出一般的好，用来评价表现或作品，不用于量度；河的深浅应说“深”。"}, {"text": "这个周末的天气很出色。", "explanation": "出色用来评价人的表现或作品，天气好应说“好”，不能用“出色”。"}, {"text": "他的身高很出色。", "explanation": "身高是身体的特征，不用“出色”评价；这里应说“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出色", "is_correct": true, "explanation": "正确答案。“成绩比同学们都出色”指成绩特别好，比别人好很多。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容环境安静，不能用来比较成绩。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不能用来评价成绩。"}, {"text": "陈旧", "is_correct": false, "explanation": "搭配：“陈旧”多形容物件或观念，不用于比较成绩。"}], "explanations": {"出色": "正确答案。“成绩比同学们都出色”指成绩特别好，比别人好很多。", "寂静": "语义：“寂静”形容环境安静，不能用来比较成绩。", "柔软": "语义：“柔软”形容质地，不能用来评价成绩。", "陈旧": "搭配：“陈旧”多形容物件或观念，不用于比较成绩。"}, "sentence_index": 6, "correct_answer": "出色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出色地打了个喷嚏。", "explanation": "这里把“出色”用来形容打喷嚏这个动作，等于说“打喷嚏打得特别好”。“出色”是褒义评价，只用于能评价好坏的表现，打喷嚏不能这样评价。"}, {"text": "我们明天早上出色。", "explanation": "这里应该用〈出发〉。出色是形容词，表示特别好；表示动身要说“出发”，不能说“出色”。"}, {"text": "问题突然出色了。", "explanation": "这里应该用〈出现〉。出色是形容词，表示特别好；问题“出现”是动作，不能说“出色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她跳舞跳的很出色。", "corrected_sentence": "她跳舞跳得很出色。", "error_description": "“得”误写成“的”：“跳舞跳”后的补语要用“得”，应为“跳得很出色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a472ade0-31e2-4a51-a15c-c52f4471e46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
