INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加球类比赛的运动员。", "primary_collocate": null, "pronunciation": "qiú yuán", "ipa": "tɕʰjoʊ̯˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "比赛开始前，球员走进了球场。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队有十一名球员。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位球员代表国家参加比赛。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练让球员们休息一会儿。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，两名球员被罚下场。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名职业球员。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们给球员加油。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，球员们都踢得很好。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的球员很受欢迎。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位球员拿到了冠军奖杯。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "球員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "参加球类比赛的运动员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bdefeb-1e1d-4048-a525-662a680312a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球员", "is_correct": true, "explanation": "正确。“比赛开始前，球员走进了球场”中，球员是能走进球场的人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能走进球场，句子意思不通。"}, {"text": "云", "is_correct": false, "explanation": "配价：“走进”的主语须是能自主移动的人或动物，不说“云走进了球场”。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：身体部位不能独立“走进球场”，不说“眼睛走进了球场”。"}], "explanations": {"球员": "正确。“比赛开始前，球员走进了球场”中，球员是能走进球场的人。", "窗户": "语义：窗户不能走进球场，句子意思不通。", "云": "配价：“走进”的主语须是能自主移动的人或动物，不说“云走进了球场”。", "眼睛": "搭配：身体部位不能独立“走进球场”，不说“眼睛走进了球场”。"}, "sentence_index": 0, "correct_answer": "球员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名滑冰球员。", "explanation": "这里应该用〈选手〉。球员只用于球类运动，滑冰不属于球类，要说选手。"}, {"text": "他是一名跳水球员。", "explanation": "这里应该用〈运动员〉。跳水不是球类运动，球员专指球类运动员，要说运动员。"}, {"text": "这位球员在医院给病人量体温。", "explanation": "这里应该用〈护士〉。球员指参加球类比赛的运动员，在医院给病人量体温的要说护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球员", "is_correct": true, "explanation": "正确。“球迷们给球员加油”中，球员是被加油的比赛参加者。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不参加比赛，球迷不会“给树加油”为它打气，句子不通。"}, {"text": "雨", "is_correct": false, "explanation": "配价：“给……加油”多用于人或队伍，不说“给雨加油”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会比赛，球迷不给桌子加油，句子意思不通。"}], "explanations": {"球员": "正确。“球迷们给球员加油”中，球员是被加油的比赛参加者。", "树": "语义：树不参加比赛，球迷不会“给树加油”为它打气，句子不通。", "雨": "配价：“给……加油”多用于人或队伍，不说“给雨加油”。", "桌子": "语义：桌子不会比赛，球迷不给桌子加油，句子意思不通。"}, "sentence_index": 6, "correct_answer": "球员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位球员在舞台上唱歌。", "explanation": "这里应该用〈歌手〉。球员指参加球类比赛的运动员，在舞台上唱歌的要说歌手。"}, {"text": "这位球员每天给花浇水。", "explanation": "这里应该用〈园丁〉。球员指参加球类比赛的运动员，不是照料花草的人，要说园丁。"}, {"text": "他是一名拳击球员。", "explanation": "这里应该用〈运动员〉。球员指参加球类比赛的运动员，拳击是个人格斗项目，不是球类，要说拳击运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只球员在比赛中进了两个球。", "corrected_sentence": "这名球员在比赛中进了两个球。", "error_description": "量词错误：“球员”指人，量词应用“名”或“位”。“只”不能指人，应改为“这名球员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经成为一名职业球员着。", "corrected_sentence": "他已经成为一名职业球员了。", "error_description": "体标错误：表示已经发生的变化用“了”，不能用“着”。“成为……着”不成立，应改为“成为一名职业球员了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '645b104d-2c6b-44f4-ac44-4271770d8e88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "加入一个队伍或团体。", "primary_collocate": null, "pronunciation": "jiā méng", "ipa": "tɕja˥ məŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他去年加盟了这支球队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻球员想加盟一家大俱乐部。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今年夏天加盟了我们公司的篮球队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那位外籍球星要加盟我们的足球队。", "target_word": "加盟", "complexity_tier": "T3", "furigana": "jiā méng", "sentence_source": "generated"}, {"text": "小王以前加盟过一支有名的乐队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一加盟球队，就进了三个球。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的球队欢迎新球员加盟。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥为了踢球，加盟了学校的足球队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位歌手决定加盟这个新乐队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练希望他明年能加盟我们队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加盟了", "label": "体标（了）"}, {"form": "加盟过", "label": "体标（过）"}, {"form": "加盟者", "label": "复合"}], "register": "中性", "sense_fingerprint": "加入球队、乐队等队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db54c0a-ae30-43eb-977b-2b2ba8aec6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加盟", "is_correct": true, "explanation": "正确：“加盟”指加入球队，与句中的“去年”“了”和“这支球队”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，球队不能被吃，这句话荒谬。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”的对象是比赛、演出，不说观看一支球队。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，球队不能用来清洗，与句意不符。"}], "explanations": {"加盟": "正确：“加盟”指加入球队，与句中的“去年”“了”和“这支球队”搭配，句意通顺。", "吃": "语义：“吃”的对象应是食物，球队不能被吃，这句话荒谬。", "观看": "搭配：“观看”的对象是比赛、演出，不说观看一支球队。", "洗": "语义：“洗”是清洗，球队不能用来清洗，与句意不符。"}, "sentence_index": 0, "correct_answer": "加盟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他加盟了今年的足球比赛。", "explanation": "这里应该用〈参加〉。加盟指加入某个团队，比赛是活动，不是团队，不能说加盟。"}, {"text": "他加盟了这次会议。", "explanation": "这里应该用〈出席〉。会议是活动，人可以出席，但不能加盟会议。"}, {"text": "他加盟了这个环保项目。", "explanation": "这里应该用〈参与〉。环保项目是工作，不是队伍或团体，“加盟”只能指加入团体，应说参与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加盟", "is_correct": true, "explanation": "正确：句末的“加盟”指新球员加入球队，与“欢迎新球员”的语境相合。"}, {"text": "退役", "is_correct": false, "explanation": "语义：“退役”指运动员退出现役，用在欢迎新球员的句子里不通。"}, {"text": "离开", "is_correct": false, "explanation": "语义：欢迎新球员离开球队与“欢迎”的意思相反，句子不合逻辑。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”指解雇、让人离职，与“欢迎新球员”的语境相反，句子不通。"}], "explanations": {"加盟": "正确：句末的“加盟”指新球员加入球队，与“欢迎新球员”的语境相合。", "退役": "语义：“退役”指运动员退出现役，用在欢迎新球员的句子里不通。", "离开": "语义：欢迎新球员离开球队与“欢迎”的意思相反，句子不合逻辑。", "辞退": "语义：“辞退”指解雇、让人离职，与“欢迎新球员”的语境相反，句子不通。"}, "sentence_index": 6, "correct_answer": "加盟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "代表团加盟了这所大学。", "explanation": "这里应该用〈访问〉。代表团来访并不是加入大学，加盟不能用来表示访问。"}, {"text": "学生们加盟了这座博物馆。", "explanation": "这里应该用〈参观〉。学生去参观博物馆，博物馆是场所，不是团体，不能说加盟。"}, {"text": "我们加盟了这座古城。", "explanation": "这里应该用〈游览〉。古城是地方，游览的是风景，不是团体，不能说加盟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没加盟了这家俱乐部。", "corrected_sentence": "他没加盟这家俱乐部。", "error_description": "错误：“没”否定已发生或未发生的动作时，“加盟”后不能再加“了”。应去掉“了”，说“没加盟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们想加盟了这家俱乐部。", "corrected_sentence": "我们想加盟这家俱乐部。", "error_description": "错误：“想”表示愿望，事情还没有发生，“加盟”后不能加“了”。应去掉“了”，说“想加盟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
