INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91726, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "加入某个组织、团体或联盟。", "primary_collocate": null, "pronunciation": "jiā méng", "ipa": "tɕja˥ məŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家小公司去年加盟了国际行业协会。", "target_word": "加盟", "complexity_tier": "T3", "furigana": "jiā méng", "sentence_source": "generated"}, {"text": "很多小公司想加盟这个行业联盟。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她加盟过一个帮助老人的团体。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个城市决定一起加盟这个联盟。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的学校已经加盟了教育联盟。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想加盟我们协会，要先交申请表。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院加盟了全国医疗联盟。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新成员加盟以后，协会更大了。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥加盟了一个环保团体。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几家商店都加盟了同一个商会。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加盟了", "label": "体标（了）"}, {"form": "加盟过", "label": "体标（过）"}, {"form": "加盟者", "label": "复合"}], "register": "中性", "sense_fingerprint": "加入组织、协会或联盟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db54c0a-ae30-43eb-977b-2b2ba8aec6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加盟", "is_correct": true, "explanation": "正确：“加盟”指加入组织，与“去年”“了”和“国际行业协会”相合，句意通顺。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”的对象是比赛、演出，不说观看一个协会。"}, {"text": "解散", "is_correct": false, "explanation": "语义：“解散”的主体应是协会本身或其创办者，小公司不能解散国际协会，句意不通。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑或设施，协会不能被拆除，句子不通。"}], "explanations": {"加盟": "正确：“加盟”指加入组织，与“去年”“了”和“国际行业协会”相合，句意通顺。", "观看": "搭配：“观看”的对象是比赛、演出，不说观看一个协会。", "解散": "语义：“解散”的主体应是协会本身或其创办者，小公司不能解散国际协会，句意不通。", "拆除": "语义：“拆除”指拆掉建筑或设施，协会不能被拆除，句子不通。"}, "sentence_index": 0, "correct_answer": "加盟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们加盟了这次展览。", "explanation": "这里应该用〈参加〉。展览是活动，不是团体，不能说加盟。"}, {"text": "他加盟了这个公益项目。", "explanation": "这里应该用〈参与〉。公益项目是事务，不是组织或团体，“加盟”只能指加入组织，应说参与。"}, {"text": "代表团加盟了这座城市。", "explanation": "这里应该用〈访问〉。代表团来访并不是加入城市，加盟不能用来表示访问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加盟", "is_correct": true, "explanation": "正确：“加盟”指医院加入联盟，与“这家医院”和“全国医疗联盟”搭配，句意通顺。"}, {"text": "出席", "is_correct": false, "explanation": "搭配：“出席”多用于会议、活动，联盟是组织，不说出席一个联盟。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，医院不能吃掉联盟，句子荒谬。"}, {"text": "投靠", "is_correct": false, "explanation": "语域：“投靠”带有依附、委身的色彩，用于医院与联盟的关系不合适。"}], "explanations": {"加盟": "正确：“加盟”指医院加入联盟，与“这家医院”和“全国医疗联盟”搭配，句意通顺。", "出席": "搭配：“出席”多用于会议、活动，联盟是组织，不说出席一个联盟。", "吃": "语义：“吃”的对象应是食物，医院不能吃掉联盟，句子荒谬。", "投靠": "语域：“投靠”带有依附、委身的色彩，用于医院与联盟的关系不合适。"}, "sentence_index": 6, "correct_answer": "加盟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们加盟了这座博物馆。", "explanation": "这里应该用〈参观〉。学生去参观博物馆，博物馆是场所，不是团体，不能说加盟。"}, {"text": "我们加盟了这座古城。", "explanation": "这里应该用〈游览〉。古城是地方，游览的是风景，不是团体，不能说加盟。"}, {"text": "我们加盟这个联盟的改革。", "explanation": "这里应该用〈支持〉。改革是一件事，不是团体，不能说加盟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家小公司没加盟了国际行业协会。", "corrected_sentence": "这家小公司没加盟国际行业协会。", "error_description": "错误：“没”与“了”不能同用。否定已完成的加入动作时，应去掉“了”，说“没加盟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们想加盟了这个协会。", "corrected_sentence": "我们想加盟这个协会。", "error_description": "错误：“想”表示愿望，事情还没有发生，“加盟”后不能加“了”。应去掉“了”，说“想加盟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
