INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91752, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于文字、消息、故事等。", "primary_collocate": null, "pronunciation": "yì zé", "ipa": "i˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "公司发出了一则重要的通知。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口贴了一则招聘广告。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在日记里写了一则小故事。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我读过一则很有意思的寓言。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有一则关于旅行的小故事。", "target_word": "一则", "complexity_tier": "T3", "furigana": "wǎng shàng yǒu yì zé guān yú lǚ xíng de xiǎo gù shi", "sentence_source": "generated"}, {"text": "老师在黑板上写了一则谜语。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里来了一则新闻提醒。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我读了一则简短的新闻。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸角落里有一则寻物启事。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校网站上发布了一则放假消息。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "量词：用于文字、消息、故事等条目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d5693c-26b2-4f0a-ad61-6ebde57a6292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一则", "is_correct": true, "explanation": "一则：量词，用于一条通知，与“重要的通知”搭配。"}, {"text": "一场", "is_correct": false, "explanation": "搭配：“场”用于比赛、演出等活动，不能量通知。"}, {"text": "一座", "is_correct": false, "explanation": "语义：“座”用于山、桥、建筑等大型物体，与通知无关。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“片”用于成片的田地、树林等，不能量通知。"}], "explanations": {"一则": "一则：量词，用于一条通知，与“重要的通知”搭配。", "一场": "搭配：“场”用于比赛、演出等活动，不能量通知。", "一座": "语义：“座”用于山、桥、建筑等大型物体，与通知无关。", "一片": "搭配：“片”用于成片的田地、树林等，不能量通知。"}, "sentence_index": 0, "correct_answer": "一则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我听过一则很好听的音乐。", "explanation": "这里应该用〈段〉。“则”用于消息、故事、广告等文字，音乐要用〈段〉。"}, {"text": "我看过一则很好看的电影。", "explanation": "这里应该用〈部〉。电影要用“部”，“则”不能量电影。"}, {"text": "我唱过一则很好听的歌。", "explanation": "这里应该用〈首〉。歌曲要用“首”，“则”不能量歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一则", "is_correct": true, "explanation": "一则：量词，用于一条新闻提醒，与“新闻提醒”搭配。"}, {"text": "一束", "is_correct": false, "explanation": "语义：“束”用于花、草等成把的东西，不能量新闻提醒。"}, {"text": "一棵", "is_correct": false, "explanation": "搭配：“棵”用于树、菜等植物，不能说“一棵提醒”。"}, {"text": "一台", "is_correct": false, "explanation": "语义：“台”用于机器、电器，“新闻提醒”不是机器，句子不成立。"}], "explanations": {"一则": "一则：量词，用于一条新闻提醒，与“新闻提醒”搭配。", "一束": "语义：“束”用于花、草等成把的东西，不能量新闻提醒。", "一棵": "搭配：“棵”用于树、菜等植物，不能说“一棵提醒”。", "一台": "语义：“台”用于机器、电器，“新闻提醒”不是机器，句子不成立。"}, "sentence_index": 6, "correct_answer": "一则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河里有一则鱼。", "explanation": "这里应该用〈条〉。鱼要用“条”，“则”只用于消息、通知等文字内容。"}, {"text": "教室里有一则桌子。", "explanation": "这里应该用〈张〉。桌子要用“张”，“则”不能量桌子。"}, {"text": "他买了一则书。", "explanation": "这里应该用〈本〉。书要用“本”，“则”不能量书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人事部今天发出了一则重要的信。", "corrected_sentence": "人事部今天发出了一封重要的信。", "error_description": "量词搭配错误：“信”应用量词“封”，不能用“则”。应为“一封重要的信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天给我读了一则简短的信。", "corrected_sentence": "她昨天给我读了一封简短的信。", "error_description": "量词搭配错误：“信”应用量词“封”，不能用“则”。应为“一封简短的信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
