INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91761, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91761, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走人是人离开，不在这里了。", "primary_collocate": null, "pronunciation": "zǒu rén", "ipa": "tsou˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "事情办完了，我们马上走人吧。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地说了一句话就走人了。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天快黑了，大家都收拾东西走人了。", "target_word": "走人", "complexity_tier": "T3", "furigana": "tiān kuài hēi le, dà jiā dōu shōu shi dōng xi zǒu rén le.", "sentence_source": "generated"}, {"text": "你不想听就走人，别在这儿吵。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，他付了钱就走人了。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵了一架，一气之下就走人了。", "target_word": "走人", "complexity_tier": "T3", "furigana": "tā men chǎo le yí jià, yí qì zhī xià jiù zǒu rén le.", "sentence_source": "generated"}, {"text": "说好五点走人，你怎么还没来？", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不在，他们就一个个走人了。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拿了东西就走人，不会多待。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不高兴，站起来就走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "走人：人从这里离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27970c99-4f73-4e93-9f4f-b3aa2257ae1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91761, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走人", "is_correct": true, "explanation": "正确。“事情办完了，我们马上走人吧”表示离开，与语境相符。"}, {"text": "留下", "is_correct": false, "explanation": "语义：“事情办完了”之后提议“留下”，与离开的语境相反。"}, {"text": "逗留", "is_correct": false, "explanation": "语义：“逗留”表示停留，与“事情办完了，马上……吧”的离开语境冲突。"}, {"text": "站住", "is_correct": false, "explanation": "搭配：“站住”指停下脚步，不用于“马上……吧”这种提议离开的句子。"}], "explanations": {"走人": "正确。“事情办完了，我们马上走人吧”表示离开，与语境相符。", "留下": "语义：“事情办完了”之后提议“留下”，与离开的语境相反。", "逗留": "语义：“逗留”表示停留，与“事情办完了，马上……吧”的离开语境冲突。", "站住": "搭配：“站住”指停下脚步，不用于“马上……吧”这种提议离开的句子。"}, "sentence_index": 0, "correct_answer": "走人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆自行车突然走人了，怎么找都找不到。", "explanation": "这里把“走人”用在了自行车上，“走人”只能指人离开，自行车不能走人，是对象用错。"}, {"text": "那只老鼠被吓了一跳，立刻走人了。", "explanation": "这里把“走人”用在了老鼠身上，“走人”的主语应是人，老鼠不能用“走人”，这里应说“跑走”。"}, {"text": "这本书很快就走人了。", "explanation": "“走人”只用于人，不能用于书，用于物品是用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走人", "is_correct": true, "explanation": "正确。“说好五点走人，你怎么还没来？”表示约定离开的时间，与语境相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“说好五点下雨”不合逻辑，与“你怎么还没来”的语境无关。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“说好五点结婚”与“你怎么还没来”的语境无关，意思不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“说好五点睡觉”不合逻辑，与“你怎么还没来”的语境冲突。"}], "explanations": {"走人": "正确。“说好五点走人，你怎么还没来？”表示约定离开的时间，与语境相符。", "下雨": "语义：“说好五点下雨”不合逻辑，与“你怎么还没来”的语境无关。", "结婚": "语义：“说好五点结婚”与“你怎么还没来”的语境无关，意思不成立。", "睡觉": "语义：“说好五点睡觉”不合逻辑，与“你怎么还没来”的语境冲突。"}, "sentence_index": 6, "correct_answer": "走人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车八点走人了。", "explanation": "“走人”只用于人，不能说火车走人，这里应说“出发”。"}, {"text": "那只猫不高兴，站起来就走人。", "explanation": "“走人”的主语应是人，猫不能用“走人”，这里应说“走开”。"}, {"text": "这台电梯刚修好，就突然走人了。", "explanation": "“走人”只能指人离开，电梯不能走人，这里用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议一结束，我们就走人过。", "corrected_sentence": "会议一结束，我们就走人了。", "error_description": "错误：“走人”表示已经离开，完成语气要用“了”，这里误用“过”，“走人过”不通。正确：“走人了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拿起包就走人着。", "corrected_sentence": "他拿起包就走人了。", "error_description": "错误：“走人”表示已经离开，完成语气要用“了”，这里误用“着”（“着”表示持续或进行），“走人着”不通。正确：“走人了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
