INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91766, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情向前发展的情况。", "primary_collocate": null, "pronunciation": "jìn zhǎn", "ipa": "tɕin˥˩ ʈʂan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个项目有了新的进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的病情没有进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道工作的最新进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究取得了很大的进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，大家说了各自的进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习中文，你有什么进展？", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈判几乎没有进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每周都告诉我工作进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想听听计划的进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的合作有了明显的进展。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "進展", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：事情向前发展的情况，常见于取得进展、最新进展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3716686e-219a-4097-9cd6-13972df5123d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进展", "is_correct": true, "explanation": "正确：进展（jìn zhǎn），指事情向前发展的情况。"}, {"text": "进站", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎn（第三声）声调不同，意思是进站（进入车站）。"}, {"text": "紧张", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同；zhāng 与 zhǎn 韵母不同（-ang 与 -an），声调也不同，意思是紧张。"}, {"text": "进账", "is_correct": false, "explanation": "zhàng（第四声）与 zhǎn 韵母不同（-ang 与 -an），声调也不同，意思是进账（收入的钱）。"}], "explanations": {"进展": "正确：进展（jìn zhǎn），指事情向前发展的情况。", "进站": "zhàn（第四声）与 zhǎn（第三声）声调不同，意思是进站（进入车站）。", "紧张": "jǐn（第三声）与 jìn（第四声）声调不同；zhāng 与 zhǎn 韵母不同（-ang 与 -an），声调也不同，意思是紧张。", "进账": "zhàng（第四声）与 zhǎn 韵母不同（-ang 与 -an），声调也不同，意思是进账（收入的钱）。"}, "sentence_index": null, "correct_answer": "进展"}, "level_3": {"options": [{"text": "进展", "is_correct": true, "explanation": "正确：进展，指项目的发展情况，与“有了新的”搭配。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”只用于人，不能说项目有新的脾气。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜与项目无关，句子不成立。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是随身物品，不能是项目的新情况。"}], "explanations": {"进展": "正确：进展，指项目的发展情况，与“有了新的”搭配。", "脾气": "搭配：“脾气”只用于人，不能说项目有新的脾气。", "西瓜": "语义：西瓜与项目无关，句子不成立。", "钱包": "语义：钱包是随身物品，不能是项目的新情况。"}, "sentence_index": 0, "correct_answer": "进展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身高有了很大的进展。", "explanation": "这里应该用〈增长〉。身高的变化用“增长”，“进展”多指事情的发展情况，不说身高有进展。"}, {"text": "这辆车的进展很快。", "explanation": "这里应该用〈速度〉。车的快慢用“速度”，“进展”指事情向前发展的情况，不能用来说车跑得快。"}, {"text": "这笔投资的进展很高。", "explanation": "这里应该用〈利率〉。投资回报的高低用“利率”或“收益率”，“进展”指事情的发展情况，不能用来说投资回报高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进展", "is_correct": true, "explanation": "正确：进展，指谈判的发展情况，与“几乎没有”搭配。"}, {"text": "手机", "is_correct": false, "explanation": "语义：谈判不能说没有手机，句子意思不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：谈判不是东西，说它几乎没有石头，与语境不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或动物的重量，不说谈判有体重。"}], "explanations": {"进展": "正确：进展，指谈判的发展情况，与“几乎没有”搭配。", "手机": "语义：谈判不能说没有手机，句子意思不通。", "石头": "语义：谈判不是东西，说它几乎没有石头，与语境不符。", "体重": "搭配：“体重”指人或动物的重量，不说谈判有体重。"}, "sentence_index": 6, "correct_answer": "进展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的亮度有了明显的进展。", "explanation": "这里应该用〈提高〉。亮度的变化用“提高”或“降低”，“进展”指事情的发展情况，不能用来说灯的亮度。"}, {"text": "这套房子的价格有了明显的进展。", "explanation": "这里应该用〈下降〉。价格的变化用“下降”或“上涨”，“进展”不用于价格。"}, {"text": "今天的温度有了明显的进展。", "explanation": "这里应该用〈升高〉。温度的变化用“升高”或“下降”，不说温度有进展。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的工作有了一条进展。", "corrected_sentence": "我的工作有了一点进展。", "error_description": "量词错误：“进展”前表示数量常用“一点”；“条”用于消息、路线这类细长或成条的东西，不能说“一条进展”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次谈判取了不小的进展。", "corrected_sentence": "这次谈判取得了不小的进展。", "error_description": "搭配错误：获得进展要说“取得进展”，“取”不能单独与“进展”搭配，应为“取得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
