INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91778, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为机构或个人提供意见、建议的专业人员。", "primary_collocate": null, "pronunciation": "gù wèn", "ipa": "ku˥˩ wən˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司请了一位顾问。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是这家银行的顾问。", "target_word": "顾问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "顾问建议我们先降低成本。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每月付给顾问一笔钱。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做过很多公司的顾问。", "target_word": "顾问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请顾问帮学校制定新的计划。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位顾问对市场非常了解。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理听了顾问的意见，决定改变方案。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院请一位外国专家当顾问。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他退休后，在几家公司当顾问。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "法律顾问", "label": "复合"}, {"form": "顧問", "label": "繁体"}], "register": "书面", "sense_fingerprint": "顾问：受公司、机构或个人聘请，提供专业意见和建议的人员（职业身份）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de7e825-ef28-4954-9ae4-9a37f9d8ffad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乞丐", "is_correct": false, "explanation": "语义：“乞丐”不是公司会聘请的职业人员，与“请了”的聘用语境冲突。"}, {"text": "顾问", "is_correct": true, "explanation": "“顾问”是受公司聘请、提供专业意见的人员，与“请了一位”相符。"}, {"text": "囚犯", "is_correct": false, "explanation": "语义：“囚犯”正在服刑，公司不会聘请他提供专业意见。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“请了一位”指聘用成年的职业人员，“小孩”不能被公司聘用。"}], "explanations": {"乞丐": "语义：“乞丐”不是公司会聘请的职业人员，与“请了”的聘用语境冲突。", "顾问": "“顾问”是受公司聘请、提供专业意见的人员，与“请了一位”相符。", "囚犯": "语义：“囚犯”正在服刑，公司不会聘请他提供专业意见。", "小孩": "搭配：“请了一位”指聘用成年的职业人员，“小孩”不能被公司聘用。"}, "sentence_index": 0, "correct_answer": "顾问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每周请顾问打扫办公室。", "explanation": "这里应该用〈清洁工〉。顾问提供专业建议，不负责打扫卫生。"}, {"text": "公司每天请顾问接送经理。", "explanation": "这里应该用〈司机〉。顾问不负责驾车接送，那是司机的工作。"}, {"text": "这家公司请了一位顾问守大门。", "explanation": "这里应该用〈保安〉。顾问提供专业建议，不负责守大门、看管出入，那是保安的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼儿", "is_correct": false, "explanation": "语义：“幼儿”尚未积累市场知识，不可能“非常了解”市场。"}, {"text": "顾问", "is_correct": true, "explanation": "“顾问”凭专业知识提供意见，与“对市场非常了解”的专业身份相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”只是短暂来访，不会对市场有专业的了解。"}, {"text": "新生", "is_correct": false, "explanation": "语义：“新生”刚入学，不可能对市场非常了解。"}], "explanations": {"幼儿": "语义：“幼儿”尚未积累市场知识，不可能“非常了解”市场。", "顾问": "“顾问”凭专业知识提供意见，与“对市场非常了解”的专业身份相符。", "游客": "语义：“游客”只是短暂来访，不会对市场有专业的了解。", "新生": "语义：“新生”刚入学，不可能对市场非常了解。"}, "sentence_index": 6, "correct_answer": "顾问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位顾问每天给病人看病。", "explanation": "这里应该用〈医生〉。顾问提供专业建议，不为病人诊断看病。"}, {"text": "这位顾问在演播室采访了很多名人。", "explanation": "这里应该用〈记者〉。顾问不做采访报道，那是记者的工作。"}, {"text": "这位顾问每天在操场上带学生跑步。", "explanation": "这里应该用〈体育老师〉。顾问提供意见，不负责带学生训练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司聘他顾问。", "corrected_sentence": "这家公司聘他为顾问。", "error_description": "错误：“聘”后缺少“为”。正确：“聘他为顾问”（也可说“聘他做顾问”或“聘他当顾问”）。“聘”带两个宾语时，中间要用“为”“做”或“当”连接职务，去掉后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找了一本顾问帮忙。", "corrected_sentence": "他找了一位顾问帮忙。", "error_description": "错误：量词用错。“顾问”是人，应用“位”，“本”只用于书籍。正确：“一位顾问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c558a4b-ca95-482e-a9ca-8fcf6baa5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
