INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91779, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很大、很危险，要马上想办法的难题。", "primary_collocate": null, "pronunciation": "yán zhòng wèn tí", "ipa": "jɛn˧˥ ʈʂʊŋ˥˩ wən˥˩ tʰi˧˥", "syllable_count": 4, "sentences": [{"text": "这座桥有严重问题，大家不能再走了。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子的水管出了严重问题，必须马上修。", "target_word": "严重问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水井里没有水是个严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车的刹车有严重问题，不能开了。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们遇到了严重问题，得马上想办法。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这是严重问题，要马上解决。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水很脏，这是一个严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发现了机器里的严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个严重问题不马上解决，大家都有危险。", "target_word": "严重问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里没有医生，这是个严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个严重问题", "label": "量词"}, {"form": "嚴重問題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "严重问题：很大很危险、要马上想办法解决的难题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b25d4a5-d08c-4cec-aadd-1aa0baf2491a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严重问题", "is_correct": true, "explanation": "正确。严重问题指很危险、需要马上处理的问题，正好解释后文“不能再走了”。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：“颜色”说外观，与“大家不能再走了”的危险判断无关。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”指过去的经历，推不出“不能再走”。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“有名字”虽然通顺，但与后文的危险判断对不上，桥的名字不会导致不能走。"}], "explanations": {"严重问题": "正确。严重问题指很危险、需要马上处理的问题，正好解释后文“不能再走了”。", "颜色": "体貌：“颜色”说外观，与“大家不能再走了”的危险判断无关。", "历史": "语义：“历史”指过去的经历，推不出“不能再走”。", "名字": "搭配：“有名字”虽然通顺，但与后文的危险判断对不上，桥的名字不会导致不能走。"}, "sentence_index": 0, "correct_answer": "严重问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题是个严重问题，我想了一个小时才做出来。", "explanation": "这里应该用〈难题〉。严重问题指很危险、需要马上处理的问题；数学题只是难，不是危险的情况。"}, {"text": "这只是个严重问题，不用太担心。", "explanation": "这里应该用〈小事〉。严重问题指很危险、需要马上想办法的难题；不必担心的小事不属于这种情况。"}, {"text": "老师问了一个很容易的严重问题，大家很快就答出来了。", "explanation": "这里应该用〈小问题〉。严重问题指很危险、需要马上想办法的难题；很容易回答的问题不属于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严重问题", "is_correct": true, "explanation": "正确。严重问题指很危险、需要马上解决的问题，与“河水很脏”的情况一致。"}, {"text": "好消息", "is_correct": false, "explanation": "语义：“好消息”是正面的事，与“河水很脏”的负面情况相反。"}, {"text": "美景", "is_correct": false, "explanation": "体貌：“美景”形容外观优美，与“河水很脏”正好相反。"}, {"text": "好主意", "is_correct": false, "explanation": "语义：“好主意”说的是想法，推不出“河水很脏”这个结论。"}], "explanations": {"严重问题": "正确。严重问题指很危险、需要马上解决的问题，与“河水很脏”的情况一致。", "好消息": "语义：“好消息”是正面的事，与“河水很脏”的负面情况相反。", "美景": "体貌：“美景”形容外观优美，与“河水很脏”正好相反。", "好主意": "语义：“好主意”说的是想法，推不出“河水很脏”这个结论。"}, "sentence_index": 6, "correct_answer": "严重问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个谜语很有意思，大家可以慢慢猜，这是个严重问题。", "explanation": "这里应该用〈有趣的谜题〉。严重问题指很危险、要马上想办法的难题；可以慢慢猜的谜语不属于这种情况。"}, {"text": "他这次考试进步很大，大家都很高兴，这是个严重问题。", "explanation": "这里应该用〈喜事〉。严重问题指很危险、要马上想办法的难题；值得高兴的事不属于这种情况。"}, {"text": "这份报告的字体有一点不一样，改一改就行，这是个严重问题。", "explanation": "这里应该用〈小毛病〉。严重问题指很危险、要马上想办法的难题；改一改就行的小毛病不属于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座楼的电梯有一只严重问题，得马上关掉。", "corrected_sentence": "这座楼的电梯有一个严重问题，得马上关掉。", "error_description": "错误形式：“一只严重问题”；正确形式：“一个严重问题”。“问题”是抽象名词，量词用“个”，“只”用于动物等，不能修饰问题。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家把这只严重问题解决了。", "corrected_sentence": "大家把这个严重问题解决了。", "error_description": "错误形式：“这只严重问题”；正确形式：“这个严重问题”。“问题”是抽象名词，指示量词要用“个”，“只”不能用于问题。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
