INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91786, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "返回；回来。", "primary_collocate": null, "pronunciation": "huí huán", "ipa": "xweɪ³⁵ xwan³⁵", "syllable_count": 2, "sentences": [{"text": "他出差半个月，昨天才回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在天黑前回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使者三日后回还，带来了好消息。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们旅行结束，已经回还学校。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等了一夜，他仍未回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回还以后，先去看望了父母。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船平安回还地球。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从国外回还，带着很多礼物。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商队春天出发，秋天回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人盼着儿子早日回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "回还：从别处返回、回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a6645ab-78ba-4186-8461-e21091544327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回还", "is_correct": true, "explanation": "回还：从外地返回，与“出差半个月”后“昨天才”的时间关系相合。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身前往，与“出差半个月”后已在外地的情形矛盾。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指下落不明，与“出差半个月，昨天才……”表示返程时间的语境不合，句意不通。"}, {"text": "动身", "is_correct": false, "explanation": "语义：“动身”指启程上路，与“出差半个月”已经在外的情形矛盾。"}], "explanations": {"回还": "回还：从外地返回，与“出差半个月”后“昨天才”的时间关系相合。", "出发": "语义：“出发”指动身前往，与“出差半个月”后已在外地的情形矛盾。", "失踪": "语义：“失踪”指下落不明，与“出差半个月，昨天才……”表示返程时间的语境不合，句意不通。", "动身": "语义：“动身”指启程上路，与“出差半个月”已经在外的情形矛盾。"}, "sentence_index": 0, "correct_answer": "回还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直没有回还我的电话。", "explanation": "这里应该用〈回〉（回电话）。回还不能以“电话”为宾语；“回”后接电话表示答复。"}, {"text": "妈妈把碗筷回还了厨房。", "explanation": "这里应该用〈送回〉。回还是不及物动词，不能带“把”字宾语；使物品回到原处要说“送回”。"}, {"text": "他终于回还了这道多年未解的难题。", "explanation": "这里应该用〈解决〉。回还只表示人或物回到原处，不能以“难题”为宾语；解决指使问题得到处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回还", "is_correct": true, "explanation": "回还：返回地球，与“飞船平安”后回到家园的语境相合。"}, {"text": "穿越", "is_correct": false, "explanation": "语义：“穿越”指从一端穿过另一端，与“平安回到地球”的意思不符。"}, {"text": "撞击", "is_correct": false, "explanation": "语义：“撞击”指猛烈碰撞，与“平安”相互矛盾。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”指修理破损之处，不能用来说飞船与地球的关系，句意不通。"}], "explanations": {"回还": "回还：返回地球，与“飞船平安”后回到家园的语境相合。", "穿越": "语义：“穿越”指从一端穿过另一端，与“平安回到地球”的意思不符。", "撞击": "语义：“撞击”指猛烈碰撞，与“平安”相互矛盾。", "修补": "语义：“修补”指修理破损之处，不能用来说飞船与地球的关系，句意不通。"}, "sentence_index": 6, "correct_answer": "回还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人去车站回还儿子。", "explanation": "这里应该用〈接〉。回还不能以人为宾语；“接”表示到某处迎接人。"}, {"text": "他常常回还童年的旧梦。", "explanation": "这里应该用〈回味〉。回还只表示回到原处，不能以“童年的旧梦”为宾语；回味指回想过去。"}, {"text": "工人们认真地回还那座老桥。", "explanation": "这里应该用〈修理〉。回还不能以“老桥”为宾语；修理指使建筑或器物恢复正常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船长平安回还来港口。", "corrected_sentence": "船长平安回还港口。", "error_description": "错误在“回还”后多加了“来”。回还本身已是完整动词，不能再加趋向补语“来”，应为“回还港口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你明天中午前回还了。", "corrected_sentence": "请你明天中午前回还。", "error_description": "错误在祈使句中用了“了”。请求对方将来某时做的动作，不能用“了”表示完成，应为“请你明天中午前回还”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
