INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91793, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "心里放着，很关心。", "primary_collocate": null, "pronunciation": "zài yì", "ipa": "tsaɪ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "他很在意孩子的学习。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈最在意我的健康。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她特别在意朋友对她的看法。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这么在意他，为什么不告诉他？", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在意的不是钱，而是尊重。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都很在意这次比赛的结果。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人很在意家里人回不回来吃饭。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很在意这件新衣服，每天都要看几次。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上不说，心里却很在意你。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在意的是你开不开心。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心里放着，很关心、很重视", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a8897d1-e71b-427d-ba6c-d8eccd14f3cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在意", "is_correct": true, "explanation": "“在意”表示很关心、很重视，这里说他非常重视孩子的学习。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指把一种语言转换成另一种语言，与“孩子的学习”没有关系。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”的对象是作业、作文等，不能说“批改孩子的学习”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，不能用来表示对学习的重视。"}], "explanations": {"在意": "“在意”表示很关心、很重视，这里说他非常重视孩子的学习。", "翻译": "语义：“翻译”指把一种语言转换成另一种语言，与“孩子的学习”没有关系。", "批改": "搭配：“批改”的对象是作业、作文等，不能说“批改孩子的学习”。", "吃": "语义：“吃”指把食物咽下去，不能用来表示对学习的重视。"}, "sentence_index": 0, "correct_answer": "在意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在意到窗外有一只鸟。", "explanation": "这里应该用〈注意到〉。“注意到”表示察觉到某事，“在意”表示关心、重视，不能表示察觉。"}, {"text": "开车时要在意前面有没有车。", "explanation": "这里应该用〈注意〉。“注意”可以用来提醒别人留神，“在意”表示关心、重视，不用于提醒留神。"}, {"text": "走路要在意脚下，别摔倒。", "explanation": "这里应该用〈留神〉。“留神”用于提醒别人小心，“在意”不能表示这种提醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在意", "is_correct": true, "explanation": "“在意”表示很挂念、很重视，这里说老人非常挂念家里人是否回来吃饭。"}, {"text": "订购", "is_correct": false, "explanation": "配价：“订购”要求商品作宾语，不能接“家里人回不回来吃饭”这样的小句。"}, {"text": "检阅", "is_correct": false, "explanation": "语域：“检阅”偏正式，多用于检阅队伍或材料，与这句日常口语的语境不协调。"}, {"text": "打扮", "is_correct": false, "explanation": "体貌：“打扮”指修饰外貌、穿戴，与“家里人回不回来吃饭”没有关系。"}], "explanations": {"在意": "“在意”表示很挂念、很重视，这里说老人非常挂念家里人是否回来吃饭。", "订购": "配价：“订购”要求商品作宾语，不能接“家里人回不回来吃饭”这样的小句。", "检阅": "语域：“检阅”偏正式，多用于检阅队伍或材料，与这句日常口语的语境不协调。", "打扮": "体貌：“打扮”指修饰外貌、穿戴，与“家里人回不回来吃饭”没有关系。"}, "sentence_index": 6, "correct_answer": "在意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上出门要在意坏人。", "explanation": "这里应该用〈提防〉。“提防”表示防备坏人，“在意”表示关心、重视，不能表示防范。"}, {"text": "下雨天路滑，要在意摔倒。", "explanation": "这里应该用〈当心〉。“当心”用于提醒对方留神，“在意”不能用于这种提醒。"}, {"text": "天黑了，要在意陌生的脚步声。", "explanation": "这里应该用〈警惕〉。“警惕”表示防范、提高戒备，“在意”只表示关心，不能表示防范。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很在意的我的作业。", "corrected_sentence": "妈妈很在意我的作业。", "error_description": "“在意”后面不能直接加“的”。错误形式是“很在意的我的作业”，正确形式是“很在意我的作业”，应删去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶很在意得我的身体。", "corrected_sentence": "奶奶很在意我的身体。", "error_description": "“在意”后面不能直接加“得”。错误形式是“很在意得我的身体”，正确形式是“很在意我的身体”，应删去“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
