INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人群是很多人聚在一起。", "primary_collocate": null, "pronunciation": "rén qún", "ipa": "ʐən˧˥ tɕʰyn˧˥", "syllable_count": 2, "sentences": [{"text": "节日那天，街上到处都是人群。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人群在门口等了一个小时。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从人群里挤出来，满头是汗。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们不要靠近人群。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店打折，门前聚了一大片人群。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的人群在唱歌，非常高兴。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大声喊了一句，人群都安静了。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完比赛，人群慢慢散开了。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢人群，所以很少去市中心。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下大了，人群跑进了商店。", "target_word": "人群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很多人聚在一起形成的一群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc6a9d0-da08-4b41-89fd-7e41cc848041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人群", "is_correct": true, "explanation": "正确：人群指聚在一起的许多人，“街上到处都是”之后接“人群”最自然。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指总人数，不指聚在街上的人群，“到处都是人口”不符合句意。"}, {"text": "人力", "is_correct": false, "explanation": "搭配：“人力”指劳动力，不能说“到处都是人力”。"}, {"text": "人生", "is_correct": false, "explanation": "语义：“人生”指一生的经历，与“街上到处都是”的具体场景不符。"}], "explanations": {"人群": "正确：人群指聚在一起的许多人，“街上到处都是”之后接“人群”最自然。", "人口": "语义：“人口”指总人数，不指聚在街上的人群，“到处都是人口”不符合句意。", "人力": "搭配：“人力”指劳动力，不能说“到处都是人力”。", "人生": "语义：“人生”指一生的经历，与“街上到处都是”的具体场景不符。"}, "sentence_index": 0, "correct_answer": "人群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上走过一只人群。", "explanation": "这里应该用〈一群〉。人群的量词要用“群”，不能用“只”。"}, {"text": "他是一个人群。", "explanation": "这里应该用〈个人〉。人群指许多人聚在一起，不能用来指单独一个人。"}, {"text": "我们班是一支人群。", "explanation": "这里应该用〈队伍〉。队伍是有组织的集体，人群是偶然聚集的许多人，不能用“支”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人群", "is_correct": true, "explanation": "正确：人群指聚在一起的许多人，“他大声喊了一句”之后“人群都安静了”符合句意。"}, {"text": "人手", "is_correct": false, "explanation": "搭配：“人手”指劳动力，不能说“人手都安静了”。"}, {"text": "人影", "is_correct": false, "explanation": "语义：“人影”指人的影子或模糊的人形，不能指一群人安静下来，句意不通。"}, {"text": "人士", "is_correct": false, "explanation": "语域：“人士”是书面的正式用语，与这里的口语叙述不符。"}], "explanations": {"人群": "正确：人群指聚在一起的许多人，“他大声喊了一句”之后“人群都安静了”符合句意。", "人手": "搭配：“人手”指劳动力，不能说“人手都安静了”。", "人影": "语义：“人影”指人的影子或模糊的人形，不能指一群人安静下来，句意不通。", "人士": "语域：“人士”是书面的正式用语，与这里的口语叙述不符。"}, "sentence_index": 6, "correct_answer": "人群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里的人群有四十个。", "explanation": "这里应该用〈人数〉。人群指聚在一起的人，不能按个数统计，说“班里的人数有四十个”才对。"}, {"text": "一群人群在街上跑。", "explanation": "这里多加了群体量词。人群本身已指聚在一起的许多人，前面不能再加“一群”；直接说“人群在街上跑”即可。"}, {"text": "这里有一个人群，正在唱歌。", "explanation": "这里应该用〈一群〉。人群的量词要用“群”，不能用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下雨的时候，人群们都跑进了商店。", "corrected_sentence": "下雨的时候，人群都跑进了商店。", "error_description": "错误：人群后面多加了“们”。正确：人群本身已是复数概念，后面不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨停以后，人群开散了。", "corrected_sentence": "雨停以后，人群散开了。", "error_description": "错误：结果补语“散开”的两个字顺序颠倒成了“开散”。正确：应说“散开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
