INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由首相或总统领导的国家最高行政机构。", "primary_collocate": null, "pronunciation": "nèi gé", "ipa": "nei˥˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "首相领导内阁。", "target_word": "内阁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "总统宣布了新内阁的名单。", "target_word": "内阁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内阁是国家最高的行政机构。", "target_word": "内阁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的内阁由首相领导。", "target_word": "内阁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内阁决定明年提高工人的工资。", "target_word": "内阁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统请他组成新的内阁。", "target_word": "内阁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内阁会议每个星期一上午开。", "target_word": "内阁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内阁提出了新的计划，国会很快就同意了。", "target_word": "内阁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为经济不好，整个内阁都辞职了。", "target_word": "内阁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首相每个月都要向国会说明内阁的工作。", "target_word": "内阁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "届", "label": "量词"}, {"form": "内阁成员", "label": "复合"}, {"form": "内阁会议", "label": "复合"}, {"form": "內閣", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "内阁：由首相或总统领导的国家最高行政机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27970c99-4f73-4e93-9f4f-b3aa2257ae1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内阁", "is_correct": true, "explanation": "正确：「内阁」是由首相领导的国家最高行政机构，能被「领导」。"}, {"text": "花园", "is_correct": false, "explanation": "语义：首相不领导花园，这与首相的职位不符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能被首相领导。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「领导」的对象是机构、人或工作，不说领导空气。"}], "explanations": {"内阁": "正确：「内阁」是由首相领导的国家最高行政机构，能被「领导」。", "花园": "语义：首相不领导花园，这与首相的职位不符。", "太阳": "语义：太阳不能被首相领导。", "空气": "搭配：「领导」的对象是机构、人或工作，不说领导空气。"}, "sentence_index": 0, "correct_answer": "内阁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "内阁决定了这个案子的判决。", "explanation": "这里应该用〈法院〉。内阁负责行政，判决案件是法院的工作，要用〈法院〉。"}, {"text": "内阁每天负责治疗病人。", "explanation": "这里应该用〈医生〉。内阁是国家的行政机构，不治病，负责治疗病人的要用〈医生〉。"}, {"text": "内阁由董事会领导。", "explanation": "这里应该用〈公司〉。公司才由董事会领导，内阁是国家机构，由首相领导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内阁", "is_correct": true, "explanation": "正确：「内阁会议」是内阁召开的会议，「内阁」在这里修饰「会议」。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：「会议」的修饰语应是团体或事项，「小说」不能修饰会议。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不会开会，「会议」的主体应是国家机构。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不能召开会议，与「每个星期一上午开」不符。"}], "explanations": {"内阁": "正确：「内阁会议」是内阁召开的会议，「内阁」在这里修饰「会议」。", "小说": "搭配：「会议」的修饰语应是团体或事项，「小说」不能修饰会议。", "眼睛": "语义：眼睛不会开会，「会议」的主体应是国家机构。", "雨水": "语义：雨水不能召开会议，与「每个星期一上午开」不符。"}, "sentence_index": 6, "correct_answer": "内阁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "内阁每周一都进行训练。", "explanation": "这里应该用〈球队〉。内阁是国家的行政机构，不进行训练，进行训练的是〈球队〉。"}, {"text": "内阁每天在田里种地。", "explanation": "这里应该用〈农民〉。内阁是国家的行政机构，不在田里种地，种地的人要用〈农民〉。"}, {"text": "这一座内阁刚刚成立。", "explanation": "这里不能用〈座〉。内阁作为机构，计量时要用〈届〉，不能说「一座」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "首相领导过过内阁。", "corrected_sentence": "首相领导过内阁。", "error_description": "「过」重复：「领导过」已经带了体标记「过」，不能再加一个。应说「领导过」，「过过」是重复的体标记，母语者不会这样说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "总统任命了一位新的内阁。", "corrected_sentence": "总统任命了一届新的内阁。", "error_description": "量词错误：「内阁」是一群人组成的机构，计量用「届」，「位」用于单个的人，不能用来计量内阁。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
