INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到这里；到这时为止。", "primary_collocate": null, "pronunciation": "dào cǐ", "ipa": "tau⁵¹ tsʰɨ²¹⁴", "syllable_count": 2, "sentences": [{"text": "今天的会议到此结束，谢谢大家。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事讲到此，大家都安静了。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题就讨论到此吧。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的节目到此结束，下次再见。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的信写到此就停了。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛到此，红队已经领先十分。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业到此为止，明天再做。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事到此为止，谁也别再提了。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课文读到此，老师请同学们讲讲感想。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路修到此，因为前面是山，所以停工了。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到此为止", "label": "复合"}, {"form": "到此结束", "label": "复合"}], "register": "书面", "sense_fingerprint": "到这里为止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9582f388-ac0e-48fb-946b-de35c9fd115a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到此", "is_correct": true, "explanation": "正确：“到此结束”表示到这里为止，与会议结束相符。"}, {"text": "开始", "is_correct": false, "explanation": "语义：开始与“结束”意思相反，句子自相矛盾。"}, {"text": "持续", "is_correct": false, "explanation": "语义：持续表示继续，不能与“结束”同用。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：放映用于电影、节目，不用于会议。"}], "explanations": {"到此": "正确：“到此结束”表示到这里为止，与会议结束相符。", "开始": "语义：开始与“结束”意思相反，句子自相矛盾。", "持续": "语义：持续表示继续，不能与“结束”同用。", "放映": "搭配：放映用于电影、节目，不用于会议。"}, "sentence_index": 0, "correct_answer": "到此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的节目到此开始，请大家安静。", "explanation": "这里应该用“从此”。到此表示到这里为止，不能表示开始，表示从这时起要说“从此”。"}, {"text": "这次讨论到此开始，请大家发言。", "explanation": "这里应该用“从此”。到此表示到这里为止，不能表示开始，从这时起要说“从此”。"}, {"text": "这场直播到此开始，请大家准备好。", "explanation": "这里应该用“在此”。到此表示到这里为止，不能表示开始，直播开始要说“在此开始”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到此", "is_correct": true, "explanation": "正确：到此为止表示到这里停止，与“明天再做”相符。"}, {"text": "继续", "is_correct": false, "explanation": "语义：继续与“为止”意思矛盾，句子不通。"}, {"text": "布置", "is_correct": false, "explanation": "语义：布置是给出作业，不表示停止。"}, {"text": "播出", "is_correct": false, "explanation": "搭配：播出用于节目，不用于作业。"}], "explanations": {"到此": "正确：到此为止表示到这里停止，与“明天再做”相符。", "继续": "语义：继续与“为止”意思矛盾，句子不通。", "布置": "语义：布置是给出作业，不表示停止。", "播出": "搭配：播出用于节目，不用于作业。"}, "sentence_index": 6, "correct_answer": "到此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路到此开始，前面是山，所以停工了。", "explanation": "这里应该用“在此”。到此表示到这里为止，不能表示开始，从这里动工要说“在此开始”。"}, {"text": "他们的任务到此开始，大家都很惊讶。", "explanation": "这里应该用“从此”。到此表示到这里为止，不能表示开始，从这时起要说“从此”。"}, {"text": "路修到此开始，因为前面是山，所以停工了。", "explanation": "这里应该用“在此”。到此表示到这里为止，不能表示开始，从这里动工要说“在此开始”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次培训到此为结束，希望大家收获很多。", "corrected_sentence": "这次培训到此结束，希望大家收获很多。", "error_description": "固定搭配错误：“到此结束”是固定说法，“为”只用于“到此为止”，不能插在“到此”和“结束”之间。正确说法：这次培训到此结束，希望大家收获很多。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天的课程到此为了，大家可以回家了。", "corrected_sentence": "明天的课程到此为止，大家可以回家了。", "error_description": "固定搭配错误：“到此为止”是固定说法，末尾应是“为止”，不能说“到此为了”。正确说法：明天的课程到此为止，大家可以回家了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
