INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91821, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对事物进行某种处理（后接双音节动词）。", "primary_collocate": null, "pronunciation": "jiā yǐ", "ipa": "tɕja˥ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个问题很重要，我们要尽快加以解决。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对这个词的意思加以说明。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书还能用，请你加以整理。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的老树应该加以保护。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的错误不大，改一改就行，不必加以批评。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片空地很大，可以加以利用。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的作业，老师每天都加以检查。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话不一定对，你要加以分析。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数字很乱，请你加以核对。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里的水不干净，必须加以处理。", "target_word": "加以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "对某件事做处理，后面接双音节动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc6a9d0-da08-4b41-89fd-7e41cc848041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加以", "is_correct": true, "explanation": "正确：加以表示对事物进行处理，前面有“尽快”，后面接双音节动词“解决”，符合句意。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”表示推迟，与“尽快”的意思相反。"}, {"text": "搁置", "is_correct": false, "explanation": "搭配：“搁置”一般接“问题、争议”，搁置后再“尽快解决”前后矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再去做，与“我们要”和“解决”的意思矛盾。"}], "explanations": {"加以": "正确：加以表示对事物进行处理，前面有“尽快”，后面接双音节动词“解决”，符合句意。", "拖延": "语义：“拖延”表示推迟，与“尽快”的意思相反。", "搁置": "搭配：“搁置”一般接“问题、争议”，搁置后再“尽快解决”前后矛盾。", "放弃": "语义：“放弃”表示不再去做，与“我们要”和“解决”的意思矛盾。"}, "sentence_index": 0, "correct_answer": "加以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我周末要加以比赛。", "explanation": "这里应该用〈参加〉。加以表示对事物进行处理，后面接“解决、保护”这类双音节动词，不能接“比赛”这类活动名词。"}, {"text": "老师应该加以学生，让他们认真学习。", "explanation": "这里应该用〈教育〉。加以的对象是事物，不能直接接表示人的名词，要说“对学生进行教育”。"}, {"text": "我每天早上都加以散步。", "explanation": "这里误用了〈加以〉，把它当成了〈进行〉的用法。加以表示对事物做某种处理，后面接的是处理性的双音节动词，不能用来修饰“散步”这种人自己的动作；直接说“每天早上都散步”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加以", "is_correct": true, "explanation": "正确：加以表示对事物进行处理，“每天都”后面接“检查”，符合句意。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”表示不再进行，与“每天都”的持续意思矛盾。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”表示不予理会，与“老师每天都”检查作业的意思矛盾。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”的宾语是需要维护的对象，不能以“检查”这类动作为宾语，“每天都保护检查”句意不通。"}], "explanations": {"加以": "正确：加以表示对事物进行处理，“每天都”后面接“检查”，符合句意。", "停止": "语义：“停止”表示不再进行，与“每天都”的持续意思矛盾。", "忽视": "语义：“忽视”表示不予理会，与“老师每天都”检查作业的意思矛盾。", "保护": "语义：“保护”的宾语是需要维护的对象，不能以“检查”这类动作为宾语，“每天都保护检查”句意不通。"}, "sentence_index": 6, "correct_answer": "加以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校每年都加以运动会。", "explanation": "这里应该用〈举办〉。加以不能直接接“运动会”这类活动名词，说“举办运动会”才自然。"}, {"text": "妈妈每天都加以房间。", "explanation": "这里应该用〈打扫〉。加以后面要接双音节处理性动词，直接接“房间”这类场所名词不自然，应说“打扫房间”。"}, {"text": "他想加以这本书。", "explanation": "这里应该用〈读〉。加以后面只能接处理性的动词，不能直接接“这本书”这样的事物；想说“读这本书”，直接用〈读〉即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台旧机器还能用，我们要加以修。", "corrected_sentence": "这台旧机器还能用，我们要加以修理。", "error_description": "错误：“加以”后面只接了单音节动词“修”。正确：应改为双音节动词“修理”，加以后面一般接双音节动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些账目的数据要进行加以核实，才能报给领导。", "corrected_sentence": "这些账目的数据要加以核实，才能报给领导。", "error_description": "错误：“加以”前面多加了“进行”，二者重复。正确：去掉“进行”，写作“要加以核实”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
