INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91825, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "何处是问哪一个地方。", "primary_collocate": null, "pronunciation": "hé chù", "ipa": "xɤ˧˥ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "请问，你的家在何处？", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次假期，你们想去何处旅行？", "target_word": "何处", "complexity_tier": "T3", "furigana": "zhè cì jià qī, nǐ men xiǎng qù hé chù lǚ xíng?", "sentence_source": "generated"}, {"text": "他不知道自己该去何处。", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这么多人，不知该在何处坐下。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店在何处？我想去买书。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅位于何处？", "target_word": "何处", "complexity_tier": "T3", "furigana": "zhè jiā cān tīng wèi yú hé chù?", "sentence_source": "generated"}, {"text": "他走了，没有人知道他去了何处。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想把这张画挂在何处？", "target_word": "何处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“学校的门在何处？”", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友来电话问我现在在何处。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "何處", "label": "繁体"}], "register": "书面", "sense_fingerprint": "何处：用来询问哪一个地方的疑问代词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b25d4a5-d08c-4cec-aadd-1aa0baf2491a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "何处", "is_correct": true, "explanation": "正确。“何处”是疑问代词，问地方，与“你的家在……”的提问一致。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，与问“家在哪里”的地点不符。"}, {"text": "什么", "is_correct": false, "explanation": "配价：“在”后需接处所词，“什么”不能单独作处所宾语。"}, {"text": "何时", "is_correct": false, "explanation": "语义：“何时”问时间，不能用来问家在哪里。"}], "explanations": {"何处": "正确。“何处”是疑问代词，问地方，与“你的家在……”的提问一致。", "谁": "语义：“谁”问人，与问“家在哪里”的地点不符。", "什么": "配价：“在”后需接处所词，“什么”不能单独作处所宾语。", "何时": "语义：“何时”问时间，不能用来问家在哪里。"}, "sentence_index": 0, "correct_answer": "何处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的钥匙就在何处。", "explanation": "这里应该用〈这里〉。何处是疑问代词，只用于提问，不能用来陈述说话人已知的地方。"}, {"text": "这家店就开在何处。", "explanation": "这里应该用〈这儿〉。何处只用于疑问，陈述已知地点时不能用它。"}, {"text": "我喜欢住在何处的小房子。", "explanation": "这里应该用〈那里〉。何处表示疑问，描述确定的地方时要用“那里”之类的指示词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何处", "is_correct": true, "explanation": "正确。“何处”问地方，与“去了……”的目的地相符。"}, {"text": "何物", "is_correct": false, "explanation": "配价：“去”后要接处所，“何物”指事物，不能作去的目的地。"}, {"text": "何故", "is_correct": false, "explanation": "语义：“何故”问原因，不能说他去的地方。"}, {"text": "何事", "is_correct": false, "explanation": "语义：“何事”问事情，与“去了……”的地点不符。"}], "explanations": {"何处": "正确。“何处”问地方，与“去了……”的目的地相符。", "何物": "配价：“去”后要接处所，“何物”指事物，不能作去的目的地。", "何故": "语义：“何故”问原因，不能说他去的地方。", "何事": "语义：“何事”问事情，与“去了……”的地点不符。"}, "sentence_index": 6, "correct_answer": "何处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你买的是何处？", "explanation": "这里应该用〈哪一本〉。“何处”只问地点，问具体是哪一件东西要用“哪一本”或“哪个”。"}, {"text": "这个箱子何处重？", "explanation": "这里应该用〈多重〉。“何处”只问地点，问重量要用“多重”。"}, {"text": "你何处这么生气？", "explanation": "这里应该用〈为什么〉。“何处”问地点，问原因要用“为什么”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
