INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91826, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，什么地方。", "primary_collocate": null, "pronunciation": "hé chù", "ipa": "xɤ˧˥ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "这条路通向何处？", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想知道钱花在了何处。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，我们今晚住在何处？", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看到我的手机放在何处了吗？", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小鸟飞向何处了？", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我，车站在何处。", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河水从何处来？", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她问我，书包落在了何处。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很累，却不知何处能坐。", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都在找他，不知他在何处。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "何處", "label": "繁体"}], "register": "书面", "sense_fingerprint": "何处：疑问代词，指什么地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b25d4a5-d08c-4cec-aadd-1aa0baf2491a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
