INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从前；以前。", "primary_collocate": null, "pronunciation": "cóng xiān", "ipa": "tsʰʊŋ³⁵ ɕjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "从先这里是一片田，现在是学校。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷从先是个老师，后来不教书了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先我们家很穷，现在日子好过了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比从先瘦多了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还是和从先一样爱笑。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先的老朋友，现在都不联系了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从先没来过这个城市，这是第一次。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先村里没有电，晚上点着灯。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的天气和从先不一样了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐从先爱哭，现在很坚强。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "从先：指从前、以前，可作定语或比较的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a6645ab-78ba-4186-8461-e21091544327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”是大片水域，不可能是一片可以盖学校的田，句子说不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”指海水，与“一片田”所指的对象冲突，句子语义不通。"}, {"text": "从先", "is_correct": true, "explanation": "从先：从前、以前，修饰“这里”的过去状况，与后半句“现在是学校”形成对比。"}, {"text": "中间", "is_correct": false, "explanation": "搭配：“中间”作主语时需要指明范围，“中间这里是一片田”不通顺。"}], "explanations": {"海洋": "语义：“海洋”是大片水域，不可能是一片可以盖学校的田，句子说不通。", "大海": "语义：“大海”指海水，与“一片田”所指的对象冲突，句子语义不通。", "从先": "从先：从前、以前，修饰“这里”的过去状况，与后半句“现在是学校”形成对比。", "中间": "搭配：“中间”作主语时需要指明范围，“中间这里是一片田”不通顺。"}, "sentence_index": 0, "correct_answer": "从先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从先我们的学校会很大。", "explanation": "这里应该用〈将来〉。从先指过去的时间，不能用来修饰还没建成的学校。"}, {"text": "从先我们下个月要去北京出差。", "explanation": "这里应该用〈下个月〉。从先指过去，不能用来说下个月的安排。"}, {"text": "从先我要成为一名医生。", "explanation": "这里应该用〈以后〉。从先指过去，不能用来说将来的理想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”指未来，与“没来过”所表示的以前经历矛盾。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“车站”是地点，不能作时间状语，说“我车站没来过”不通顺。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是具体的时段，不能表示“以前”的时间，句子语义不通。"}, {"text": "从先", "is_correct": true, "explanation": "从先：以前、从前，表示过去的时间，与“这是第一次”相符。"}], "explanations": {"明天": "语义：“明天”指未来，与“没来过”所表示的以前经历矛盾。", "车站": "搭配：“车站”是地点，不能作时间状语，说“我车站没来过”不通顺。", "下午": "语义：“下午”是具体的时段，不能表示“以前”的时间，句子语义不通。", "从先": "从先：以前、从前，表示过去的时间，与“这是第一次”相符。"}, "sentence_index": 6, "correct_answer": "从先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从先要参加考试，很紧张。", "explanation": "这里应该用〈明天〉。从先指过去，不能用来说明天的安排。"}, {"text": "从先会下雨，记得带伞。", "explanation": "这里应该用〈后天〉。从先指过去，不能用来说将要发生的天气。"}, {"text": "从先我要去医院复查。", "explanation": "这里应该用〈下个星期天〉。从先指过去，不能用来说还没到来的安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "从先了田地现在都盖了楼房。", "corrected_sentence": "从先的田地现在都盖了楼房。", "error_description": "错误在“了”误作定语标记。“了”不能修饰名词，“从先了田地”不成词组；应改为定语标记“的”，即“从先的田地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把从先很爱笑，现在不笑了。", "corrected_sentence": "他从先很爱笑，现在不笑了。", "error_description": "误加“把”：“从先”是时间副词，不能作“把”字句的宾语，“把从先很爱笑”结构不成立；应删去“把”，正确说法是“他从先很爱笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a55ccf-0263-4558-8e1f-29a0b865fc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
