INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91841, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力拉。", "primary_collocate": null, "pronunciation": "chě", "ipa": "ʈʂʰɤ²¹⁴", "syllable_count": 1, "sentences": [{"text": "小孩扯着妈妈的手，不肯回家。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力扯了一下绳子。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别扯我的袖子，我听得见。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟扯着我的衣角，要吃糖。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他扯住那个人，不让他走。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子扯着一根绳子玩。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师扯了扯衣领，站到台前。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她扯着风筝线，在草地上跑。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗扯着绳子往前冲。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我扯了扯他，小声说：“别说了。”", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扯了", "label": "体标"}, {"form": "扯着", "label": "体标"}, {"form": "扯过", "label": "体标"}, {"form": "扯了扯", "label": "重叠"}, {"form": "扯住", "label": "复合"}], "register": "口语", "sense_fingerprint": "用力拉住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9582f388-ac0e-48fb-946b-de35c9fd115a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91841, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扯", "is_correct": true, "explanation": "扯（chě，第三声）：用力拉住。"}, {"text": "车", "is_correct": false, "explanation": "chē（第一声）与 chě（第三声）声调不同，意思是车。"}, {"text": "彻", "is_correct": false, "explanation": "chè（第四声）与 chě（第三声）声调不同，意思是彻底。"}, {"text": "尺", "is_correct": false, "explanation": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是尺子。"}, {"text": "舍", "is_correct": false, "explanation": "shě 与 chě 声母不同（sh 与 ch），声调相同，意思是舍弃。"}], "explanations": {"扯": "扯（chě，第三声）：用力拉住。", "车": "chē（第一声）与 chě（第三声）声调不同，意思是车。", "彻": "chè（第四声）与 chě（第三声）声调不同，意思是彻底。", "尺": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是尺子。", "舍": "shě 与 chě 声母不同（sh 与 ch），声调相同，意思是舍弃。"}, "sentence_index": null, "correct_answer": "扯"}, "level_3": {"options": [{"text": "扯", "is_correct": true, "explanation": "扯：用力拉住，与“不肯回家”的拉扯情境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃妈妈的手。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、饰物等，不能说戴手。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与拉住妈妈的手无关。"}], "explanations": {"扯": "扯：用力拉住，与“不肯回家”的拉扯情境相符。", "吃": "搭配：“吃”的对象是食物，不能说吃妈妈的手。", "戴": "搭配：“戴”用于帽子、饰物等，不能说戴手。", "唱": "语义：“唱”指发出歌声，与拉住妈妈的手无关。"}, "sentence_index": 0, "correct_answer": "扯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天下班后扯小提琴练习。", "explanation": "这里应该用〈拉〉。拉小提琴是标准说法；“扯”口语中多用于二胡等胡琴，不说“扯小提琴”。"}, {"text": "她每天早上都扯一遍地板。", "explanation": "这里应该用〈拖〉。拖地板是用拖把擦洗，扯不能用于擦地。"}, {"text": "她把湿毛巾扯干了。", "explanation": "这里应该用〈拧〉。拧干湿物要靠扭转挤水，扯只表示用力拉或撕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91841, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扯", "is_correct": true, "explanation": "扯（chě，第三声）：用力拉住。"}, {"text": "撤", "is_correct": false, "explanation": "chè（第四声）与 chě（第三声）声调不同，意思是撤退。"}, {"text": "齿", "is_correct": false, "explanation": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是牙齿。"}, {"text": "耻", "is_correct": false, "explanation": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是羞耻。"}, {"text": "者", "is_correct": false, "explanation": "zhě 与 chě 声母不同（zh 与 ch），声调相同，意思是人，如作者的“者”。"}], "explanations": {"扯": "扯（chě，第三声）：用力拉住。", "撤": "chè（第四声）与 chě（第三声）声调不同，意思是撤退。", "齿": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是牙齿。", "耻": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是羞耻。", "者": "zhě 与 chě 声母不同（zh 与 ch），声调相同，意思是人，如作者的“者”。"}, "sentence_index": null, "correct_answer": "扯"}, "level_3": {"options": [{"text": "扯", "is_correct": true, "explanation": "扯：用力拉整理衣领，与“站到台前”前的整理动作相符。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指以气流推动，不用于整理衣领。"}, {"text": "啃", "is_correct": false, "explanation": "搭配：“啃”的对象是食物，衣领不能被啃。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的对象是花果、帽子等，不能说摘衣领。"}], "explanations": {"扯": "扯：用力拉整理衣领，与“站到台前”前的整理动作相符。", "吹": "语义：“吹”指以气流推动，不用于整理衣领。", "啃": "搭配：“啃”的对象是食物，衣领不能被啃。", "摘": "搭配：“摘”的对象是花果、帽子等，不能说摘衣领。"}, "sentence_index": 6, "correct_answer": "扯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上扯一管牙膏。", "explanation": "这里应该用〈挤〉。挤牙膏要靠用力压出，扯表示用力拉或撕，不能用于牙膏。"}, {"text": "他一拳扯在墙上，手都破了。", "explanation": "这里应该用〈打〉。打是用拳头击打，扯是用力拉或撕，不能用于击打墙面。"}, {"text": "他用小刀把木棍扯尖了。", "explanation": "这里应该用〈削〉。削是用刀刮去表皮使物体变尖，扯是用力拉或撕，不能用于削木棍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她住扯了我的胳膊，不让我走。", "corrected_sentence": "她扯住了我的胳膊，不让我走。", "error_description": "错误形式：“住扯了”；正确形式：“扯住了”。结果补语“住”要紧跟在动词“扯”后面，表示拉住、抓牢。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把那根线断扯了。", "corrected_sentence": "她把那根线扯断了。", "error_description": "错误形式：“断扯了”；正确形式：“扯断了”。结果补语“断”要紧跟在动词“扯”之后，表示扯到断的结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
