INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91853, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用笔把文章写出来。", "primary_collocate": null, "pronunciation": "zhuàn xiě", "ipa": "ʈʂʷan⁵¹ ɕjɛ²¹⁴", "syllable_count": 2, "sentences": [{"text": "他正在撰写一篇关于环保的文章。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请我们撰写一份调查报告。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用了三个月撰写毕业论文。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者连夜撰写了这篇新闻稿。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长亲自撰写了开学致辞。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你撰写一份活动方案，明天交给我。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天晚上都撰写一篇短评。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封公开信由三位同学共同撰写。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理让小王撰写本月的工作总结。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她坐在桌前，认真地撰写发言稿。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "撰写了", "label": "完成体"}, {"form": "撰写着", "label": "持续体"}, {"form": "撰写过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "撰写-用笔把文章写出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9582f388-ac0e-48fb-946b-de35c9fd115a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撰写", "is_correct": true, "explanation": "撰写：用笔写作文章，与“一篇关于环保的文章”相符。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”用于布料、毛线，不能说织文章。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与写作文章无关。"}, {"text": "盖", "is_correct": false, "explanation": "搭配：“盖”用于房屋、印章等，不能说盖文章。"}], "explanations": {"撰写": "撰写：用笔写作文章，与“一篇关于环保的文章”相符。", "织": "搭配：“织”用于布料、毛线，不能说织文章。", "喝": "语义：“喝”指饮用，与写作文章无关。", "盖": "搭配：“盖”用于房屋、印章等，不能说盖文章。"}, "sentence_index": 0, "correct_answer": "撰写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他花了一个上午撰写了一顿午饭。", "explanation": "这里应该用〈做〉。撰写用于文章、报告等文字作品，午饭要用做。"}, {"text": "他把那幅风景画撰写得很漂亮。", "explanation": "这里应该用〈绘制〉。撰写用于文字作品，画作要用绘制。"}, {"text": "工匠用了三天撰写了一座石像。", "explanation": "这里应该用〈雕刻〉。撰写用于文字作品，石像要用雕刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撰写", "is_correct": true, "explanation": "撰写：用笔写出短评，与“一篇短评”相符。"}, {"text": "剥", "is_correct": false, "explanation": "搭配：“剥”用于果皮、外壳，不能说剥短评。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”用于衣物、伤口，不能说缝短评。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指咽下，与写短评无关。"}], "explanations": {"撰写": "撰写：用笔写出短评，与“一篇短评”相符。", "剥": "搭配：“剥”用于果皮、外壳，不能说剥短评。", "缝": "搭配：“缝”用于衣物、伤口，不能说缝短评。", "吞": "语义：“吞”指咽下，与写短评无关。"}, "sentence_index": 6, "correct_answer": "撰写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工程师撰写了一座大桥。", "explanation": "这里应该用〈设计〉。撰写用于文字作品，大桥要用设计。"}, {"text": "他们昨天撰写了一段视频。", "explanation": "这里应该用〈录制〉。撰写用于文字，视频要用录制。"}, {"text": "师傅撰写了那台电脑。", "explanation": "这里应该用〈修理〉。撰写用于文字作品，电脑出了故障要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经在撰写完了这份报告。", "corrected_sentence": "他已经撰写完了这份报告。", "error_description": "错误形式：“已经在撰写完了”；正确形式：“已经撰写完了”。“在”表示动作正在进行，与表示完成的“完了”矛盾，不能同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在撰写了一份培训材料。", "corrected_sentence": "我正在撰写一份培训材料。", "error_description": "错误形式：“正在撰写了”；正确形式：“正在撰写”。“正在”表示动作进行中，不能与表示完成的“了”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
