INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "哥是比你大的男孩，是你的哥哥。", "primary_collocate": null, "pronunciation": "gē", "ipa": "kɤ˥", "syllable_count": 1, "sentences": [{"text": "哥，你今天回家吃饭吗？", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥，我的书包在哪儿？", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥，帮我看看这道题。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥，你比我大三岁，对吧？", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥，明天你能送我去学校吗？", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥，这件衣服好看吗？", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥，别走，等等我！", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥，我今天考了一百分！", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹对我说：“哥，谢谢你。”", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥，我饿了，我们去吃饭吧。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大哥", "label": "复合"}], "register": "口语", "sense_fingerprint": "名词：对哥哥的称呼，比自己大的男孩，多用于当面叫人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3716686e-219a-4097-9cd6-13972df5123d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哥", "is_correct": true, "explanation": "哥 gē 为本词，指哥哥，是对比自己大的男性的称呼"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 gē（第一声）声调不同，意思是量词“个”"}, {"text": "格", "is_correct": false, "explanation": "gé（第二声）与 gē（第一声）声调不同，意思是“格子”"}, {"text": "科", "is_correct": false, "explanation": "kē 与 gē 声母不同（k 送气，g 不送气），意思是“科学”"}], "explanations": {"哥": "哥 gē 为本词，指哥哥，是对比自己大的男性的称呼", "个": "gè（第四声）与 gē（第一声）声调不同，意思是量词“个”", "格": "gé（第二声）与 gē（第一声）声调不同，意思是“格子”", "科": "kē 与 gē 声母不同（k 送气，g 不送气），意思是“科学”"}, "sentence_index": null, "correct_answer": "哥"}, "level_3": {"options": [{"text": "哥", "is_correct": true, "explanation": "哥是对哥哥的称呼，这里当面叫对方，符合句意"}, {"text": "书", "is_correct": false, "explanation": "语义：书是物品，不能被当面称呼，句中是在问对方回家吃饭的事"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“吃饭”的宾语已是“饭”，称呼位置再用“饭”会重复，搭配不通"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不能被当面称呼，也不能回家吃饭"}], "explanations": {"哥": "哥是对哥哥的称呼，这里当面叫对方，符合句意", "书": "语义：书是物品，不能被当面称呼，句中是在问对方回家吃饭的事", "饭": "搭配：“吃饭”的宾语已是“饭”，称呼位置再用“饭”会重复，搭配不通", "雨": "语义：雨是天气现象，不能被当面称呼，也不能回家吃饭"}, "sentence_index": 0, "correct_answer": "哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是我哥，比我大三岁。", "explanation": "这里应该用〈姐〉。哥只指哥哥，比自己大的女性要说姐"}, {"text": "我家有一只哥，比我大三岁。", "explanation": "这里应该用〈个〉。哥指人，量词要用个，“只”多用于动物或物品"}, {"text": "他是我哥，比我小三岁。", "explanation": "这里应该用〈弟〉。哥指比自己大的哥哥，与“比我小三岁”矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91857, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哥", "is_correct": true, "explanation": "哥 gē 为本词，指哥哥，是对比自己大的男性的称呼"}, {"text": "各", "is_correct": false, "explanation": "gè（第四声）与 gē（第一声）声调不同，意思是“各自”"}, {"text": "隔", "is_correct": false, "explanation": "gé（第二声）与 gē（第一声）声调不同，意思是“隔开”"}, {"text": "颗", "is_correct": false, "explanation": "kē 与 gē 声母不同（k 送气，g 不送气），意思是量词“颗”"}], "explanations": {"哥": "哥 gē 为本词，指哥哥，是对比自己大的男性的称呼", "各": "gè（第四声）与 gē（第一声）声调不同，意思是“各自”", "隔": "gé（第二声）与 gē（第一声）声调不同，意思是“隔开”", "颗": "kē 与 gē 声母不同（k 送气，g 不送气），意思是量词“颗”"}, "sentence_index": null, "correct_answer": "哥"}, "level_3": {"options": [{"text": "哥", "is_correct": true, "explanation": "哥是对哥哥的称呼，这里叫住对方，符合句意"}, {"text": "门", "is_correct": false, "explanation": "语义：门不会走，也不能被叫住"}, {"text": "车", "is_correct": false, "explanation": "搭配：“等等我”要对能行动的人说，车不能等人"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能走动，也不能被当面称呼"}], "explanations": {"哥": "哥是对哥哥的称呼，这里叫住对方，符合句意", "门": "语义：门不会走，也不能被叫住", "车": "搭配：“等等我”要对能行动的人说，车不能等人", "椅子": "语义：椅子不能走动，也不能被当面称呼"}, "sentence_index": 6, "correct_answer": "哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有一条哥，在北京工作。", "explanation": "这里应该用〈个〉。哥指人，“条”用于细长的东西，指人要用个"}, {"text": "我哥是个女生，每天都化妆。", "explanation": "这里应该用〈姐〉。哥只指男性，说女生要用姐"}, {"text": "我哥比我年轻三岁。", "explanation": "这里应该用〈弟〉。哥指比自己大的哥哥，与“比我年轻”矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个哥，我的电脑坏了，你能帮我修一下吗？", "corrected_sentence": "哥，我的电脑坏了，你能帮我修一下吗？", "error_description": "错误：“一个哥”。正确：“哥”。称呼对方时直接用“哥”，不能加数量词，否则变成指称第三者，与句中的称呼不符", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有两张哥，都在北京工作。", "corrected_sentence": "我家有两个哥，都在北京工作。", "error_description": "错误：量词“两张”。正确：“两个”。“张”用于平面的东西，指人的哥哥要用量词“个”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
