INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91869, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大战是很大很大的战争或比赛。", "primary_collocate": null, "pronunciation": "dà zhàn", "ipa": "ta˥˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "这场大战打了整整三年。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大战开始前，士兵们都很紧张。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给我们讲过那场大战的故事。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队今晚有一场大战，球迷都来了。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大战过后，城里一个人也没有。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大战让很多家庭失去了亲人。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大战结束了，人们终于可以回家。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了一场海上大战。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家之间打过一场大战。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的足球大战很精彩，我看了一整晚。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大戰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大战：规模很大的战争或比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc6a9d0-da08-4b41-89fd-7e41cc848041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91869, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大战", "is_correct": true, "explanation": "正确答案：大战（dà zhàn），规模很大的战争或比赛。"}, {"text": "大展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，大展的意思是大展身手、大展宏图。"}, {"text": "打战", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，打战的意思是因寒冷或害怕而发抖。"}, {"text": "大专", "is_correct": false, "explanation": "zhuān（第一声）与 zhàn（第四声）韵母和声调都不同，大专的意思是大专院校。"}], "explanations": {"大战": "正确答案：大战（dà zhàn），规模很大的战争或比赛。", "大展": "zhǎn（第三声）与 zhàn（第四声）声调不同，大展的意思是大展身手、大展宏图。", "打战": "dǎ（第三声）与 dà（第四声）声调不同，打战的意思是因寒冷或害怕而发抖。", "大专": "zhuān（第一声）与 zhàn（第四声）韵母和声调都不同，大专的意思是大专院校。"}, "sentence_index": null, "correct_answer": "大战"}, "level_3": {"options": [{"text": "大战", "is_correct": true, "explanation": "正确：大战指规模很大的战争或比赛，「这场大战打了整整三年」语义通顺。"}, {"text": "晚会", "is_correct": false, "explanation": "搭配：「打」不能与「晚会」搭配，「这场晚会打了三年」说不通。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭不是战争或比赛，不能说「这场午饭打了三年」。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：讲座不是战争或比赛，与「打了整整三年」的语境不符。"}], "explanations": {"大战": "正确：大战指规模很大的战争或比赛，「这场大战打了整整三年」语义通顺。", "晚会": "搭配：「打」不能与「晚会」搭配，「这场晚会打了三年」说不通。", "午饭": "语义：午饭不是战争或比赛，不能说「这场午饭打了三年」。", "讲座": "语义：讲座不是战争或比赛，与「打了整整三年」的语境不符。"}, "sentence_index": 0, "correct_answer": "大战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大战很小，只有几个人参加。", "explanation": "这里把大战当成了规模很小的争执，应该用〈争吵〉；大战本指很大很大的战争或比赛。"}, {"text": "今天下了一场大战。", "explanation": "这里应该用〈大雨〉。大战是战争或比赛，不能用来形容下雨。"}, {"text": "大战很蓝。", "explanation": "这里应该用〈天空〉。大战是战争或比赛，不能形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大战", "is_correct": true, "explanation": "正确：大战指规模很大的战争或比赛，「大战结束了」语义通顺。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单不是战争或比赛，「账单结束了，人们可以回家」说不通。"}, {"text": "袜子", "is_correct": false, "explanation": "搭配：袜子不能「结束」，「袜子结束了」说不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：「饭菜结束了」不成立，「结束」不能与「饭菜」搭配。"}], "explanations": {"大战": "正确：大战指规模很大的战争或比赛，「大战结束了」语义通顺。", "账单": "语义：账单不是战争或比赛，「账单结束了，人们可以回家」说不通。", "袜子": "搭配：袜子不能「结束」，「袜子结束了」说不通。", "饭菜": "搭配：「饭菜结束了」不成立，「结束」不能与「饭菜」搭配。"}, "sentence_index": 6, "correct_answer": "大战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈昨晚把足球大战做成了一顿饭。", "explanation": "这里应该用〈晚饭〉。大战是战争或比赛，不能做成食物。"}, {"text": "他的梦想是考上大战。", "explanation": "这里应该用〈大学〉。大战是战争或比赛，不能用来考上。"}, {"text": "昨晚的足球大战把我家的桌子踢坏了。", "explanation": "这里应该用〈球员〉作主语。大战指比赛本身，不能作为施事去踢坏东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大战去年就吃完了。", "corrected_sentence": "这场大战去年就结束了。", "error_description": "搭配错误：「大战」是战争或比赛，不能用「吃」搭配，应说「打完」或「结束」。正确说法是「这场大战去年就结束了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场大战打很激烈。", "corrected_sentence": "那场大战打得很激烈。", "error_description": "补语错误：表示程度的补语要用「得」连接，应说「打得很激烈」，不能说「打很激烈」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
