INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91870, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大规模的战争或激烈的较量。", "primary_collocate": null, "pronunciation": "dà zhàn", "ipa": "ta˥˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "两家公司在手机市场上打了一场大战。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天是两位冠军的大战，我很想看。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人和老将的这场大战，十分激烈。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司打起了大战，顾客买到了便宜的东西。", "target_word": "大战", "complexity_tier": "T3", "furigana": "dà zhàn", "sentence_source": "generated"}, {"text": "这场大战到最后一分钟才分出输赢。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两支球队的大战打得十分激烈。", "target_word": "大战", "complexity_tier": "T3", "furigana": "dà zhàn", "sentence_source": "generated"}, {"text": "这场大战让他成了全国有名的棋手。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前一天，他们为明天的大战做好了准备。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的最后一场大战特别好看。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家饭店的大战，让街上热闹极了。", "target_word": "大战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大戰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大战：大规模战争或激烈的较量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc6a9d0-da08-4b41-89fd-7e41cc848041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91870, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大战", "is_correct": true, "explanation": "正确答案：大战（dà zhàn），指大规模战争或激烈的较量。"}, {"text": "大赞", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），意思是大力称赞。"}, {"text": "大展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是大规模展示。"}, {"text": "打战", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是因寒冷或害怕而发抖。"}], "explanations": {"大战": "正确答案：大战（dà zhàn），指大规模战争或激烈的较量。", "大赞": "zàn 与 zhàn 声母不同（z 与 zh），意思是大力称赞。", "大展": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是大规模展示。", "打战": "dǎ（第三声）与 dà（第四声）声调不同，意思是因寒冷或害怕而发抖。"}, "sentence_index": null, "correct_answer": "大战"}, "level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "搭配：“打”不能与“感冒”搭配，应说“得了感冒”，句子不通。"}, {"text": "大战", "is_correct": true, "explanation": "大战：指激烈的较量，与“打了一场”搭配，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不是可以“打”的事件，与量词“场”也不搭。"}, {"text": "晚餐", "is_correct": false, "explanation": "搭配：“打”不能与“晚餐”搭配，应说“吃晚餐”。"}], "explanations": {"感冒": "搭配：“打”不能与“感冒”搭配，应说“得了感冒”，句子不通。", "大战": "大战：指激烈的较量，与“打了一场”搭配，符合句意。", "花园": "语义：花园是场所，不是可以“打”的事件，与量词“场”也不搭。", "晚餐": "搭配：“打”不能与“晚餐”搭配，应说“吃晚餐”。"}, "sentence_index": 0, "correct_answer": "大战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家为新同学举办了一场大战。", "explanation": "这里应该用〈欢迎会〉。“大战”指大规模战争或激烈的较量，不能用来指欢迎新同学的聚会；这类聚会要说〈欢迎会〉。"}, {"text": "同学们在周末进行了一场安静的大战。", "explanation": "这里应该用〈聚会〉。“大战”指激烈的较量，与“安静”的气氛相反，也不指朋友间的相聚；朋友相聚要说〈聚会〉。"}, {"text": "他在台上做了一场简短的大战。", "explanation": "这里应该用〈演讲〉。“大战”指大规模战争或激烈的较量，不是讲话，也不能用“简短”形容；发表讲话要用〈演讲〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91870, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大战", "is_correct": true, "explanation": "正确答案：大战（dà zhàn），指大规模战争或激烈的较量。"}, {"text": "大赚", "is_correct": false, "explanation": "zhuàn 与 zhàn 韵母不同（uan 与 an），意思是赚大钱。"}, {"text": "大善", "is_correct": false, "explanation": "shàn 与 zhàn 声母不同（sh 与 zh），意思是非常善良，词义不同。"}, {"text": "大转", "is_correct": false, "explanation": "zhuǎn（第三声）与 zhàn（第四声）韵母与声调都不同，意思是大幅转动。"}], "explanations": {"大战": "正确答案：大战（dà zhàn），指大规模战争或激烈的较量。", "大赚": "zhuàn 与 zhàn 韵母不同（uan 与 an），意思是赚大钱。", "大善": "shàn 与 zhàn 声母不同（sh 与 zh），意思是非常善良，词义不同。", "大转": "zhuǎn（第三声）与 zhàn（第四声）韵母与声调都不同，意思是大幅转动。"}, "sentence_index": null, "correct_answer": "大战"}, "level_3": {"options": [{"text": "演唱会", "is_correct": false, "explanation": "语义：“演唱会”与“棋手”无关，无法让他成为棋手，句意不通。"}, {"text": "大战", "is_correct": true, "explanation": "大战：指激烈的较量，此处指让他成名的一场比赛，符合句意。"}, {"text": "手术", "is_correct": false, "explanation": "语义：“手术”不能让人成为棋手，与“棋手”的语义矛盾。"}, {"text": "午餐", "is_correct": false, "explanation": "搭配：量词“场”一般不用于“午餐”，应说“这顿午餐”。"}], "explanations": {"演唱会": "语义：“演唱会”与“棋手”无关，无法让他成为棋手，句意不通。", "大战": "大战：指激烈的较量，此处指让他成名的一场比赛，符合句意。", "手术": "语义：“手术”不能让人成为棋手，与“棋手”的语义矛盾。", "午餐": "搭配：量词“场”一般不用于“午餐”，应说“这顿午餐”。"}, "sentence_index": 6, "correct_answer": "大战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教授做了一场枯燥的大战。", "explanation": "这里应该用〈讲座〉。“大战”指激烈的较量，不能用“枯燥”形容；学术报告要用〈讲座〉。"}, {"text": "他们举办了一场温馨的大战。", "explanation": "这里应该用〈婚礼〉。“大战”指激烈的较量，与“温馨”的气氛相反；举办仪式要用〈婚礼〉。"}, {"text": "他做了一场美丽的大战。", "explanation": "这里应该用〈梦〉。“大战”不能用来形容梦境；做梦的“梦”才与“美丽”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个队在决赛中打了一个大战。", "corrected_sentence": "两个队在决赛中打了一场大战。", "error_description": "量词错误：“大战”是一次事件，应用量词“场”，不能用“个”。正确说法是“打了一场大战”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个班的大战打十分激烈。", "corrected_sentence": "两个班的大战打得十分激烈。", "error_description": "补语错误：“打”后面表示程度的补语要用“得”引出，应说“打得十分激烈”，不能省略“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c597d663-65c1-4423-930b-42039741c284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
