INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91875, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大批是特别多的一群。", "primary_collocate": null, "pronunciation": "dà pī", "ipa": "ta⁵¹ pʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "假期里，大批游客来到这座小城。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口站着大批等车的人。", "target_word": "大批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览开始前，大批观众排起了长队。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司最近招了大批新员工。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，大批球迷涌向出口。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震后，大批志愿者赶到了灾区。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节前，大批工人坐火车回老家。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上有大批学生骑车去学校。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商场打折，大批顾客一早就来了。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节日期间，大批外地人涌进了这座城市。", "target_word": "大批", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大批大批", "label": "重叠"}], "register": "中性", "sense_fingerprint": "大批-特别多的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9582f388-ac0e-48fb-946b-de35c9fd115a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寥寥", "is_correct": false, "explanation": "语义：假期里来的游客应当很多，“寥寥”表示人数很少，与句中“假期里”的热闹情境相反。"}, {"text": "大批", "is_correct": true, "explanation": "正确：“大批”修饰“游客”，表示成群的人数很多，符合假期里游客涌入小城的语境。"}, {"text": "巨大", "is_correct": false, "explanation": "语法：“巨大”作定语通常要带“的”，“巨大游客”不成立；且它多形容规模、压力或影响，不直接表示成群的人。"}, {"text": "零星", "is_correct": false, "explanation": "语义：“零星”指分散、数量少，与“假期里”游客众多的情境矛盾。"}], "explanations": {"寥寥": "语义：假期里来的游客应当很多，“寥寥”表示人数很少，与句中“假期里”的热闹情境相反。", "大批": "正确：“大批”修饰“游客”，表示成群的人数很多，符合假期里游客涌入小城的语境。", "巨大": "语法：“巨大”作定语通常要带“的”，“巨大游客”不成立；且它多形容规模、压力或影响，不直接表示成群的人。", "零星": "语义：“零星”指分散、数量少，与“假期里”游客众多的情境矛盾。"}, "sentence_index": 0, "correct_answer": "大批"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂每天排放大批废水。", "explanation": "这里应该用〈大量〉。大批指成群的人或物，用于可数的一群；废水是不可数的物质，要用大量。"}, {"text": "他花了大批时间准备考试。", "explanation": "这里应该用〈很多〉。大批强调成群的人或物，时间是不可数的，不能用大批修饰。"}, {"text": "他承受着大批压力。", "explanation": "这里应该用〈巨大〉。大批强调成群的人或物，压力是抽象的，不能用大批修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀少", "is_correct": false, "explanation": "语义：春节前大家都要回家，人流很大，“稀少”与春节前返乡的情境矛盾。"}, {"text": "浩瀚", "is_correct": false, "explanation": "搭配：“浩瀚”多形容海洋、星空等广阔的事物，不能修饰“工人”。"}, {"text": "大批", "is_correct": true, "explanation": "正确：“大批”修饰“工人”，表示成群的人数多，与春节前返乡的人流相符。"}, {"text": "大型", "is_correct": false, "explanation": "搭配：“大型”多修饰机器、活动、设施，不能用来修饰人群。"}], "explanations": {"稀少": "语义：春节前大家都要回家，人流很大，“稀少”与春节前返乡的情境矛盾。", "浩瀚": "搭配：“浩瀚”多形容海洋、星空等广阔的事物，不能修饰“工人”。", "大批": "正确：“大批”修饰“工人”，表示成群的人数多，与春节前返乡的人流相符。", "大型": "搭配：“大型”多修饰机器、活动、设施，不能用来修饰人群。"}, "sentence_index": 6, "correct_answer": "大批"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一次借给朋友大批钱。", "explanation": "这里应该用〈大笔〉。钱款的数量用大笔，大批强调成群的人或物，不用来修饰钱。"}, {"text": "这个周末我有大批时间。", "explanation": "这里应该用〈大把〉。大把是口语，修饰时间很多；大批不能修饰时间。"}, {"text": "他一次性缴纳了大批税款。", "explanation": "这里应该用〈大额〉。大额用于金额数目大，大批不能用来修饰税款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "假期一到，一个大批游客涌进了这座小城。", "corrected_sentence": "假期一到，一大批游客涌进了这座小城。", "error_description": "错误形式“一个大批”，正确形式“一大批”。“大批”是形容词，前面只用数词“一”，不能再加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春节前，很大批工人坐火车回老家。", "corrected_sentence": "春节前，一大批工人坐火车回老家。", "error_description": "错误形式“很大批”，正确形式“一大批”。“大批”是形容词，表示成群的人多，不能被程度副词“很”修饰；修饰名词前应用数词“一”构成“一大批”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
