INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "削减是把数量弄少一点。", "primary_collocate": null, "pronunciation": "xuē jiǎn", "ipa": "ɕɥɛ˥ tɕjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "公司决定削减今年的开支。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校削减了三个班的人数。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了省钱，我们削减了买衣服的钱。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府削减了今年的预算。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里钱不多，只好削减吃饭的费用。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂削减了一半工人。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说要削减开会的次数。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把每月的零花钱削减了一半。", "target_word": "削减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院削减了晚上的门诊时间。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先削减不用的开支，再买新电脑。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "削减了", "label": "体标"}, {"form": "削减过", "label": "体标"}, {"form": "削減", "label": "繁体"}], "register": "正式", "sense_fingerprint": "削减：把费用、人数等数量减少一些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b25d4a5-d08c-4cec-aadd-1aa0baf2491a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "削减", "is_correct": true, "explanation": "正确：削减指把数量弄少一点，即本条目的词"}, {"text": "靴尖", "is_correct": false, "explanation": "jiān 与 jiǎn 声调不同，意思是靴子的前端"}, {"text": "血检", "is_correct": false, "explanation": "xuè（第四声）与 xuē（第一声）声调不同，意思是血液检查"}, {"text": "雪碱", "is_correct": false, "explanation": "xuě（第三声）与 xuē（第一声）声调不同，意思是一种碱类物质"}], "explanations": {"削减": "正确：削减指把数量弄少一点，即本条目的词", "靴尖": "jiān 与 jiǎn 声调不同，意思是靴子的前端", "血检": "xuè（第四声）与 xuē（第一声）声调不同，意思是血液检查", "雪碱": "xuě（第三声）与 xuē（第一声）声调不同，意思是一种碱类物质"}, "sentence_index": null, "correct_answer": "削减"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说「吃开支」"}, {"text": "削减", "is_correct": true, "explanation": "正确：「削减」表示减少数量，可以搭配「开支」，符合句意"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」指喜爱美好的事物，与开支的减少相矛盾"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能带「开支」作宾语，句子无法成立"}], "explanations": {"吃": "搭配：「吃」的对象是食物，不能说「吃开支」", "削减": "正确：「削减」表示减少数量，可以搭配「开支」，符合句意", "欣赏": "语义：「欣赏」指喜爱美好的事物，与开支的减少相矛盾", "唱": "搭配：「唱」不能带「开支」作宾语，句子无法成立"}, "sentence_index": 0, "correct_answer": "削减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重削减了三公斤。", "explanation": "这里应该用〈减少〉。削减多用于费用、人数、预算等可以压缩的数量，体重的变化要说减少"}, {"text": "今年的气温削减了五度。", "explanation": "这里应该用〈降低〉。削减指主动压缩费用、人数等数量，气温的下降要说降低"}, {"text": "秋风一吹，树上的叶子纷纷削减了。", "explanation": "这里应该用〈脱落〉。削减指人主动压缩数量，叶子自然掉落要说脱落"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮用", "is_correct": false, "explanation": "搭配：「饮用」的对象是饮品，不能说「饮用次数」"}, {"text": "削减", "is_correct": true, "explanation": "正确：「削减」表示减少数量，可以搭配「次数」，符合句意"}, {"text": "观赏", "is_correct": false, "explanation": "语义：「观赏」指欣赏景物或表演，与「开会的次数」不相容"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：「熄灭」指火或光的消失，不能用于「次数」"}], "explanations": {"饮用": "搭配：「饮用」的对象是饮品，不能说「饮用次数」", "削减": "正确：「削减」表示减少数量，可以搭配「次数」，符合句意", "观赏": "语义：「观赏」指欣赏景物或表演，与「开会的次数」不相容", "熄灭": "语义：「熄灭」指火或光的消失，不能用于「次数」"}, "sentence_index": 6, "correct_answer": "削减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃了药以后，他的头痛削减了。", "explanation": "这里应该用〈减轻〉。削减用于数量、费用的压缩，疼痛的减弱要说减轻"}, {"text": "这块海绵被削减了。", "explanation": "这里应该用〈压缩〉。削减用于数量或费用，物体体积变小要说压缩"}, {"text": "今天中午，他的体温削减了两度。", "explanation": "这里应该用〈降低〉。削减指压缩费用、人数等数量，体温的下降要说降低"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
