INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "削弱、减少。", "primary_collocate": null, "pronunciation": "xuē jiǎn", "ipa": "ɕɥɛ˥ tɕjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "国王想削减大臣的权力。", "target_word": "削减", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新规定削减了老板的权力。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国同意削减各自的兵力。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总部削减了各地分公司的权力。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家决定削减军队的人数。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师削减了考试的内容。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们削减了对方的势力。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂计划削减废气排放量。", "target_word": "削减", "complexity_tier": "T3", "furigana": "xuē jiǎn", "sentence_source": "generated"}, {"text": "学校削减了老师的会议时间。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王把大臣的兵力削减了一半。", "target_word": "削减", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "削减了", "label": "体标"}, {"form": "削减过", "label": "体标"}, {"form": "削減", "label": "繁体"}], "register": "正式", "sense_fingerprint": "削减：削弱并减少权力、兵力、排放等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b25d4a5-d08c-4cec-aadd-1aa0baf2491a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "削减", "is_correct": true, "explanation": "正确：削减指削弱并减少权力、兵力等，即本条目的词"}, {"text": "靴尖", "is_correct": false, "explanation": "jiān 与 jiǎn 声调不同，意思是靴子的前端"}, {"text": "血检", "is_correct": false, "explanation": "xuè（第四声）与 xuē（第一声）声调不同，意思是血液检查"}, {"text": "雪碱", "is_correct": false, "explanation": "xuě（第三声）与 xuē（第一声）声调不同，意思是一种碱类物质"}], "explanations": {"削减": "正确：削减指削弱并减少权力、兵力等，即本条目的词", "靴尖": "jiān 与 jiǎn 声调不同，意思是靴子的前端", "血检": "xuè（第四声）与 xuē（第一声）声调不同，意思是血液检查", "雪碱": "xuě（第三声）与 xuē（第一声）声调不同，意思是一种碱类物质"}, "sentence_index": null, "correct_answer": "削减"}, "level_3": {"options": [{"text": "品尝", "is_correct": false, "explanation": "搭配：「品尝」的对象是食物或滋味，不能说「品尝权力」"}, {"text": "削减", "is_correct": true, "explanation": "正确：「削减」表示削弱、压缩权力，可以搭配「权力」，符合句意"}, {"text": "种植", "is_correct": false, "explanation": "语义：「种植」指栽培植物，与「权力」不相容"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：「喂养」的对象是动物，不能带「权力」作宾语"}], "explanations": {"品尝": "搭配：「品尝」的对象是食物或滋味，不能说「品尝权力」", "削减": "正确：「削减」表示削弱、压缩权力，可以搭配「权力」，符合句意", "种植": "语义：「种植」指栽培植物，与「权力」不相容", "喂养": "搭配：「喂养」的对象是动物，不能带「权力」作宾语"}, "sentence_index": 0, "correct_answer": "削减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次地震削减了他的体力。", "explanation": "这里应该用〈消耗〉。削减多用于权力、兵力等的压缩，体力的耗损要说消耗"}, {"text": "这次手术削减了他的痛苦。", "explanation": "这里应该用〈减轻〉。削减用于权力、兵力等的压缩，痛苦、压力的减弱要说减轻"}, {"text": "警察削减了暴动。", "explanation": "这里应该用〈压制〉。削减是压低权力、兵力等，暴动的平息要说压制"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮用", "is_correct": false, "explanation": "搭配：「饮用」的对象是饮品，不能带「势力」作宾语"}, {"text": "削减", "is_correct": true, "explanation": "正确：「削减」表示削弱、压缩势力，符合句意"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：「烹饪」的对象是食材，不能说「烹饪势力」"}, {"text": "放牧", "is_correct": false, "explanation": "语义：「放牧」指饲养牲畜，与「势力」不相容"}], "explanations": {"饮用": "搭配：「饮用」的对象是饮品，不能带「势力」作宾语", "削减": "正确：「削减」表示削弱、压缩势力，符合句意", "烹饪": "搭配：「烹饪」的对象是食材，不能说「烹饪势力」", "放牧": "语义：「放牧」指饲养牲畜，与「势力」不相容"}, "sentence_index": 6, "correct_answer": "削减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大火削减了整座房子。", "explanation": "这里应该用〈摧毁〉。削减指部分压缩，整座建筑被彻底毁掉要说摧毁"}, {"text": "我们终于削减了这次误会。", "explanation": "这里应该用〈消除〉。削减用于数量或权力的压缩，误会的化解要说消除"}, {"text": "医生削减了他的阑尾。", "explanation": "这里应该用〈切除〉。削减指压缩数量或权力，器官的摘除要说切除"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革把总统的权力削减很厉害。", "corrected_sentence": "这次改革把总统的权力削减得很厉害。", "error_description": "错误：「把」字句中「削减」后缺少「得」，「削减很厉害」不成立；正确：应说「削减得很厉害」，「得」引出程度补语", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国把各自的兵力削减。", "corrected_sentence": "两国把各自的兵力削减了。", "error_description": "错误：「把」字句中「削减」后缺少「了」，句子不完整；正确：应说「两国把各自的兵力削减了」，「把」字句的动词后通常要带「了」或补语", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
